// Count UTF-16 code units needed for a UTF-8 string
static int utf8_utf16_length(const char* s, int byte_len)
{
	int count = 0;
	int i = 0;
	while (i < byte_len)
	{
		unsigned char c = (unsigned char)s[i];
		if (c < 0x80) { count++; i++; }
		else if (c < 0xE0) { count++; i += 2; }
		else if (c < 0xF0) { count++; i += 3; }
		else { count += 2; i += 4; } // surrogate pair = 2 UTF-16 code units
	}
	return count;
}

// Decode one UTF-8 character, return code point, advance *pos
static uint32_t utf8_decode_one(const char* s, int byte_len, int* pos)
{
	unsigned char c = (unsigned char)s[*pos];
	uint32_t cp;
	if (c < 0x80) { cp = c; *pos += 1; }
	else if (c < 0xE0 && *pos + 1 < byte_len) {
		cp = ((uint32_t)(c & 0x1F) << 6) | (s[*pos+1] & 0x3F);
		*pos += 2;
	}
	else if (c < 0xF0 && *pos + 2 < byte_len) {
		cp = ((uint32_t)(c & 0x0F) << 12) | ((uint32_t)(s[*pos+1] & 0x3F) << 6) | (s[*pos+2] & 0x3F);
		*pos += 3;
	}
	else if (*pos + 3 < byte_len) {
		cp = ((uint32_t)(c & 0x07) << 18) | ((uint32_t)(s[*pos+1] & 0x3F) << 12) |
		     ((uint32_t)(s[*pos+2] & 0x3F) << 6) | (s[*pos+3] & 0x3F);
		*pos += 4;
	}
	else { cp = 0xFFFD; *pos += 1; }
	return cp;
}

// Convert UTF-8 to malloc-allocated UTF-16. Returns uint16_t*.
// Uses malloc (not heap_alloc) so that leaked strings don't exhaust the fixed heap arena.
uint16_t* utf8_to_u16(SWFAppContext* app_context, const char* utf8, u32 byte_len, u32* out_u16_len)
{
	(void)app_context;
	if (byte_len == 0 || utf8 == NULL) {
		*out_u16_len = 0;
		return (uint16_t*) u16_empty;
	}
	int count = utf8_utf16_length(utf8, (int)byte_len);
	uint16_t* result = (uint16_t*) malloc((count + 1) * sizeof(uint16_t));
	if (result == NULL) { *out_u16_len = 0; return (uint16_t*) u16_empty; }
	int u = 0, i = 0;
	while (i < (int)byte_len) {
		uint32_t cp = utf8_decode_one(utf8, (int)byte_len, &i);
		if (cp < 0x10000) {
			result[u++] = (uint16_t)cp;
		} else {
			uint32_t adj = cp - 0x10000;
			result[u++] = (uint16_t)(0xD800 | (adj >> 10));
			result[u++] = (uint16_t)(0xDC00 | (adj & 0x3FF));
		}
	}
	result[u] = 0;
	*out_u16_len = (u32)u;
	return result;
}

// Convert UTF-16 to UTF-8 in caller-provided buffer. Returns bytes written (not including NUL).
int u16_to_utf8(const uint16_t* u16, u32 u16_len, char* out, int out_size)
{
	if (out_size <= 0) return 0;
	if (u16 == NULL) { out[0] = '\0'; return 0; }
	int pos = 0;
	for (u32 i = 0; i < u16_len && pos < out_size - 1; i++) {
		uint16_t unit = u16[i];
		// Check for surrogate pair
		if (unit >= 0xD800 && unit <= 0xDBFF && i + 1 < u16_len) {
			uint16_t low = u16[i + 1];
			if (low >= 0xDC00 && low <= 0xDFFF) {
				uint32_t cp = 0x10000 + ((uint32_t)(unit - 0xD800) << 10) + (low - 0xDC00);
				if (pos + 4 > out_size - 1) break;
				out[pos++] = (char)(0xF0 | (cp >> 18));
				out[pos++] = (char)(0x80 | ((cp >> 12) & 0x3F));
				out[pos++] = (char)(0x80 | ((cp >> 6) & 0x3F));
				out[pos++] = (char)(0x80 | (cp & 0x3F));
				i++;
				continue;
			}
		}
		// Lone surrogate → U+FFFD
		if (unit >= 0xD800 && unit <= 0xDFFF) {
			if (pos + 3 > out_size - 1) break;
			out[pos++] = (char)0xEF;
			out[pos++] = (char)0xBF;
			out[pos++] = (char)0xBD;
			continue;
		}
		if (unit < 0x80) {
			out[pos++] = (char)unit;
		} else if (unit < 0x800) {
			if (pos + 2 > out_size - 1) break;
			out[pos++] = (char)(0xC0 | (unit >> 6));
			out[pos++] = (char)(0x80 | (unit & 0x3F));
		} else {
			if (pos + 3 > out_size - 1) break;
			out[pos++] = (char)(0xE0 | (unit >> 12));
			out[pos++] = (char)(0x80 | ((unit >> 6) & 0x3F));
			out[pos++] = (char)(0x80 | (unit & 0x3F));
		}
	}
	out[pos] = '\0';
	return pos;
}

// Decode a UTF-16 code unit (possibly surrogate pair) to a code point.
// Advances *idx past the consumed units. Returns the code point.
static inline uint32_t u16_decode_codepoint(const uint16_t* s, u32 len, u32* idx)
{
	uint16_t u = s[*idx];
	(*idx)++;
	if (u >= 0xD800 && u <= 0xDBFF && *idx < len) {
		uint16_t u2 = s[*idx];
		if (u2 >= 0xDC00 && u2 <= 0xDFFF) {
			(*idx)++;
			return 0x10000 + ((uint32_t)(u - 0xD800) << 10) + (u2 - 0xDC00);
		}
	}
	return u;
}

// Lexicographic comparison of two UTF-16 strings by raw code unit (Flash/ECMAScript semantics)
static int u16_cmp(const uint16_t* a, u32 a_len, const uint16_t* b, u32 b_len)
{
	u32 min_len = a_len < b_len ? a_len : b_len;
	for (u32 i = 0; i < min_len; i++) {
		if (a[i] != b[i]) return (int)a[i] - (int)b[i];
	}
	return (int)a_len - (int)b_len;
}

// Fast ASCII-to-UTF-16 conversion (for number strings which are always ASCII)
// Uses malloc (not heap_alloc) so leaked strings don't exhaust the fixed heap arena.
static uint16_t* ascii_to_u16(SWFAppContext* app_context, const char* ascii, int len, u32* out_len)
{
	(void)app_context;
	uint16_t* result = (uint16_t*) malloc((len + 1) * sizeof(uint16_t));
	if (result == NULL) { *out_len = 0; return (uint16_t*) u16_empty; }
	for (int i = 0; i < len; i++)
		result[i] = (uint16_t)(unsigned char)ascii[i];
	result[len] = 0;
	*out_len = (u32)len;
	return result;
}

// Get UTF-16 string pointer from ActionVar
const uint16_t* varGetU16Ptr(ActionVar* v)
{
	if (v->type != ACTION_STACK_VALUE_STRING) return NULL;
	return v->data.string_data.owns_memory ?
		v->data.string_data.heap_ptr : (const uint16_t*) v->data.numeric_value;
}

// Concatenate two UTF-16 strings into a new malloc-allocated buffer
static uint16_t* u16_concat(SWFAppContext* app_context, const uint16_t* a, u32 a_len,
                             const uint16_t* b, u32 b_len, u32* out_len)
{
	(void)app_context;
	u32 total = a_len + b_len;
	uint16_t* result = (uint16_t*) malloc((total + 1) * sizeof(uint16_t));
	if (result == NULL) {
		// OOM: return empty string to avoid segfault
		static uint16_t empty_u16 = 0;
		*out_len = 0;
		return &empty_u16;
	}
	if (a_len > 0) memcpy(result, a, a_len * sizeof(uint16_t));
	if (b_len > 0) memcpy(result + a_len, b, b_len * sizeof(uint16_t));
	result[total] = 0;
	*out_len = total;
	return result;
}

// push_str_id_fn: converts char* to UTF-16 (with caching for constant strings) and pushes onto stack
void push_str_id_fn(SWFAppContext* app_context, const char* str, u32 byte_len, u32 id)
{
	uint16_t* u16;
	u32 u16_len;

	if (id > 0 && app_context->max_string_id > 0 && id < app_context->max_string_id) {
		// Lazy-init cache on first use
		if (app_context->str_cache == NULL) {
			app_context->str_cache = (uint16_t**) calloc(app_context->max_string_id, sizeof(uint16_t*));
			app_context->str_cache_len = (u32*) calloc(app_context->max_string_id, sizeof(u32));
		}
		if (app_context->str_cache != NULL && app_context->str_cache[id] != NULL) {
			u16 = app_context->str_cache[id];
			u16_len = app_context->str_cache_len[id];
		} else {
			u16 = utf8_to_u16(app_context, str, byte_len, &u16_len);
			if (app_context->str_cache != NULL) {
				app_context->str_cache[id] = u16;
				app_context->str_cache_len[id] = u16_len;
			}
		}
	} else {
		if (byte_len == 0 || str == NULL) {
			u16 = (uint16_t*) u16_empty;
			u16_len = 0;
		} else {
			u16 = utf8_to_u16(app_context, str, byte_len, &u16_len);
		}
	}

	OLDSP = SP;
	SP -= 4 + 4 + 8 + 8;
	SP &= ~7;
	STACK[SP] = ACTION_STACK_VALUE_STRING;
	VAL(u32, &STACK[SP + 4]) = OLDSP;
	VAL(u32, &STACK[SP + 8]) = u16_len;
	VAL(u32, &STACK[SP + 12]) = id;
	VAL(u64, &STACK[SP + 16]) = (u64)u16;
}

// ==================================================================
// Scope Chain for WITH statement
// ==================================================================

// MAX_SCOPE_DEPTH is defined in action_internal.h
ASObject* scope_chain[MAX_SCOPE_DEPTH];
u8 scope_is_with[MAX_SCOPE_DEPTH];       // 1 = with scope, 0 = function scope
MovieClip* scope_mc[MAX_SCOPE_DEPTH];     // non-NULL if scope entry is a MovieClip
u32 scope_depth = 0;

// Exception handling infrastructure (setjmp/longjmp based try/catch)
#define MAX_EXCEPTION_DEPTH 16

typedef struct {
	jmp_buf handler;
	int has_jmp_buf;
	u32 saved_scope_depth;
} ExceptionFrame;

typedef struct {
	ExceptionFrame frames[MAX_EXCEPTION_DEPTH];
	int depth;

	bool exception_thrown;
	ActionVar exception_value;

	bool return_pending;
	ActionVar return_value;
} ExceptionState;

static ExceptionState g_exception_state = {0};

// Per-call-frame `this` binding stack (mirrors Ruffle's Activation.this)
// This is separate from the scope chain — GetVariable("this") checks this stack
// before the scope chain, matching Flash's behavior where `this` is not a scope property.
// MAX_THIS_DEPTH is defined in action_internal.h
ActionVar g_this_stack[MAX_THIS_DEPTH];
u32 g_this_depth = 0;

// Tracks the scope object on which the last GetVariable found a value via a WITH scope.
// Used by CallFunction to determine the correct `this` binding when a function is
// found on a scope chain entry (Ruffle: CallableValue::Callable(scope_obj, fn)).
// Reset to {.type = ACTION_STACK_VALUE_UNDEFINED} after each GetVariable call.
static ActionVar g_last_callable_this = {0};
static int g_last_callable_this_set = 0;
static int g_last_callable_this_is_with = 0;  // 1 if from a WITH scope entry

// Super context stack — tracks prototype chain depth for super() resolution.
// Ruffle model: super is a virtual (this, depth) pair. Depth indicates how many
// __proto__ levels to skip when resolving super properties/constructors.
// depth=1 means "start from this.__proto__" (i.e. the first parent class).
#define MAX_SUPER_DEPTH 64
static void* g_super_this_stack[MAX_SUPER_DEPTH];   // this binding for each super level (ASObject*)
static u8    g_super_depth_stack[MAX_SUPER_DEPTH];   // prototype chain depth
static void* g_super_mc_stack[MAX_SUPER_DEPTH];      // companion MovieClip* (for registerClass ctors)
static u32   g_super_stack_pos = 0;

static void pushSuperContext(void* this_obj, u8 depth) {
	if (g_super_stack_pos < MAX_SUPER_DEPTH) {
		g_super_this_stack[g_super_stack_pos] = this_obj;
		g_super_depth_stack[g_super_stack_pos] = depth;
		g_super_mc_stack[g_super_stack_pos] = NULL;
		g_super_stack_pos++;
	}
}

// Push super context with a companion MC pointer.
// Used by registerClass constructors where this_obj is mc->dynamic_props (for
// proto chain walking) but the parent constructor needs the actual MovieClip.
void pushSuperContextWithMC(void* this_obj, u8 depth, void* mc) {
	if (g_super_stack_pos < MAX_SUPER_DEPTH) {
		g_super_this_stack[g_super_stack_pos] = this_obj;
		g_super_depth_stack[g_super_stack_pos] = depth;
		g_super_mc_stack[g_super_stack_pos] = mc;
		g_super_stack_pos++;
	}
}

void popSuperContext(void) {
	if (g_super_stack_pos > 0) g_super_stack_pos--;
}

static int hasSuperContext(void) {
	return g_super_stack_pos > 0;
}

static void* getSuperThis(void) {
	return g_super_stack_pos > 0 ? g_super_this_stack[g_super_stack_pos - 1] : NULL;
}

static u8 getSuperDepth(void) {
	return g_super_stack_pos > 0 ? g_super_depth_stack[g_super_stack_pos - 1] : 0;
}

// Returns the companion MC if the super context was created by a registerClass constructor.
static void* getSuperMC(void) {
	return g_super_stack_pos > 0 ? g_super_mc_stack[g_super_stack_pos - 1] : NULL;
}

// Forward declare resolveProtoVar (defined below walkProtoChain)
void* resolveProtoVar(ActionVar* proto_var);

// Walk the __proto__ chain from 'this_obj' by 'depth' levels.
// Returns the prototype object at that depth, or NULL if chain is too short.
static ASObject* walkProtoChain(void* this_obj, u8 depth) {
	if (this_obj == NULL) return NULL;
	ASObject* current = (ASObject*) this_obj;
	for (u8 i = 0; i < depth; i++) {
		ActionVar* proto_var = getProperty(current, "__proto__", 9);
		current = (ASObject*) resolveProtoVar(proto_var);
		if (current == NULL) return NULL;
	}
	return current;
}

// Resolve a __proto__ ActionVar to an ASObject* (returned as void*).
// OBJECT → direct cast. SUPER → unwrap by walking this_ptr's proto chain.
void* resolveProtoVar(ActionVar* proto_var) {
	if (proto_var == NULL || proto_var->data.numeric_value == 0) return NULL;
	if (proto_var->type == ACTION_STACK_VALUE_OBJECT)
		return (void*) proto_var->data.numeric_value;
	if (proto_var->type == ACTION_STACK_VALUE_SUPER)
		return (void*) walkProtoChain((void*) proto_var->data.numeric_value, (u8) proto_var->str_size);
	return NULL;
}

// Get the "super proto" — the prototype where super methods are searched.
// This is this.__proto__^depth (i.e., walk depth levels up).
static ASObject* getSuperBaseProto(void) {
	if (g_super_stack_pos == 0) return NULL;
	void* this_obj = g_super_this_stack[g_super_stack_pos - 1];
	u8 depth = g_super_depth_stack[g_super_stack_pos - 1];
	return walkProtoChain(this_obj, depth);
}

// Get the prototype of the base proto — where super property/method searches start.
// This is this.__proto__^(depth+1).
static ASObject* getSuperSearchStart(void) {
	ASObject* base = getSuperBaseProto();
	if (base == NULL) return NULL;
	ActionVar* proto_var = getProperty(base, "__proto__", 9);
	return (ASObject*) resolveProtoVar(proto_var);
}

// Forward declarations for MC property helpers (defined in WITH section)
