// Object.registerClass(symbolName, constructorFunc)
// Returns true on success, false on invalid args.
static ActionVar actionObjectRegisterClass(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_BOOLEAN;

	// Need at least 2 args
	if (arg_count < 2)
	{
		result.data.numeric_value = 0; // false
		return result;
	}

	// Coerce first arg (symbol name) to string via the stack
	pushVar(app_context, &args[0]);
	char _rc_buf[17];
	convertString(app_context, _rc_buf);
	char symbol_buf[256];
	u32 sym_len = (u32)u16_to_utf8((const uint16_t*)STACK_TOP_VALUE, STACK_TOP_N, symbol_buf, sizeof(symbol_buf) - 1);
	symbol_buf[sym_len] = '\0';
	POP();

	// Second arg: null/undefined = unregister, function = register, anything else = false
	if (args[1].type == ACTION_STACK_VALUE_NULL || args[1].type == ACTION_STACK_VALUE_UNDEFINED)
	{
		// Unregister
		actionRegisterClassForSymbol(symbol_buf, NULL);
		result.data.numeric_value = 1; // true
		return result;
	}

	if (args[1].type != ACTION_STACK_VALUE_FUNCTION)
	{
		result.data.numeric_value = 0; // false
		return result;
	}

	ASFunction* ctor = (ASFunction*)(uintptr_t)args[1].data.numeric_value;
	actionRegisterClassForSymbol(symbol_buf, (void*)ctor);
	result.data.numeric_value = 1; // true
	return result;
}

// Built-in toString for Object(primitive) wrappers — returns valueOf as string
static ActionVar builtin_wrapper_toString(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 15;
	ret.data.numeric_value = (u64) u16_object_Object;

	if (this_obj != NULL)
	{
		ASObject* obj = (ASObject*) this_obj;
		ActionVar* val_prop = getProperty(obj, "valueOf", 7);
		if (val_prop != NULL && val_prop->type != ACTION_STACK_VALUE_FUNCTION)
		{
			char buf[64];
			int len = varToStringBuf(app_context, val_prop, buf, sizeof(buf));
			// Convert UTF-8 result to UTF-16 for storage
			u32 u16_len;
			uint16_t* u16_str = ascii_to_u16(app_context, buf, len, &u16_len);
			ret.data.string_data.heap_ptr = u16_str;
			ret.data.string_data.owns_memory = true;
			ret.str_size = u16_len;
		}
	}
	return ret;
}

static ActionVar builtin_object_toString(SWFAppContext* app_context)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	if (g_swf_version < 5) {
		// SWF4 and below uses "[type Object]" format for user-created objects
		ret.str_size = 13;
		ret.data.numeric_value = (u64) u16_type_Object;
	} else {
		// SWF5+ uses "[object Object]" format
		ret.str_size = 15;
		ret.data.numeric_value = (u64) u16_object_Object;
	}
	return ret;
}

