// TextSnapshot.hitTestTextNearPos(x, y[, closeDist]) — always returns a number (stub).
// Real method returns index of character closest to (x, y) within closeDist, or -1.
// With >3 args it returns undefined (matches Flash's arg-count gate).
static ActionVar builtin_ts_hitTestTextNearPos(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)registers; (void)this_obj;
	ActionVar ret = {0};
	if (arg_count >= 2 && arg_count <= 3) {
		ret.type = ACTION_STACK_VALUE_F64;
		VAL(double, &ret.data.numeric_value) = -1.0;
	} else {
		ret.type = ACTION_STACK_VALUE_UNDEFINED;
	}
	return ret;
}

// TextSnapshot.getText(start, end[, includeNewlines]) — extract substring
static ActionVar builtin_ts_getText(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count < 2 || arg_count > 3) return ret;

	ASObject* obj = (ASObject*)this_obj;
	if (!obj) return ret;
	// Non-native TextSnapshots return undefined regardless of args.
	if (obj->native_type != NATIVE_TEXTSNAPSHOT) return ret;

	ActionVar* tv = getProperty(obj, "__ts_text__", 11);
	ActionVar* cv = getProperty(obj, "__ts_count__", 12);
	ActionVar* nv = getProperty(obj, "__ts_nl__", 9);

	// Native TextSnapshot with empty/missing text: return empty string
	// (matches Ruffle: TextSnapshot::get_text returns WString::new() for
	// count==0).
	if (!tv || tv->type != ACTION_STACK_VALUE_STRING || !cv || cv->type != ACTION_STACK_VALUE_F64) {
		ret.type = ACTION_STACK_VALUE_STRING;
		ret.str_size = 0;
		ret.data.numeric_value = (u64) u16_empty;
		return ret;
	}

	const uint16_t* text = varGetU16Ptr(tv);
	int count = (int)VAL(double, &cv->data.numeric_value);
	const uint16_t* nl_flags = (nv && nv->type == ACTION_STACK_VALUE_STRING) ? varGetU16Ptr(nv) : NULL;
	if (!text || count == 0) {
		ret.type = ACTION_STACK_VALUE_STRING;
		ret.str_size = 0;
		ret.data.numeric_value = (u64) u16_empty;
		return ret;
	}

	int start = (int)tsArgToDouble_ctx(app_context, &args[0]);
	int end = (int)tsArgToDouble_ctx(app_context, &args[1]);
	int include_nl = (arg_count >= 3) ? tsArgTruthy(&args[2]) : 0;

	// Clamp
	if (start < 0) start = 0;
	if (start >= count) start = count - 1;
	if (end < 0) end = 0;
	if (end > count) end = count;

	// Build result
	uint16_t result[8192];
	size_t rlen = 0;

	if (start < end) {
		for (int i = start; i < end && rlen < 8190; i++) {
			if (include_nl && nl_flags && nl_flags[i] == '1')
				result[rlen++] = '\n';
			result[rlen++] = text[i];
		}
	} else {
		// start >= end: return single char at position start
		if (include_nl && nl_flags && nl_flags[start] == '1')
			result[rlen++] = '\n';
		result[rlen++] = text[start];
	}

	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = (u32)rlen;
	ret.data.string_data.heap_ptr = (uint16_t*)malloc( (rlen + 1) * sizeof(uint16_t));
	memcpy(ret.data.string_data.heap_ptr, result, rlen * sizeof(uint16_t));
	ret.data.string_data.heap_ptr[rlen] = 0;
	ret.data.string_data.owns_memory = true;
	return ret;
}

// TextSnapshot.findText(startIndex, textToFind, caseSensitive) — search for text
static ActionVar builtin_ts_findText(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count != 3) return ret;

	ASObject* obj = (ASObject*)this_obj;
	if (!obj) return ret;

	ActionVar* tv = getProperty(obj, "__ts_text__", 11);
	ActionVar* cv = getProperty(obj, "__ts_count__", 12);
	if (!tv || tv->type != ACTION_STACK_VALUE_STRING || !cv || cv->type != ACTION_STACK_VALUE_F64)
		return ret;

	const uint16_t* text = varGetU16Ptr(tv);
	int count = (int)VAL(double, &cv->data.numeric_value);
	if (!text) return ret;

	int start_idx = (int)tsArgToDouble_ctx(app_context, &args[0]);

	// Get search text — coerce to string via stack if needed (handles objects with toString)
	const uint16_t* search = NULL;
	u32 search_len = 0;
	int search_pushed = 0;
	if (args[1].type == ACTION_STACK_VALUE_STRING) {
		search = varGetU16Ptr(&args[1]);
		search_len = args[1].str_size;
	} else if (args[1].type == ACTION_STACK_VALUE_OBJECT || args[1].type == ACTION_STACK_VALUE_ARRAY ||
	           args[1].type == ACTION_STACK_VALUE_F64 || args[1].type == ACTION_STACK_VALUE_F32 ||
	           args[1].type == ACTION_STACK_VALUE_BOOLEAN) {
		// Push to stack and call convertString for coercion
		PUSH(args[1].type, args[1].data.numeric_value);
		STACK_TOP_N = args[1].str_size;
		char tmp[256];
		convertString(app_context, tmp);
		if (STACK_TOP_TYPE == ACTION_STACK_VALUE_STRING) {
			search = varGetU16Ptr((ActionVar*)(STACK + SP));
			search_len = STACK_TOP_N;
			search_pushed = 1;
		} else {
			POP();
		}
	}

	int case_sensitive = tsArgTruthy(&args[2]);

	// Empty search string → -1
	if (search_len == 0 || !search) {
		if (search_pushed) POP();
		ret.type = ACTION_STACK_VALUE_F64;
		VAL(double, &ret.data.numeric_value) = -1.0;
		return ret;
	}

	// Negative or out-of-bounds start → -1
	if (start_idx < 0 || start_idx >= count) {
		if (search_pushed) POP();
		ret.type = ACTION_STACK_VALUE_F64;
		VAL(double, &ret.data.numeric_value) = -1.0;
		return ret;
	}

	// Search
	ret.type = ACTION_STACK_VALUE_F64;
	VAL(double, &ret.data.numeric_value) = -1.0;

	for (int i = start_idx; i <= count - (int)search_len; i++) {
		int match = 1;
		for (u32 j = 0; j < search_len; j++) {
			uint16_t a = text[i + j];
			uint16_t b = search[j];
			if (!case_sensitive) {
				if (a >= 'A' && a <= 'Z') a += 32;
				if (b >= 'A' && b <= 'Z') b += 32;
			}
			if (a != b) { match = 0; break; }
		}
		if (match) {
			VAL(double, &ret.data.numeric_value) = (double)i;
			break;
		}
	}

	if (search_pushed) POP();
	return ret;
}

// Helper: resolve Sound this_obj, falling back to g_event_this_mc->dynamic_props
// when called from MOVIECLIP method dispatch (which passes this_obj=NULL)
static ASObject* resolveSoundThis(void* this_obj)
{
	if (this_obj != NULL) return (ASObject*)this_obj;
	extern MovieClip* g_event_this_mc;
	if (g_event_this_mc != NULL && g_event_this_mc->dynamic_props != NULL)
		return (ASObject*)g_event_this_mc->dynamic_props;
	return NULL;
}

// Global sound transform — shared by all Sound objects with no owner (new Sound())
static ASObject* g_sound_global_transform = NULL;

// Helper: initialize default sound transform properties on an object
static void initSoundTransformDefaults(SWFAppContext* app_context, ASObject* obj)
{
	ActionVar vol = {0};
	vol.type = ACTION_STACK_VALUE_F64;
	VAL(double, &vol.data.numeric_value) = 100.0;
	setPropertyWithFlags(app_context, obj, "__volume__", 10, &vol, PROPERTY_FLAGS_DONTENUM);
	ActionVar v = {0};
	v.type = ACTION_STACK_VALUE_F64;
	VAL(double, &v.data.numeric_value) = 100.0;
	setPropertyWithFlags(app_context, obj, "__ll__", 6, &v, PROPERTY_FLAGS_DONTENUM);
	VAL(double, &v.data.numeric_value) = 0.0;
	setPropertyWithFlags(app_context, obj, "__lr__", 6, &v, PROPERTY_FLAGS_DONTENUM);
	setPropertyWithFlags(app_context, obj, "__rl__", 6, &v, PROPERTY_FLAGS_DONTENUM);
	VAL(double, &v.data.numeric_value) = 100.0;
	setPropertyWithFlags(app_context, obj, "__rr__", 6, &v, PROPERTY_FLAGS_DONTENUM);
}

// Helper: resolve the transform-holding object for a Sound instance.
// If Sound has an owner MC → returns MC's dynamic_props (shared per-MC transform).
// If no owner → returns global transform object (shared among all ownerless Sounds).
static ASObject* resolveSoundTransformTarget(SWFAppContext* app_context, void* this_obj)
{
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL) return NULL;

	// Only Sound objects (native_type == NATIVE_SOUND) participate in shared transform
	if (sound_obj->native_type != NATIVE_SOUND) return NULL;

	// Check for owner MC
	ActionVar* owner = getProperty(sound_obj, "__sound_owner__", 15);
	if (owner != NULL && owner->type == ACTION_STACK_VALUE_MOVIECLIP) {
		MovieClip* mc = (MovieClip*)(uintptr_t) owner->data.numeric_value;
		if (mc != NULL) {
			// Ensure dynamic_props exists on the MC
			if (mc->dynamic_props == NULL) {
				mc->dynamic_props = (void*) allocObject(app_context, 8);
				retainObject((ASObject*) mc->dynamic_props);
			}
			// Initialize MC's sound transform if not yet done
			ActionVar* existing = getProperty((ASObject*)mc->dynamic_props, "__volume__", 10);
			if (existing == NULL) {
				initSoundTransformDefaults(app_context, (ASObject*)mc->dynamic_props);
			}
			return (ASObject*)mc->dynamic_props;
		}
	}

	// No owner → use global transform (lazy init)
	if (g_sound_global_transform == NULL) {
		g_sound_global_transform = allocObject(app_context, 8);
		retainObject(g_sound_global_transform);
		initSoundTransformDefaults(app_context, g_sound_global_transform);
	}
	return g_sound_global_transform;
}

// Helper: convert ActionVar to int32 for Sound methods using clamp_to_i32 semantics
// (matches Ruffle: if in [INT32_MIN, INT32_MAX] → cast, else → INT32_MIN. NaN → INT32_MIN)
static int32_t soundArgToInt32(ActionVar* arg)
{
	double d = 0.0;
	if (arg->type == ACTION_STACK_VALUE_F64) d = VAL(double, &arg->data.numeric_value);
	else if (arg->type == ACTION_STACK_VALUE_F32) d = (double)VAL(float, &arg->data.numeric_value);
	else if (arg->type == ACTION_STACK_VALUE_BOOLEAN) d = arg->data.numeric_value ? 1.0 : 0.0;
	else if (arg->type == ACTION_STACK_VALUE_STRING) {
		const uint16_t* u16 = varGetU16Ptr(arg);
		if (u16 != NULL && arg->str_size > 0) {
			char buf[64]; u16_to_utf8(u16, arg->str_size, buf, sizeof(buf));
			d = strtod(buf, NULL);
		}
	}
	// clamp_to_i32: NaN and out-of-range values → INT32_MIN
	if (d >= (double)INT32_MIN && d <= (double)INT32_MAX) return (int32_t)d;
	return INT32_MIN;
}

// Helper: read internal sound transform property as int32
static int32_t readSoundProp(ASObject* obj, const char* name, u32 len)
{
	ActionVar* v = getPropertyWithPrototype(obj, name, len);
	if (v == NULL) return 0;
	if (v->type == ACTION_STACK_VALUE_F64) return (int32_t)VAL(double, &v->data.numeric_value);
	if (v->type == ACTION_STACK_VALUE_F32) return (int32_t)VAL(float, &v->data.numeric_value);
	return 0;
}

// Helper: write internal sound transform property
static void writeSoundProp(SWFAppContext* app_context, ASObject* obj, const char* name, u32 len, int32_t val)
{
	ActionVar v = {0};
	v.type = ACTION_STACK_VALUE_F64;
	VAL(double, &v.data.numeric_value) = (double)val;
	setPropertyWithFlags(app_context, obj, name, len, &v, PROPERTY_FLAGS_DONTENUM);
}

// Sound.getVolume() - returns the __volume__ property (default 100)
static ActionVar builtin_sound_getVolume(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	ActionVar* vol = getPropertyWithPrototype(obj, "__volume__", 10);
	if (vol != NULL) {
		ret = *vol;
	}
	return ret;
}

// Sound.setVolume(vol) - sets the __volume__ property
static ActionVar builtin_sound_setVolume(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	ActionVar vol_var = {0};
	vol_var.type = ACTION_STACK_VALUE_F64;
	if (arg_count >= 1) {
		int32_t vol = soundArgToInt32(&args[0]);
		VAL(double, &vol_var.data.numeric_value) = (double)vol;
	} else {
		// Flash: setVolume() with no args sets volume to 0
		VAL(double, &vol_var.data.numeric_value) = 0.0;
	}
	setPropertyWithFlags(app_context, obj, "__volume__", 10, &vol_var, PROPERTY_FLAGS_DONTENUM);
	return ret;
}

// Sound.getPan() - returns pan value derived from ll/rr transform
static ActionVar builtin_sound_getPan(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	int32_t ll = readSoundProp(obj, "__ll__", 6);
	int32_t rr = readSoundProp(obj, "__rr__", 6);
	// Ruffle formula: if ll != 100: pan = 100 - abs(ll); else: pan = abs(rr) - 100
	int32_t pan;
	if (ll != 100) {
		pan = 100 - (ll < 0 ? -ll : ll);
	} else {
		pan = (rr < 0 ? -rr : rr) - 100;
	}
	ret.type = ACTION_STACK_VALUE_F64;
	VAL(double, &ret.data.numeric_value) = (double)pan;
	return ret;
}

// Sound.setPan(pan) - sets stereo pan by adjusting ll/rr
static ActionVar builtin_sound_setPan(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	if (arg_count < 1) return ret;
	int32_t pan = soundArgToInt32(&args[0]);
	// Ruffle formula for setPan:
	// If pan >= 0: ll = 100 - pan, rr = 100
	// If pan < 0:  ll = 100, rr = 100 + pan
	// lr = 0, rl = 0 always
	int32_t ll, rr;
	if (pan >= 0) {
		ll = 100 - pan;
		rr = 100;
	} else {
		ll = 100;
		rr = 100 + pan;
	}
	writeSoundProp(app_context, obj, "__ll__", 6, ll);
	writeSoundProp(app_context, obj, "__lr__", 6, 0);
	writeSoundProp(app_context, obj, "__rl__", 6, 0);
	writeSoundProp(app_context, obj, "__rr__", 6, rr);
	return ret;
}

// Sound.getTransform() - returns transform object {ll, lr, rl, rr}
static ActionVar builtin_sound_getTransform(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	ASObject* result = allocObject(app_context, 8);
	setObjectProto(app_context, result);
	ActionVar v = {0};
	v.type = ACTION_STACK_VALUE_F64;
	VAL(double, &v.data.numeric_value) = (double)readSoundProp(obj, "__ll__", 6);
	setProperty(app_context, result, "ll", 2, &v);
	VAL(double, &v.data.numeric_value) = (double)readSoundProp(obj, "__lr__", 6);
	setProperty(app_context, result, "lr", 2, &v);
	VAL(double, &v.data.numeric_value) = (double)readSoundProp(obj, "__rl__", 6);
	setProperty(app_context, result, "rl", 2, &v);
	VAL(double, &v.data.numeric_value) = (double)readSoundProp(obj, "__rr__", 6);
	setProperty(app_context, result, "rr", 2, &v);
	ret.type = ACTION_STACK_VALUE_OBJECT;
	ret.data.numeric_value = (u64)result;
	return ret;
}

// Sound.setTransform(transformObj) - sets stereo transform from object with ll/lr/rl/rr
static ActionVar builtin_sound_setTransform(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* obj = resolveSoundTransformTarget(app_context, this_obj);
	if (obj == NULL) return ret;
	if (arg_count < 1) return ret;
	// Argument must be an object; read ll, lr, rl, rr properties
	ASObject* tfm = NULL;
	if (args[0].type == ACTION_STACK_VALUE_OBJECT)
		tfm = (ASObject*) args[0].data.numeric_value;
	if (tfm == NULL) return ret;
	// Only update OWN properties on the transform object (has_own_property, not prototype chain)
	ActionVar* p;
	p = getProperty(tfm, "ll", 2);
	if (p != NULL) {
		double d = 0.0;
		if (p->type == ACTION_STACK_VALUE_F64) d = VAL(double, &p->data.numeric_value);
		else if (p->type == ACTION_STACK_VALUE_F32) d = (double)VAL(float, &p->data.numeric_value);
		writeSoundProp(app_context, obj, "__ll__", 6, ecmaToInt32(d));
	}
	p = getProperty(tfm, "lr", 2);
	if (p != NULL) {
		double d = 0.0;
		if (p->type == ACTION_STACK_VALUE_F64) d = VAL(double, &p->data.numeric_value);
		else if (p->type == ACTION_STACK_VALUE_F32) d = (double)VAL(float, &p->data.numeric_value);
		writeSoundProp(app_context, obj, "__lr__", 6, ecmaToInt32(d));
	}
	p = getProperty(tfm, "rl", 2);
	if (p != NULL) {
		double d = 0.0;
		if (p->type == ACTION_STACK_VALUE_F64) d = VAL(double, &p->data.numeric_value);
		else if (p->type == ACTION_STACK_VALUE_F32) d = (double)VAL(float, &p->data.numeric_value);
		writeSoundProp(app_context, obj, "__rl__", 6, ecmaToInt32(d));
	}
	p = getProperty(tfm, "rr", 2);
	if (p != NULL) {
		double d = 0.0;
		if (p->type == ACTION_STACK_VALUE_F64) d = VAL(double, &p->data.numeric_value);
		else if (p->type == ACTION_STACK_VALUE_F32) d = (double)VAL(float, &p->data.numeric_value);
		writeSoundProp(app_context, obj, "__rr__", 6, ecmaToInt32(d));
	}
	return ret;
}

// Sound.attachSound(id) - look up sound by export name, store duration
static ActionVar builtin_sound_attachSound(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL || arg_count < 1) return ret;
	// Coerce first arg to string (export name)
	char name_buf[256];
	if (args[0].type == ACTION_STACK_VALUE_STRING) {
		u16_to_utf8((const uint16_t*)args[0].data.numeric_value, args[0].str_size, name_buf, sizeof(name_buf));
	} else {
		return ret;
	}
	// Look up export name → char_id
	size_t char_id = ng_lookupExport(name_buf);
	if (char_id == (size_t)-1) return ret;
	// Look up char_id → duration
	int32_t dur_ms = ng_getSoundDuration((u16)char_id);
	if (dur_ms >= 0) {
		ActionVar dur_var = {0};
		dur_var.type = ACTION_STACK_VALUE_F64;
		VAL(double, &dur_var.data.numeric_value) = (double)dur_ms;
		setPropertyWithFlags(app_context, sound_obj, "__duration__", 12, &dur_var, PROPERTY_FLAGS_DONTENUM);
		setPropertyWithFlags(app_context, sound_obj, "duration", 8, &dur_var, PROPERTY_FLAGS_DONTENUM);
	}
	return ret;
}

// Sound.getDuration() - returns duration of attached sound
static ActionVar builtin_sound_getDuration(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL) return ret;
	ActionVar* dur = getProperty(sound_obj, "__duration__", 12);
	if (dur != NULL) ret = *dur;
	return ret;
}

// Forward declarations for sound playback
static void soundStartPlayback(ASObject* sound_obj, double duration_ms);
static void soundStopForObject(ASObject* sound_obj);
static void soundFireCallback(SWFAppContext* app_context, ASObject* sound_obj, const char* name, u32 name_len, ActionVar* cb_args, u32 cb_arg_count);
static double soundGetElapsedForObject(ASObject* sound_obj);

// --- ID3v2 tag parser ---

static ActionVar builtin_id3_valueOf(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	return ret;
}

static ASFunction g_id3_valueof_func = {0};

static const char* id3_get_alias(const char* fid)
{
	if (memcmp(fid, "TIT2", 4) == 0) return "songname";
	if (memcmp(fid, "TPE1", 4) == 0) return "artist";
	if (memcmp(fid, "TALB", 4) == 0) return "album";
	if (memcmp(fid, "TYER", 4) == 0) return "year";
	if (memcmp(fid, "TCON", 4) == 0) return "genre";
	if (memcmp(fid, "TRCK", 4) == 0) return "track";
	return NULL;
}

// Decode ID3v2 text encoding to UTF-8. Returns bytes written (excluding NUL).
static int id3_decode_text(const unsigned char* data, int data_len, int encoding, char* out, int out_size)
{
	int pos = 0;
	if (encoding == 0 || encoding == 3)
	{
		// Latin1 (0) or UTF-8 (3): copy bytes
		for (int i = 0; i < data_len && pos < out_size - 1; i++)
		{
			if (data[i] == '\0') break;
			out[pos++] = (char)data[i];
		}
	}
	else if (encoding == 1 || encoding == 2)
	{
		// UTF-16 with BOM (1) or UTF-16BE (2)
		int le = 0;
		const unsigned char* src = data;
		int src_len = data_len;
		if (encoding == 1 && src_len >= 2)
		{
			int bom = (src[0] << 8) | src[1];
			le = (bom == 0xFFFE);
			src += 2; src_len -= 2;
		}
		for (int i = 0; i + 1 < src_len && pos < out_size - 4; i += 2)
		{
			uint16_t ch = le ? (src[i] | (src[i+1] << 8)) : ((src[i] << 8) | src[i+1]);
			if (ch == 0) break;
			if (ch < 0x80) out[pos++] = (char)ch;
			else if (ch < 0x800) { out[pos++] = (char)(0xC0 | (ch >> 6)); out[pos++] = (char)(0x80 | (ch & 0x3F)); }
			else { out[pos++] = (char)(0xE0 | (ch >> 12)); out[pos++] = (char)(0x80 | ((ch >> 6) & 0x3F)); out[pos++] = (char)(0x80 | (ch & 0x3F)); }
		}
	}
	out[pos] = '\0';
	return pos;
}

// Parse COMM frame text (skip language + short description)
static int id3_decode_comm(const unsigned char* frame_data, int frame_size, char* out, int out_size)
{
	if (frame_size < 5) return 0;
	int encoding = frame_data[0];
	// Skip language (3 bytes)
	const unsigned char* rest = frame_data + 4;
	int rest_len = frame_size - 4;

	if (encoding == 0 || encoding == 3)
	{
		// Latin1/UTF-8: find null terminator of short description
		int i = 0;
		while (i < rest_len && rest[i] != '\0') i++;
		if (i < rest_len) i++; // skip null
		return id3_decode_text(rest + i, rest_len - i, encoding, out, out_size);
	}
	else if (encoding == 1 || encoding == 2)
	{
		// UTF-16: skip BOM for description, find double-null, then decode text portion
		const unsigned char* scan = rest;
		int scan_len = rest_len;
		int le = 0;
		if (encoding == 1 && scan_len >= 2) {
			le = ((scan[0] << 8) | scan[1]) == 0xFFFE;
			scan += 2; scan_len -= 2;
		}
		// Find null terminator (two zero bytes aligned)
		while (scan_len >= 2)
		{
			uint16_t ch = le ? (scan[0] | (scan[1] << 8)) : ((scan[0] << 8) | scan[1]);
			scan += 2; scan_len -= 2;
			if (ch == 0) break;
		}
		// scan now points to text portion (may have its own BOM)
		return id3_decode_text(scan, scan_len, encoding, out, out_size);
	}
	return 0;
}

static ActionVar makeStringFromUTF8(SWFAppContext* app_context, const char* utf8, int utf8_len)
{
	ActionVar v = {0};
	v.type = ACTION_STACK_VALUE_STRING;
	u32 u16len = 0;
	uint16_t* u16str = utf8_to_u16(app_context, utf8, (u32)utf8_len, &u16len);
	v.str_size = u16len;
	VAL(u64, &v.data.numeric_value) = (u64)u16str;
	return v;
}

// Parse ID3v2 tags from MP3 data, returns ASObject* with tag properties (or NULL)
static ASObject* parseID3v2Tags(SWFAppContext* app_context, const unsigned char* data, int data_len)
{
	if (data_len < 10 || data[0] != 'I' || data[1] != 'D' || data[2] != '3') return NULL;
	if (data[3] < 3) return NULL; // only v2.3+

	int tag_size = ((data[6] & 0x7F) << 21) | ((data[7] & 0x7F) << 14) |
	               ((data[8] & 0x7F) << 7) | (data[9] & 0x7F);
	int end = 10 + tag_size;
	if (end > data_len) end = data_len;

	// Collect text frames and COMM entries
	#define MAX_ID3_FRAMES 64
	#define MAX_ID3_COMM 8
	typedef struct { char fid[5]; char text[512]; } ID3Frame;
	ID3Frame frames[MAX_ID3_FRAMES];
	int frame_count = 0;
	char comm_texts[MAX_ID3_COMM][512];
	int comm_count = 0;
	int first_comm_slot = -1;

	int pos = 10;
	while (pos + 10 <= end && frame_count < MAX_ID3_FRAMES)
	{
		char fid[5] = {(char)data[pos], (char)data[pos+1], (char)data[pos+2], (char)data[pos+3], 0};
		if (fid[0] == '\0') break; // padding

		int fsize = (int)((data[pos+4] << 24) | (data[pos+5] << 16) | (data[pos+6] << 8) | data[pos+7]);
		if (fsize <= 0 || pos + 10 + fsize > end) break;
		const unsigned char* fdata = data + pos + 10;
		pos += 10 + fsize;

		if (fid[0] == 'T' && fsize >= 2)
		{
			// Text frame
			memcpy(frames[frame_count].fid, fid, 5);
			id3_decode_text(fdata + 1, fsize - 1, fdata[0], frames[frame_count].text, 512);
			frame_count++;
		}
		else if (memcmp(fid, "COMM", 4) == 0)
		{
			if (first_comm_slot == -1) {
				memcpy(frames[frame_count].fid, "COMM", 5);
				frames[frame_count].text[0] = '\0';
				first_comm_slot = frame_count;
				frame_count++;
			}
			if (comm_count < MAX_ID3_COMM)
				id3_decode_comm(fdata, fsize, comm_texts[comm_count++], 512);
		}
		// Skip URL frames (WOAR etc.) and other non-text frames
	}

	if (frame_count == 0) return NULL;

	ASObject* id3 = allocObject(app_context, (u32)(frame_count * 3 + 4));

	// valueOf → undefined (makes id3 == undefined true, trace(id3) = "undefined")
	if (g_id3_valueof_func.function_type == 0) {
		g_id3_valueof_func.function_type = 2;
		g_id3_valueof_func.advanced_func = builtin_id3_valueOf;
	}
	ActionVar vof = {0}; vof.type = ACTION_STACK_VALUE_FUNCTION;
	vof.data.numeric_value = (u64)(uintptr_t)&g_id3_valueof_func;
	setPropertyWithFlags(app_context, id3, "valueOf", 7, &vof, PROPERTY_FLAGS_DONTENUM);

	// Add properties in file order (for-in is LIFO: last-added = first-iterated).
	// Within each pair: alias first (lower index), then frame code (higher index),
	// so for-in returns: frame code, alias (matching Flash/Ruffle order).
	for (int i = 0; i < frame_count; i++)
	{
		if (i == first_comm_slot && comm_count > 0)
		{
			// "comment" alias first (lower index → popped later → appears after COMM)
			ActionVar cv = makeStringFromUTF8(app_context, comm_texts[comm_count - 1], (int)strlen(comm_texts[comm_count - 1]));
			setProperty(app_context, id3, "comment", 7, &cv);
			// COMM → ASArray of comment texts
			ASArray* arr = allocArray(app_context, (u32)(comm_count > 0 ? comm_count : 1));
			arr->length = (u32)comm_count;
			for (int j = 0; j < comm_count; j++)
				arr->elements[j] = makeStringFromUTF8(app_context, comm_texts[j], (int)strlen(comm_texts[j]));
			ActionVar av = {0}; av.type = ACTION_STACK_VALUE_ARRAY;
			av.data.numeric_value = (u64)(uintptr_t)arr;
			setProperty(app_context, id3, "COMM", 4, &av);
		}
		else if (i != first_comm_slot)
		{
			const char* alias = id3_get_alias(frames[i].fid);
			if (alias) {
				ActionVar av = makeStringFromUTF8(app_context, frames[i].text, (int)strlen(frames[i].text));
				setProperty(app_context, id3, alias, (u32)strlen(alias), &av);
			}
			ActionVar sv = makeStringFromUTF8(app_context, frames[i].text, (int)strlen(frames[i].text));
			setProperty(app_context, id3, frames[i].fid, 4, &sv);
		}
	}

	#undef MAX_ID3_FRAMES
	#undef MAX_ID3_COMM
	return id3;
}

static ActionVar builtin_sound_loadSound(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL || arg_count < 1) return ret;

	// Get URL string
	if (args[0].type != ACTION_STACK_VALUE_STRING) return ret;
	const uint16_t* u16 = varGetU16Ptr(&args[0]);
	if (!u16) return ret;
	char url[256];
	u16_to_utf8(u16, args[0].str_size, url, sizeof(url));

	// Stop any currently playing instances of this sound
	soundStopForObject(sound_obj);

	// Snapshot pre-loadSound string own properties (Place 0 pattern)
	ASProperty* pre_dur_p = findPropertyRaw(sound_obj, "duration", 8);
	int pre_had_str_dur = (pre_dur_p != NULL && pre_dur_p->value.type == ACTION_STACK_VALUE_STRING);
	ActionVar pre_str_dur = {0}; if (pre_had_str_dur) pre_str_dur = pre_dur_p->value;

	ASProperty* pre_pos_p = findPropertyRaw(sound_obj, "position", 8);
	int pre_had_str_pos = (pre_pos_p != NULL && pre_pos_p->value.type == ACTION_STACK_VALUE_STRING);
	ActionVar pre_str_pos = {0}; if (pre_had_str_pos) pre_str_pos = pre_pos_p->value;

	// Snapshot pre-loadSound id3 own property (Place 0 pattern)
	ASProperty* pre_id3_p = findPropertyRaw(sound_obj, "id3", 3);
	int pre_had_id3 = (pre_id3_p != NULL && pre_id3_p->value.type == ACTION_STACK_VALUE_STRING);
	ActionVar pre_id3_val = {0}; if (pre_had_id3) pre_id3_val = pre_id3_p->value;

	// Clear previous duration (in case new load fails)
	{
		ActionVar zero_dur = {0}; zero_dur.type = ACTION_STACK_VALUE_F64;
		VAL(double, &zero_dur.data.numeric_value) = 0;
		setProperty(app_context, sound_obj, "__duration__", 12, &zero_dur);
	}

	// Look up in data registry
#ifdef HAS_DATA_FILES
	// Strip path, match basename
	const char* basename = url;
	for (const char* p = url; *p; p++)
		if (*p == '/' || *p == '\\') basename = p + 1;

	DataFileEntry* entry = findDataFile(basename);
	if (entry == NULL) return ret;

	// Estimate MP3 duration from file size
	// Simple heuristic for CBR MP3: parse first frame header for bitrate
	const unsigned char* mp3 = (const unsigned char*)entry->content;
	int mp3_len = entry->content_length;
	double duration_ms = 0;

	// Parse ID3v2 tags and skip header
	ASObject* id3_obj = parseID3v2Tags(app_context, mp3, mp3_len);
	int audio_offset = 0;
	if (mp3_len >= 10 && mp3[0] == 'I' && mp3[1] == 'D' && mp3[2] == '3')
	{
		int id3_size = ((mp3[6] & 0x7F) << 21) | ((mp3[7] & 0x7F) << 14) |
		               ((mp3[8] & 0x7F) << 7) | (mp3[9] & 0x7F);
		audio_offset = id3_size + 10;
		mp3 += audio_offset;
		mp3_len -= audio_offset;
	}

	// Store parsed ID3 object (or clear previous)
	if (id3_obj != NULL) {
		ActionVar id3_var = {0}; id3_var.type = ACTION_STACK_VALUE_OBJECT;
		id3_var.data.numeric_value = (u64)(uintptr_t)id3_obj;
		setPropertyWithFlags(app_context, sound_obj, "__id3__", 7, &id3_var, PROPERTY_FLAGS_DONTENUM);
		if (pre_had_id3) {
			setPropertyWithFlags(app_context, sound_obj, "__id3_override__", 16, &pre_id3_val, PROPERTY_FLAGS_DONTENUM);
		}
	}

	if (mp3_len >= 4 && mp3[0] == 0xFF && (mp3[1] & 0xE0) == 0xE0)
	{
		// MPEG audio frame header
		int version = (mp3[1] >> 3) & 3; // 0=2.5, 2=2, 3=1
		int layer = (mp3[1] >> 1) & 3;   // 1=III, 2=II, 3=I
		int br_idx = (mp3[2] >> 4) & 0xF;
		int sr_idx = (mp3[2] >> 2) & 3;

		// Bitrate table for MPEG1 Layer III
		static const int bitrates_v1_l3[] = {0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0};
		// Sample rate table for MPEG1
		static const int samplerates_v1[] = {44100, 48000, 32000, 0};

		int bitrate = 0;
		if (version == 3 && layer == 1) // MPEG1 Layer III
			bitrate = bitrates_v1_l3[br_idx] * 1000;
		else if (version == 3 && layer == 2) { // MPEG1 Layer II
			static const int bitrates_v1_l2[] = {0,32,48,56,64,80,96,112,128,160,192,224,256,320,384,0};
			bitrate = bitrates_v1_l2[br_idx] * 1000;
		}

		if (bitrate > 0)
			duration_ms = (double)mp3_len * 8.0 / (double)bitrate * 1000.0;
		else
			duration_ms = 1000.0; // fallback
	}
	else
	{
		duration_ms = 1000.0; // fallback for non-standard MP3
	}

	// Store duration on the Sound instance
	ActionVar dur_val = {0};
	dur_val.type = ACTION_STACK_VALUE_F64;
	VAL(double, &dur_val.data.numeric_value) = duration_ms;
	setProperty(app_context, sound_obj, "__duration__", 12, &dur_val);

	// Set position to 0 (not playing yet)
	{
		ActionVar pos = {0}; pos.type = ACTION_STACK_VALUE_F64;
		setProperty(app_context, sound_obj, "__position__", 12, &pos);
	}

	// Mark as loaded (activates native getters for duration/position)
	// If pre-loadSound string overrides exist, set __dur_override__ / __pos_override__
	{
		ActionVar loaded = {0}; loaded.type = ACTION_STACK_VALUE_BOOLEAN; loaded.data.numeric_value = 1;
		setProperty(app_context, sound_obj, "__loaded__", 10, &loaded);

		// Pre-loadSound overrides only persist if BOTH duration AND position were set
		if (pre_had_str_dur && pre_had_str_pos) {
			setProperty(app_context, sound_obj, "__dur_override__", 16, &pre_str_dur);
			setProperty(app_context, sound_obj, "__pos_override__", 16, &pre_str_pos);
		}
	}

	// Prepare success=true argument for callbacks
	ActionVar cb_success = {0}; cb_success.type = ACTION_STACK_VALUE_BOOLEAN; cb_success.data.numeric_value = 1;

	// Dispatch onID3 callback (only if ID3 tags were found, before onLoad)
	if (id3_obj != NULL)
	{
		// Temporarily clear __duration__ so getDuration() returns 0 during onID3
		ActionVar save_int_dur = dur_val;
		ActionVar zero = {0}; zero.type = ACTION_STACK_VALUE_F64;
		VAL(double, &zero.data.numeric_value) = 0;
		setProperty(app_context, sound_obj, "__duration__", 12, &zero);

		soundFireCallback(app_context, sound_obj, "onID3", 5, &cb_success, 1);

		// Clear string own props set during onID3 callback, restore pre-loadSound ones
		{
			ASProperty* pd = findPropertyRaw(sound_obj, "duration", 8);
			if (pd != NULL && pd->value.type == ACTION_STACK_VALUE_STRING) {
				if (pre_had_str_dur) pd->value = pre_str_dur;
				else pd->value.type = ACTION_STACK_VALUE_UNDEFINED;
			}
			ASProperty* pp = findPropertyRaw(sound_obj, "position", 8);
			if (pp != NULL && pp->value.type == ACTION_STACK_VALUE_STRING) {
				if (pre_had_str_pos) pp->value = pre_str_pos;
				else pp->value.type = ACTION_STACK_VALUE_UNDEFINED;
			}
		}

		// Restore __duration__ for onLoad
		setProperty(app_context, sound_obj, "__duration__", 12, &save_int_dur);
	}

	// Dispatch onLoad callback (with success=true)
	soundFireCallback(app_context, sound_obj, "onLoad", 6, &cb_success, 1);

	// Clear any string duration/position own properties set during callbacks
	// Then restore only the ones that existed before loadSound
	{
		ASProperty* pd = findPropertyRaw(sound_obj, "duration", 8);
		if (pd != NULL && pd->value.type == ACTION_STACK_VALUE_STRING) {
			if (pre_had_str_dur) pd->value = pre_str_dur;
			else pd->value.type = ACTION_STACK_VALUE_UNDEFINED;
		}
		ASProperty* pp = findPropertyRaw(sound_obj, "position", 8);
		if (pp != NULL && pp->value.type == ACTION_STACK_VALUE_STRING) {
			if (pre_had_str_pos) pp->value = pre_str_pos;
			else pp->value.type = ACTION_STACK_VALUE_UNDEFINED;
		}
	}

	// If streaming mode, auto-start playback
	int is_streaming = 0;
	if (arg_count >= 2 && args[1].type == ACTION_STACK_VALUE_BOOLEAN)
		is_streaming = (int)args[1].data.numeric_value;
	if (is_streaming)
		soundStartPlayback(sound_obj, duration_ms);
#endif

	return ret;
}

static ActionVar builtin_sound_getPosition(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_F64;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL) return ret;

	// Check if sound has completed (position = duration)
	ActionVar* completed = getProperty(sound_obj, "__completed__", 13);
	if (completed != NULL && completed->type == ACTION_STACK_VALUE_BOOLEAN && completed->data.numeric_value)
	{
		ActionVar* dur = getProperty(sound_obj, "__duration__", 12);
		if (dur != NULL && dur->type == ACTION_STACK_VALUE_F64)
			VAL(double, &ret.data.numeric_value) = VAL(double, &dur->data.numeric_value);
		return ret;
	}

	// Check if currently playing — return elapsed
	double elapsed = soundGetElapsedForObject(sound_obj);
	VAL(double, &ret.data.numeric_value) = elapsed;
	return ret;
}

static ActionVar builtin_sound_stop(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL) return ret;
	soundStopForObject(sound_obj);
	return ret;
}

static ActionVar builtin_sound_start(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sound_obj = resolveSoundThis(this_obj);
	if (sound_obj == NULL) return ret;

	// Get duration
	ActionVar* dur = getProperty(sound_obj, "__duration__", 12);
	if (dur == NULL || dur->type != ACTION_STACK_VALUE_F64) return ret;
	double duration_ms = VAL(double, &dur->data.numeric_value);
	if (duration_ms <= 0) return ret;

	// Start playback simulation
	soundStartPlayback(sound_obj, duration_ms);

	return ret;
}

// (setObjectProto is declared in action_internal.h)

// ContextMenu.copy() — creates a new ContextMenu with copied builtInItems
static ActionVar builtin_contextmenu_copy(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* cm = (ASObject*)this_obj;
	if (cm == NULL) return ret;

	// Create new ContextMenu object with __proto__ from stub_ctors[4]
	extern ASFunction g_stub_ctors[]; // forward ref
	ASObject* new_cm = allocObject(app_context, 8);
	retainObject(new_cm);
	if (g_stub_ctors[4].prototype_obj != NULL) {
		ActionVar pv = {0};
		pv.type = ACTION_STACK_VALUE_OBJECT;
		pv.data.numeric_value = (u64)g_stub_ctors[4].prototype_obj;
		setProperty(app_context, new_cm, "__proto__", 9, &pv);
	}

	// Copy builtInItems
	ActionVar* bi_var = getProperty(cm, "builtInItems", 12);
	if (bi_var != NULL && bi_var->type == ACTION_STACK_VALUE_OBJECT) {
		ASObject* old_bi = (ASObject*)bi_var->data.numeric_value;
		ASObject* new_bi = allocObject(app_context, 10);
		retainObject(new_bi);
		setObjectProto(app_context, new_bi);
		// Copy all properties from old builtInItems
		for (u32 i = 0; i < old_bi->num_used; i++) {
			if (old_bi->properties[i].name_length > 0) {
				setProperty(app_context, new_bi, old_bi->properties[i].name,
				            old_bi->properties[i].name_length, &old_bi->properties[i].value);
			}
		}
		ActionVar bv = {0};
		bv.type = ACTION_STACK_VALUE_OBJECT;
		bv.data.numeric_value = (u64)new_bi;
		setProperty(app_context, new_cm, "builtInItems", 12, &bv);
	}

	// Copy customItems (shallow copy of array)
	ActionVar* ci_var = getProperty(cm, "customItems", 11);
	if (ci_var != NULL && ci_var->type == ACTION_STACK_VALUE_ARRAY) {
		ASArray* old_ca = (ASArray*)ci_var->data.numeric_value;
		ASArray* new_ca = allocArray(app_context, old_ca->length > 0 ? old_ca->length : 4);
		new_ca->length = old_ca->length;
		for (u32 i = 0; i < old_ca->length; i++) {
			new_ca->elements[i] = old_ca->elements[i];
		}
		ActionVar cv = {0};
		cv.type = ACTION_STACK_VALUE_ARRAY;
		cv.data.numeric_value = (u64)new_ca;
		setProperty(app_context, new_cm, "customItems", 11, &cv);
	}

	// Copy onSelect
	ActionVar* os_var = getProperty(cm, "onSelect", 8);
	if (os_var != NULL) {
		setProperty(app_context, new_cm, "onSelect", 8, os_var);
	}

	ret.type = ACTION_STACK_VALUE_OBJECT;
	ret.data.numeric_value = (u64)new_cm;
	return ret;
}

// ContextMenuItem.copy() — creates a copy of the menu item
static ActionVar builtin_contextmenuitem_copy(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* cmi = (ASObject*)this_obj;
	if (cmi == NULL) return ret;

	extern ASFunction g_stub_ctors[];
	ASObject* new_cmi = allocObject(app_context, 8);
	retainObject(new_cmi);
	if (g_stub_ctors[5].prototype_obj != NULL) {
		ActionVar pv = {0};
		pv.type = ACTION_STACK_VALUE_OBJECT;
		pv.data.numeric_value = (u64)g_stub_ctors[5].prototype_obj;
		setProperty(app_context, new_cmi, "__proto__", 9, &pv);
	}
	// Copy all properties
	const char* props[] = {"caption", "onSelect", "separatorBefore", "enabled", "visible"};
	int lens[] = {7, 8, 15, 7, 7};
	for (int i = 0; i < 5; i++) {
		ActionVar* pv = getProperty(cmi, props[i], lens[i]);
		if (pv != NULL) setProperty(app_context, new_cmi, props[i], lens[i], pv);
	}
	ret.type = ACTION_STACK_VALUE_OBJECT;
	ret.data.numeric_value = (u64)new_cmi;
	return ret;
}

static ActionVar builtin_return_zero(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_F64;
	return ret;
}

// --- NetConnection connect/close implementation ---

static ActionVar makeStringActionVar(SWFAppContext* app_context, const char* str, u32 len);
static ASFunction g_nc_connect_func;
static ASFunction g_nc_close_func;

// --- NetStream playback implementation ---

static ASFunction g_ns_play_func;
static ASFunction g_ns_seek_func;
static ASFunction g_ns_pause_func;

#define MAX_ACTIVE_NETSTREAMS 8
typedef struct {
	int active;
	ASObject* ns_obj;
	int pending_start;   // play() called, fire Play.Start/Buffer.Full on next tick
	int playing;
	int paused;
	double duration_s;   // video duration from FLV metadata
	double elapsed_ms;   // playback time elapsed
	int completed;       // playback reached end
	int has_metadata;    // onMetaData should be dispatched
	double meta_width;
	double meta_height;
	double meta_framerate;
} ActiveNetStream;

static ActiveNetStream g_active_netstreams[MAX_ACTIVE_NETSTREAMS];
static int g_has_active_netstreams = 0;

// --- LocalConnection implementation ---

static ASFunction g_lc_connect_func;
static ASFunction g_lc_send_func;
static ASFunction g_lc_close_func;
static ASFunction g_lc_domain_func;

#define MAX_LC_CHANNELS 32
#define MAX_LC_MESSAGES 64
#define MAX_LC_MSG_ARGS 16

typedef struct {
	char key[256];        // lowercased channel key
	ASObject* receiver;   // the connected LC object
} LCChannel;

typedef struct {
	char channel_key[256];
	char method[256];
	ActionVar args[MAX_LC_MSG_ARGS];
	int num_args;
	ASObject* sender;
	int had_receiver;     // 1 if channel had listener at send time
} LCMessage;

static LCChannel g_lc_channels[MAX_LC_CHANNELS];
static int g_lc_channel_count = 0;
static LCMessage g_lc_messages[MAX_LC_MESSAGES];
static int g_lc_message_count = 0;

// Build channel key from connection name.
// For connect(): name has no ':', domain is always "localhost"
// For send(): name may contain "domain:channelname"
static void lc_build_key(const char* connection_name, int from_send, char* key_out, int key_size)
{
	const char* colon = strchr(connection_name, ':');
	if (from_send && colon != NULL)
	{
		// Explicit domain:name — extract domain and channel name
		int domain_len = (int)(colon - connection_name);
		const char* name = colon + 1;
		// Get superdomain: rsplit on '.', take last segment, or whole domain if no dot
		const char* dot = NULL;
		for (int i = domain_len - 1; i >= 0; i--)
		{
			if (connection_name[i] == '.') { dot = &connection_name[i]; break; }
		}
		const char* superdomain = dot ? (dot + 1) : connection_name;
		int superdomain_len = dot ? (int)(connection_name + domain_len - dot - 1) : domain_len;
		// ALWAYS use superdomain:name form (even for underscore names when explicit prefix given)
		snprintf(key_out, key_size, "%.*s:%s", superdomain_len, superdomain, name);
	}
	else if (connection_name[0] == '_')
	{
		// Global channel: no domain prefix
		snprintf(key_out, key_size, "%s", connection_name);
	}
	else
	{
		// Default domain "localhost"
		snprintf(key_out, key_size, "localhost:%s", connection_name);
	}
	// Lowercase the entire key
	for (int i = 0; key_out[i]; i++)
		key_out[i] = (char)tolower((unsigned char)key_out[i]);
}

static ASObject* lc_find_receiver(const char* key)
{
	for (int i = 0; i < g_lc_channel_count; i++)
	{
		if (strcmp(g_lc_channels[i].key, key) == 0)
			return g_lc_channels[i].receiver;
	}
	return NULL;
}

static int lc_is_connected(ASObject* obj)
{
	for (int i = 0; i < g_lc_channel_count; i++)
	{
		if (g_lc_channels[i].receiver == obj) return 1;
	}
	return 0;
}

static int lc_register(const char* key, ASObject* receiver)
{
	if (g_lc_channel_count >= MAX_LC_CHANNELS) return 0;
	strncpy(g_lc_channels[g_lc_channel_count].key, key, 255);
	g_lc_channels[g_lc_channel_count].key[255] = '\0';
	g_lc_channels[g_lc_channel_count].receiver = receiver;
	g_lc_channel_count++;
	return 1;
}

static void lc_unregister(ASObject* receiver)
{
	for (int i = 0; i < g_lc_channel_count; i++)
	{
		if (g_lc_channels[i].receiver == receiver)
		{
			// Shift remaining entries down
			for (int j = i; j < g_lc_channel_count - 1; j++)
				g_lc_channels[j] = g_lc_channels[j + 1];
			g_lc_channel_count--;
			return;
		}
	}
}

static int lc_is_protected_method(const char* method)
{
	return (strcasecmp(method, "send") == 0 ||
	        strcasecmp(method, "connect") == 0 ||
	        strcasecmp(method, "close") == 0 ||
	        strcasecmp(method, "allowDomain") == 0 ||
	        strcasecmp(method, "allowInsecureDomain") == 0 ||
	        strcasecmp(method, "domain") == 0 ||
	        strcasecmp(method, "onStatus") == 0);
}

static ActionVar builtin_lc_connect(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0; // false

	ASObject* lc = (ASObject*)this_obj;
	if (lc == NULL || arg_count < 1) return ret;

	// Connection name must be a non-empty string
	if (args[0].type != ACTION_STACK_VALUE_STRING || args[0].str_size == 0) return ret;
	const uint16_t* u16 = varGetU16Ptr(&args[0]);
	if (u16 == NULL) return ret;
	char name_buf[256] = {0};
	u16_to_utf8(u16, args[0].str_size, name_buf, sizeof(name_buf));
	if (name_buf[0] == '\0') return ret;

	// Reject names containing ':'
	if (strchr(name_buf, ':') != NULL) return ret;

	// Already connected? Must close first
	if (lc_is_connected(lc)) return ret;

	// Build channel key
	char key[256] = {0};
	lc_build_key(name_buf, 0, key, sizeof(key));

	// Check if channel is taken
	if (lc_find_receiver(key) != NULL) return ret;

	// Register
	if (!lc_register(key, lc)) return ret;

	ret.data.numeric_value = 1; // true
	return ret;
}

static ActionVar builtin_lc_send(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0; // false

	ASObject* lc = (ASObject*)this_obj;
	if (lc == NULL || arg_count < 2) return ret;

	// Channel name must be a non-empty string
	if (args[0].type != ACTION_STACK_VALUE_STRING || args[0].str_size == 0) return ret;
	const uint16_t* ch_u16 = varGetU16Ptr(&args[0]);
	if (ch_u16 == NULL) return ret;
	char ch_buf[256] = {0};
	u16_to_utf8(ch_u16, args[0].str_size, ch_buf, sizeof(ch_buf));
	if (ch_buf[0] == '\0') return ret;

	// Method name must be a non-empty string
	if (args[1].type != ACTION_STACK_VALUE_STRING || args[1].str_size == 0) return ret;
	const uint16_t* m_u16 = varGetU16Ptr(&args[1]);
	if (m_u16 == NULL) return ret;
	char method_buf[256] = {0};
	u16_to_utf8(m_u16, args[1].str_size, method_buf, sizeof(method_buf));
	if (method_buf[0] == '\0') return ret;

	// Check protected methods
	if (lc_is_protected_method(method_buf)) return ret;

	// Build channel key
	char key[256] = {0};
	lc_build_key(ch_buf, 1, key, sizeof(key));

	// Check if channel has a receiver at send time
	int had_receiver = (lc_find_receiver(key) != NULL) ? 1 : 0;

	// Queue message
	if (g_lc_message_count >= MAX_LC_MESSAGES) { ret.data.numeric_value = 1; return ret; }
	LCMessage* msg = &g_lc_messages[g_lc_message_count++];
	strncpy(msg->channel_key, key, 255); msg->channel_key[255] = '\0';
	strncpy(msg->method, method_buf, 255); msg->method[255] = '\0';
	msg->sender = lc;
	msg->had_receiver = had_receiver;

	// Copy extra args (args beyond channel_name and method_name)
	msg->num_args = 0;
	for (u32 i = 2; i < arg_count && msg->num_args < MAX_LC_MSG_ARGS; i++)
		msg->args[msg->num_args++] = args[i];

	ret.data.numeric_value = 1; // true
	return ret;
}

static ActionVar builtin_lc_close(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;

	ASObject* lc = (ASObject*)this_obj;
	if (lc == NULL) return ret;

	lc_unregister(lc);
	return ret;
}

static ActionVar builtin_lc_domain(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar ret = makeStringActionVar(app_context, "localhost", 9);
	return ret;
}

// Dispatch a method call on a LocalConnection receiver object.
// Looks up methodName on the receiver's prototype chain and calls it.
static void lc_dispatch_method(SWFAppContext* app_context, ASObject* receiver,
                               const char* method_name, ActionVar* args, int num_args)
{
	extern MovieClip* g_current_context;
	ActionVar* mv = getPropertyWithPrototype(receiver, method_name, strlen(method_name));
	if (mv == NULL || mv->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)mv->data.numeric_value;
	if (func == NULL) return;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, args, num_args, regs, (void*)receiver);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		// Type 1: push args on stack (reverse order)
		for (int i = num_args - 1; i >= 0; i--)
			pushVar(app_context, &args[i]);

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;

		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}

	g_special_depth--;
}

// Dispatch onStatus callback on a LocalConnection sender.
// Creates {level: "status"} or {level: "error"} event object.
static void lc_dispatch_onStatus(SWFAppContext* app_context, ASObject* sender, const char* level)
{
	extern MovieClip* g_current_context;
	ActionVar* handler = getPropertyWithPrototype(sender, "onStatus", 8);
	if (handler == NULL || handler->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)handler->data.numeric_value;
	if (func == NULL) return;

	// Create event object: { level: "status"|"error" }
	ASObject* event_obj = allocObject(app_context, 4);
	setObjectProto(app_context, event_obj);
	ActionVar lv = makeStringActionVar(app_context, level, strlen(level));
	setProperty(app_context, event_obj, "level", 5, &lv);

	ActionVar event_arg = {0};
	event_arg.type = ACTION_STACK_VALUE_OBJECT;
	event_arg.data.numeric_value = (u64)event_obj;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, &event_arg, 1, regs, (void*)sender);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		pushVar(app_context, &event_arg);

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;

		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}

	g_special_depth--;
}

// Process all queued LocalConnection messages. Called at end of frame.
void processLocalConnectionMessages(SWFAppContext* app_context)
{
	if (g_lc_message_count == 0) return;

	// Copy queue (processing may trigger new sends)
	int count = g_lc_message_count;
	LCMessage msgs[MAX_LC_MESSAGES];
	memcpy(msgs, g_lc_messages, count * sizeof(LCMessage));
	g_lc_message_count = 0;

	for (int i = 0; i < count; i++)
	{
		LCMessage* msg = &msgs[i];
		if (!msg->had_receiver)
		{
			// No receiver at send time → error
			lc_dispatch_onStatus(app_context, msg->sender, "error");
			continue;
		}

		// Re-check if channel has a receiver at delivery time
		ASObject* receiver = lc_find_receiver(msg->channel_key);
		if (receiver == NULL)
		{
			// Receiver gone → error
			lc_dispatch_onStatus(app_context, msg->sender, "error");
			continue;
		}

		// Success: fire onStatus status, then call method on receiver
		lc_dispatch_onStatus(app_context, msg->sender, "status");
		lc_dispatch_method(app_context, receiver, msg->method,
		                   msg->num_args > 0 ? msg->args : NULL, msg->num_args);
	}
}

int hasActiveLocalConnections(void)
{
	return g_lc_message_count > 0;
}

// Parse FLV header and extract duration from onMetaData script tag.
// Returns duration in seconds, or 0 if parsing fails.
static double flv_parse_duration(const unsigned char* data, int len,
                                 double* out_width, double* out_height, double* out_framerate)
{
	*out_width = 0; *out_height = 0; *out_framerate = 0;
	if (len < 13 || data[0] != 'F' || data[1] != 'L' || data[2] != 'V') return 0;
	int offset = 9; // skip FLV header
	offset += 4;    // skip first PreviousTagSize

	while (offset + 11 < len)
	{
		int tag_type = data[offset];
		int tag_size = (data[offset+1] << 16) | (data[offset+2] << 8) | data[offset+3];
		int tag_data_start = offset + 11;
		if (tag_data_start + tag_size > len) break;

		if (tag_type == 18) // Script data tag
		{
			// Parse AMF: expect string "onMetaData" then ECMA array
			int p = tag_data_start;
			int tag_end = tag_data_start + tag_size;
			if (p >= tag_end || data[p] != 0x02) goto next_tag; // AMF string type
			p++;
			if (p + 2 > tag_end) goto next_tag;
			int slen = (data[p] << 8) | data[p+1]; p += 2;
			if (p + slen > tag_end) goto next_tag;
			if (slen != 10 || memcmp(data + p, "onMetaData", 10) != 0) goto next_tag;
			p += slen;

			// Expect ECMA array (type 0x08)
			if (p >= tag_end || data[p] != 0x08) goto next_tag;
			p++;
			if (p + 4 > tag_end) goto next_tag;
			// int count = (data[p]<<24)|(data[p+1]<<16)|(data[p+2]<<8)|data[p+3];
			p += 4;

			double duration = 0;
			// Parse key-value pairs until end marker
			while (p + 3 < tag_end)
			{
				if (data[p] == 0x00 && data[p+1] == 0x00 && data[p+2] == 0x09) break; // end marker
				int klen = (data[p] << 8) | data[p+1]; p += 2;
				if (p + klen > tag_end) break;
				const char* key = (const char*)(data + p); p += klen;

				if (p >= tag_end) break;
				int vtype = data[p]; p++;

				if (vtype == 0x00) // Number (8 bytes, big-endian double)
				{
					if (p + 8 > tag_end) break;
					// big-endian to host double
					unsigned char dbuf[8];
					for (int i = 0; i < 8; i++) dbuf[i] = data[p + 7 - i];
					double val;
					memcpy(&val, dbuf, 8);
					p += 8;

					if (klen == 8 && memcmp(key, "duration", 8) == 0) duration = val;
					else if (klen == 5 && memcmp(key, "width", 5) == 0) *out_width = val;
					else if (klen == 6 && memcmp(key, "height", 6) == 0) *out_height = val;
					else if (klen == 9 && memcmp(key, "framerate", 9) == 0) *out_framerate = val;
				}
				else if (vtype == 0x01) // Boolean (1 byte)
				{
					if (p + 1 > tag_end) break;
					p += 1;
				}
				else if (vtype == 0x02) // String
				{
					if (p + 2 > tag_end) break;
					int vslen = (data[p] << 8) | data[p+1]; p += 2;
					if (p + vslen > tag_end) break;
					p += vslen;
				}
				else
				{
					break; // Unknown type, stop parsing
				}
			}
			return duration;
		}
next_tag:
		offset = tag_data_start + tag_size + 4; // +4 for PreviousTagSize
	}
	return 0;
}

// Decode a ScreenVideo (codec 3) keyframe to RGBA pixel buffer.
// Returns 1 on success, 0 on failure. Caller must free *out_pixels.
// ScreenVideo format: blocks are bottom-to-top, BGR within block is bottom-to-top.
static int screenvideo_decode_frame(const unsigned char* data, int data_len,
                                     int* out_width, int* out_height,
                                     unsigned char** out_pixels)
{
	if (data_len < 5) return 0;

	// First byte was already consumed (frameType|codecID), data starts at the SV header
	int b1 = data[0], b2 = data[1], b3 = data[2], b4 = data[3];
	int block_w = ((b1 >> 4) + 1) * 16;
	int image_w = ((b1 & 0xF) << 8) | b2;
	int block_h = ((b3 >> 4) + 1) * 16;
	int image_h = ((b3 & 0xF) << 8) | b4;

	if (image_w == 0 || image_h == 0 || image_w > 4096 || image_h > 4096) return 0;

	int cols = (image_w + block_w - 1) / block_w;
	int rows = (image_h + block_h - 1) / block_h;

	unsigned char* pixels = (unsigned char*)calloc(image_w * image_h * 4, 1);
	if (!pixels) return 0;

	int p = 4; // skip SV header
	// Blocks are in row-major order, bottom-to-top (row 0 = bottom row of image)
	for (int row = 0; row < rows; row++)
	{
		for (int col = 0; col < cols; col++)
		{
			if (p + 2 > data_len) { free(pixels); return 0; }
			int block_data_size = (data[p] << 8) | data[p + 1];
			p += 2;
			if (block_data_size == 0) continue; // unchanged block (skip)
			if (p + block_data_size > data_len) { free(pixels); return 0; }

			// Determine actual block dimensions (edge blocks may be smaller)
			int bx = col * block_w;
			int by_bottom = row * block_h; // y from bottom
			int bw = (bx + block_w > image_w) ? (image_w - bx) : block_w;
			int bh = (by_bottom + block_h > image_h) ? (image_h - by_bottom) : block_h;

			// Decompress block data (zlib)
			unsigned char* block_bgr = (unsigned char*)malloc(bw * bh * 3);
			if (!block_bgr) { free(pixels); return 0; }

			unsigned long decomp_len = bw * bh * 3;
			extern int uncompress(unsigned char* dest, unsigned long* destLen,
			                       const unsigned char* source, unsigned long sourceLen);
			int zret = uncompress(block_bgr, &decomp_len, data + p, block_data_size);
			if (zret != 0 || (int)decomp_len != bw * bh * 3)
			{
				free(block_bgr);
				p += block_data_size;
				continue; // skip corrupt block
			}

			// Copy block to pixel buffer (BGR bottom-to-top → RGBA top-to-bottom)
			// Block data row 0 = bottom of block visual, dst_y maps bottom-to-top
			for (int yr = 0; yr < bh; yr++)
			{
				int src_y = yr; // row 0 = bottom of block (both data and visual)
				int dst_y = (image_h - 1) - (by_bottom + yr); // flip to top-to-bottom
				if (dst_y < 0 || dst_y >= image_h) continue;
				for (int xr = 0; xr < bw; xr++)
				{
					int dst_x = bx + xr;
					if (dst_x >= image_w) continue;
					int src_idx = (src_y * bw + xr) * 3;
					int dst_idx = (dst_y * image_w + dst_x) * 4;
					pixels[dst_idx + 0] = block_bgr[src_idx + 2]; // R (from B)
					pixels[dst_idx + 1] = block_bgr[src_idx + 1]; // G
					pixels[dst_idx + 2] = block_bgr[src_idx + 0]; // B (from R)
					pixels[dst_idx + 3] = 255;                     // A
				}
			}

			free(block_bgr);
			p += block_data_size;
		}
	}

	*out_width = image_w;
	*out_height = image_h;
	*out_pixels = pixels;
	return 1;
}

// Parse FLV and decode the first video frame (ScreenVideo only).
// Returns decoded RGBA pixels, or NULL if no decodable frame found.
static unsigned char* flv_decode_first_frame(const unsigned char* data, int len,
                                              int* out_width, int* out_height)
{
	*out_width = 0; *out_height = 0;
	if (len < 13 || data[0] != 'F' || data[1] != 'L' || data[2] != 'V') return NULL;
	int offset = 9 + 4; // skip header + first PreviousTagSize

	while (offset + 11 < len)
	{
		int tag_type = data[offset];
		int tag_size = (data[offset+1] << 16) | (data[offset+2] << 8) | data[offset+3];
		int tag_data_start = offset + 11;
		if (tag_data_start + tag_size > len) break;

		if (tag_type == 9 && tag_size > 1) // Video tag
		{
			int first_byte = data[tag_data_start];
			int frame_type = (first_byte >> 4) & 0xF;
			int codec_id = first_byte & 0xF;

			if (codec_id == 3 && frame_type == 1) // ScreenVideo keyframe
			{
				unsigned char* pixels = NULL;
				if (screenvideo_decode_frame(data + tag_data_start + 1, tag_size - 1,
				                              out_width, out_height, &pixels))
					return pixels;
			}
			// Other codecs not supported yet
		}
		offset = tag_data_start + tag_size + 4;
	}
	return NULL;
}

// Global video frame storage for NetStream→Video pipeline
#define MAX_VIDEO_FRAMES 4
static struct {
	int active;
	ASObject* ns_obj;
	unsigned char* pixels;  // RGBA
	int width;
	int height;
} g_video_frames[MAX_VIDEO_FRAMES];

static void ns_store_decoded_frame(ASObject* ns, unsigned char* pixels, int w, int h)
{
	for (int i = 0; i < MAX_VIDEO_FRAMES; i++)
	{
		if (g_video_frames[i].ns_obj == ns || !g_video_frames[i].active)
		{
			if (g_video_frames[i].pixels) free(g_video_frames[i].pixels);
			g_video_frames[i].active = 1;
			g_video_frames[i].ns_obj = ns;
			g_video_frames[i].pixels = pixels;
			g_video_frames[i].width = w;
			g_video_frames[i].height = h;
			return;
		}
	}
	free(pixels); // no slot available
}

// Expose decoded video frame for headless rendering (tag.c calls this).
// Converts RGBA u8 to ARGB u32 (format expected by renderer_draw_bitmap_quad).
// Returns 1 if a frame was found, 0 otherwise. Caller must free *out_argb.
int actionGetVideoFramePixels(uint32_t** out_argb, int* out_w, int* out_h)
{
	for (int i = 0; i < MAX_VIDEO_FRAMES; i++)
	{
		if (g_video_frames[i].active && g_video_frames[i].pixels)
		{
			int w = g_video_frames[i].width;
			int h = g_video_frames[i].height;
			int n = w * h;
			uint32_t* argb = (uint32_t*)malloc(n * sizeof(uint32_t));
			if (!argb) return 0;
			unsigned char* rgba = g_video_frames[i].pixels;
			for (int p = 0; p < n; p++)
			{
				argb[p] = ((uint32_t)rgba[p*4+3] << 24) |
				           ((uint32_t)rgba[p*4+0] << 16) |
				           ((uint32_t)rgba[p*4+1] << 8) |
				           (uint32_t)rgba[p*4+2];
			}
			*out_argb = argb;
			*out_w = w;
			*out_h = h;
			return 1;
		}
	}
	return 0;
}

static void ns_dispatch_onStatus(SWFAppContext* app_context, ASObject* ns,
                                  const char* code, const char* level)
{
	extern MovieClip* g_current_context;
	ActionVar* handler = getPropertyWithPrototype(ns, "onStatus", 8);
	if (handler == NULL || handler->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)handler->data.numeric_value;
	if (func == NULL) return;

	// Create event object: { code: "...", level: "..." }
	// Must have Object.prototype for hasOwnProperty to work in type-1 handlers
	ASObject* event_obj = allocObject(app_context, 4);
	setObjectProto(app_context, event_obj);
	ActionVar cv = makeStringActionVar(app_context, code, strlen(code));
	setProperty(app_context, event_obj, "code", 4, &cv);
	ActionVar lv = makeStringActionVar(app_context, level, strlen(level));
	setProperty(app_context, event_obj, "level", 5, &lv);

	ActionVar event_arg = {0};
	event_arg.type = ACTION_STACK_VALUE_OBJECT;
	event_arg.data.numeric_value = (u64)event_obj;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, &event_arg, 1, regs, (void*)ns);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		pushVar(app_context, &event_arg);

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		// Push local scope so type-1 function parameter binding works
		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;

		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}

	g_special_depth--;
}

static void ns_dispatch_onMetaData(SWFAppContext* app_context, ASObject* ns,
                                    double duration, double width, double height, double framerate)
{
	extern MovieClip* g_current_context;
	ActionVar* handler = getPropertyWithPrototype(ns, "onMetaData", 10);
	if (handler == NULL || handler->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)handler->data.numeric_value;
	if (func == NULL) return;

	// Create metadata object
	ASObject* meta = allocObject(app_context, 8);
	ActionVar dv = {0}; dv.type = ACTION_STACK_VALUE_F64;
	VAL(double, &dv.data.numeric_value) = duration;
	setProperty(app_context, meta, "duration", 8, &dv);
	VAL(double, &dv.data.numeric_value) = width;
	setProperty(app_context, meta, "width", 5, &dv);
	VAL(double, &dv.data.numeric_value) = height;
	setProperty(app_context, meta, "height", 6, &dv);
	VAL(double, &dv.data.numeric_value) = framerate;
	setProperty(app_context, meta, "framerate", 9, &dv);

	ActionVar meta_arg = {0};
	meta_arg.type = ACTION_STACK_VALUE_OBJECT;
	meta_arg.data.numeric_value = (u64)meta;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, &meta_arg, 1, regs, (void*)ns);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		pushVar(app_context, &meta_arg);

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		// Push local scope so type-1 function parameter binding works
		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;

		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}

	g_special_depth--;
}

#ifdef HAS_DATA_FILES
extern DataFileEntry* findDataFile(const char* name);
#endif

static ActionVar builtin_ns_play(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ASObject* ns = (ASObject*)this_obj;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (ns == NULL || arg_count == 0) return ret;

#ifdef HAS_DATA_FILES
	// Get URL string
	char url_buf[256] = {0};
	if (args[0].type == ACTION_STACK_VALUE_STRING && args[0].str_size > 0)
	{
		uint16_t* u16 = (uint16_t*)(uintptr_t)args[0].data.numeric_value;
		u32 i;
		for (i = 0; i < args[0].str_size && i < 255; i++)
			url_buf[i] = (char)(u16[i] & 0xFF);
		url_buf[i] = 0;
	}
	else return ret;

	// Strip path, use basename
	const char* basename = url_buf;
	for (const char* p = url_buf; *p; p++)
		if (*p == '/' || *p == '\\') basename = p + 1;

	DataFileEntry* entry = findDataFile(basename);
	if (entry == NULL) return ret;

	// Parse FLV to get duration
	double width = 0, height = 0, framerate = 0;
	double duration = flv_parse_duration((const unsigned char*)entry->content, entry->content_length,
	                                      &width, &height, &framerate);
	if (duration <= 0) duration = 1.0; // fallback

	// Register as active NetStream
	int slot = -1;
	for (int i = 0; i < MAX_ACTIVE_NETSTREAMS; i++)
	{
		if (!g_active_netstreams[i].active) { slot = i; break; }
		// Reuse slot if same ns_obj (re-play)
		if (g_active_netstreams[i].ns_obj == ns) { slot = i; break; }
	}
	if (slot < 0) return ret;

	g_active_netstreams[slot].active = 1;
	g_active_netstreams[slot].ns_obj = ns;
	g_active_netstreams[slot].pending_start = 1;
	g_active_netstreams[slot].playing = 0;
	g_active_netstreams[slot].paused = 0;
	g_active_netstreams[slot].duration_s = duration;
	g_active_netstreams[slot].elapsed_ms = 0;
	g_active_netstreams[slot].completed = 0;
	g_active_netstreams[slot].has_metadata = 1;
	g_active_netstreams[slot].meta_width = width;
	g_active_netstreams[slot].meta_height = height;
	g_active_netstreams[slot].meta_framerate = framerate;
	g_has_active_netstreams = 1;

	// Decode first video frame (ScreenVideo only)
	int frame_w = 0, frame_h = 0;
	unsigned char* frame_pixels = flv_decode_first_frame(
		(const unsigned char*)entry->content, entry->content_length,
		&frame_w, &frame_h);
	if (frame_pixels != NULL)
		ns_store_decoded_frame(ns, frame_pixels, frame_w, frame_h);
#endif

	return ret;
}

static ActionVar builtin_ns_seek(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ASObject* ns = (ASObject*)this_obj;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (ns == NULL) return ret;

	// Find the active stream for this ns
	for (int i = 0; i < MAX_ACTIVE_NETSTREAMS; i++)
	{
		if (g_active_netstreams[i].active && g_active_netstreams[i].ns_obj == ns)
		{
			// Fire Seek.Notify synchronously
			ns_dispatch_onStatus(app_context, ns, "NetStream.Seek.Notify", "status");
			break;
		}
	}

	return ret;
}

static ActionVar builtin_ns_pause(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	// pause() returns undefined in Flash
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	return ret;
}

void processNetStreams(SWFAppContext* app_context, double frame_duration_ms)
{
	if (!g_has_active_netstreams) return;

	int any_active = 0;
	for (int i = 0; i < MAX_ACTIVE_NETSTREAMS; i++)
	{
		if (!g_active_netstreams[i].active) continue;

		ActiveNetStream* ns = &g_active_netstreams[i];

		if (ns->pending_start)
		{
			ns->pending_start = 0;
			ns->playing = 1;
			// Fire Play.Start and Buffer.Full
			ns_dispatch_onStatus(app_context, ns->ns_obj, "NetStream.Play.Start", "status");
			ns_dispatch_onStatus(app_context, ns->ns_obj, "NetStream.Buffer.Full", "status");
			// Dispatch onMetaData if we parsed metadata
			if (ns->has_metadata)
			{
				ns_dispatch_onMetaData(app_context, ns->ns_obj,
				                        ns->duration_s, ns->meta_width,
				                        ns->meta_height, ns->meta_framerate);
				ns->has_metadata = 0;
			}
			any_active = 1;
			continue;
		}

		if (ns->playing && !ns->paused && !ns->completed)
		{
			ns->elapsed_ms += frame_duration_ms;
			if (ns->elapsed_ms >= ns->duration_s * 1000.0)
			{
				// Playback complete
				ns->completed = 1;
				ns->playing = 0;
				ns_dispatch_onStatus(app_context, ns->ns_obj, "NetStream.Buffer.Flush", "status");
				ns_dispatch_onStatus(app_context, ns->ns_obj, "NetStream.Play.Stop", "status");
				ns_dispatch_onStatus(app_context, ns->ns_obj, "NetStream.Buffer.Empty", "status");
				ns->active = 0;
			}
			else
			{
				any_active = 1;
			}
		}
		else
		{
			any_active = 1; // paused or waiting — still active
		}
	}

	if (!any_active)
	{
		g_has_active_netstreams = 0;
		for (int i = 0; i < MAX_ACTIVE_NETSTREAMS; i++)
			if (g_active_netstreams[i].active) { g_has_active_netstreams = 1; break; }
	}
}

int hasActiveNetStreams(void)
{
	return g_has_active_netstreams;
}

static void nc_dispatch_onStatus(SWFAppContext* app_context, ASObject* nc,
                                  const char* code, const char* level)
{
	extern MovieClip* g_current_context;
	ActionVar* handler = getPropertyWithPrototype(nc, "onStatus", 8);
	if (handler == NULL || handler->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)handler->data.numeric_value;
	if (func == NULL) return;

	// Create event object: { code: "...", level: "..." }
	ASObject* event_obj = allocObject(app_context, 4);
	ActionVar cv = makeStringActionVar(app_context, code, strlen(code));
	setProperty(app_context, event_obj, "code", 4, &cv);
	ActionVar lv = makeStringActionVar(app_context, level, strlen(level));
	setProperty(app_context, event_obj, "level", 5, &lv);

	ActionVar event_arg = {0};
	event_arg.type = ACTION_STACK_VALUE_OBJECT;
	event_arg.data.numeric_value = (u64)event_obj;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, &event_arg, 1, regs, (void*)nc);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		// Type 1 function: push event arg on stack
		pushVar(app_context, &event_arg);

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;

		for (u32 ci = 0; ci < captured_count; ci++)
			if (scope_depth > 0) scope_depth--;
	}

	g_special_depth--;
}

static ActionVar builtin_nc_connect(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers;
	ASObject* nc = (ASObject*)this_obj;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (nc == NULL) return ret;

	// If already connected, fire Close first
	ActionVar* is_conn = getProperty(nc, "isConnected", 11);
	if (is_conn != NULL && is_conn->type == ACTION_STACK_VALUE_BOOLEAN && is_conn->data.numeric_value != 0)
	{
		nc_dispatch_onStatus(app_context, nc, "NetConnection.Connect.Closed", "status");
	}

	// Set isConnected = true
	ActionVar bv = {0}; bv.type = ACTION_STACK_VALUE_BOOLEAN; bv.data.numeric_value = 1;
	setProperty(app_context, nc, "isConnected", 11, &bv);

	// connect(null) = local connection: fire Success
	// connect(non-null string) = remote: no onStatus, but store URI for close()
	int is_null_connect = (arg_count == 0);
	if (!is_null_connect && arg_count > 0)
	{
		is_null_connect = (args[0].type == ACTION_STACK_VALUE_NULL ||
		                   args[0].type == ACTION_STACK_VALUE_UNDEFINED);
	}

	if (is_null_connect)
	{
		// Clear uri for local connections
		ActionVar empty_uri = {0}; empty_uri.type = ACTION_STACK_VALUE_NULL;
		setProperty(app_context, nc, "uri", 3, &empty_uri);
		nc_dispatch_onStatus(app_context, nc, "NetConnection.Connect.Success", "status");
	}
	else
	{
		// Store the URI for remote connections (used by close to detect remote)
		if (arg_count > 0)
			setProperty(app_context, nc, "uri", 3, &args[0]);
	}

	return ret;
}

static void nc_dispatch_onStatus_undefined(SWFAppContext* app_context, ASObject* nc)
{
	extern MovieClip* g_current_context;
	ActionVar* handler = getPropertyWithPrototype(nc, "onStatus", 8);
	if (handler == NULL || handler->type != ACTION_STACK_VALUE_FUNCTION) return;
	ASFunction* func = (ASFunction*)(uintptr_t)handler->data.numeric_value;
	if (func == NULL) return;

	ActionVar undef_arg = {0};
	undef_arg.type = ACTION_STACK_VALUE_UNDEFINED;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH) { g_special_depth--; return; }

	if (func->function_type == 2)
	{
		ActionVar* regs = NULL;
		if (func->register_count > 0)
			regs = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		g_call_depth++;
		func->advanced_func(app_context, &undef_arg, 1, regs, (void*)nc);
		g_call_depth--;

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count + 1; ci++)
			if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (regs != NULL) FREE(regs);
	}
	else
	{
		pushVar(app_context, &undef_arg);
		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
		g_call_depth--;
	}

	g_special_depth--;
}

static ActionVar builtin_nc_close(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)args; (void)arg_count; (void)registers;
	ASObject* nc = (ASObject*)this_obj;
	ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_UNDEFINED;
	if (nc == NULL) return ret;

	// Only fire onStatus if currently connected
	ActionVar* is_conn = getProperty(nc, "isConnected", 11);
	if (is_conn != NULL && is_conn->type == ACTION_STACK_VALUE_BOOLEAN && is_conn->data.numeric_value != 0)
	{
		// Check if it was a remote connection (has uri property)
		ActionVar* uri = getProperty(nc, "uri", 3);
		int was_remote = (uri != NULL && uri->type == ACTION_STACK_VALUE_STRING && uri->str_size > 0);

		ActionVar bv = {0}; bv.type = ACTION_STACK_VALUE_BOOLEAN; bv.data.numeric_value = 0;
		setProperty(app_context, nc, "isConnected", 11, &bv);
		nc_dispatch_onStatus(app_context, nc, "NetConnection.Connect.Closed", "status");

		// Remote connections also fire a second onStatus with undefined event
		if (was_remote)
		{
			nc_dispatch_onStatus_undefined(app_context, nc);
		}
	}

	return ret;
}

#define MAX_PROTO_STUB_FUNCS 192
static ASFunction g_proto_stub_funcs[MAX_PROTO_STUB_FUNCS];
static int g_proto_stub_func_count = 0;

// (setupNativeFuncOwnProps is declared in action_internal.h)

// Add a stub function property to a prototype object.
// flags controls ENUMERABLE/WRITABLE/CONFIGURABLE behavior.
static void addStubMethodToProto(SWFAppContext* app_context, ASObject* proto, const char* name, u32 name_len, u8 flags)
{
	if (g_proto_stub_func_count >= MAX_PROTO_STUB_FUNCS) return;
	ASFunction* fn = &g_proto_stub_funcs[g_proto_stub_func_count++];
	memset(fn, 0, sizeof(ASFunction));
	strncpy(fn->name, name, 255);
	fn->function_type = 2;
	fn->advanced_func = (Function2Ptr) builtin_stub_method;
	setupNativeFuncOwnProps(app_context, fn);
	if (function_count < MAX_FUNCTIONS)
		function_registry[function_count++] = fn;
	ActionVar fv = {0};
	fv.type = ACTION_STACK_VALUE_FUNCTION;
	fv.data.numeric_value = (u64) fn;
	setPropertyWithFlags(app_context, proto, name, name_len, &fv, flags);
}

static int isNativeTextFieldProperty(const char* name, u32 len); // forward decl

// Built-in hasOwnProperty checks if a property exists directly on the object
static ActionVar builtin_object_hasOwnProperty(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.str_size = 0;
	ret.data.numeric_value = 0; // false by default

	if (this_obj != NULL && args != NULL && arg_count >= 1)
	{
		ASObject* obj = (ASObject*) this_obj;
		const char* prop_name = NULL;
		u32 prop_name_len = 0;
		char coerced_buf[64];

		if (args[0].type == ACTION_STACK_VALUE_STRING)
		{
			const uint16_t* _u16 = varGetU16Ptr(&args[0]);
			prop_name_len = (u32)u16_to_utf8(_u16, args[0].str_size, coerced_buf, sizeof(coerced_buf));
			prop_name = coerced_buf;
		}
		else if (args[0].type == ACTION_STACK_VALUE_UNDEFINED)
		{
			// undefined coerces to "undefined" for property names
			prop_name = "undefined";
			prop_name_len = 9;
		}
		else if (args[0].type == ACTION_STACK_VALUE_NULL)
		{
			// null coerces to "null" for property names
			prop_name = "null";
			prop_name_len = 4;
		}
		else
		{
			// Coerce non-string argument to string (numbers, booleans)
			int len = varToStringBuf(app_context, &args[0], coerced_buf, sizeof(coerced_buf));
			prop_name = coerced_buf;
			prop_name_len = (u32) len;
		}

		if (prop_name != NULL)
		{
			// TextField native properties live on TextField.prototype as placeholders,
			// not as own properties on the instance — even though we also mirror them
			// on `dynamic_props` for read/write access, hasOwnProperty on the instance
			// must return false for them to match Flash.
			if (obj->native_type == NATIVE_TEXTFIELD &&
			    isNativeTextFieldProperty(prop_name, prop_name_len))
			{
				return ret; // false
			}
			// Use hasPropertyRaw to check existence ignoring flash_flags visibility
			// (hasOwnProperty returns true even for hidden properties)
			if (hasPropertyRaw(obj, prop_name, prop_name_len))
			{
				ret.data.numeric_value = 1; // true
			}
		}
	}
	return ret;
}

// Built-in isPropertyEnumerable(name) — checks if OWN property exists and is enumerable
static ActionVar builtin_object_isPropertyEnumerable(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.str_size = 0;
	ret.data.numeric_value = 0; // false by default

	if (this_obj != NULL && args != NULL && arg_count >= 1)
	{
		ASObject* obj = (ASObject*) this_obj;
		const char* prop_name = NULL;
		u32 prop_name_len = 0;
		char coerced_buf[64];

		if (args[0].type == ACTION_STACK_VALUE_STRING)
		{
			const uint16_t* _u16 = varGetU16Ptr(&args[0]);
			prop_name_len = (u32)u16_to_utf8(_u16, args[0].str_size, coerced_buf, sizeof(coerced_buf));
			prop_name = coerced_buf;
		}
		else
		{
			int len = varToStringBuf(app_context, &args[0], coerced_buf, sizeof(coerced_buf));
			prop_name = coerced_buf;
			prop_name_len = (u32) len;
		}

		if (prop_name != NULL)
		{
			// Check own properties only (not prototype chain)
			for (u32 i = 0; i < obj->num_used; i++)
			{
				if (obj->properties[i].name_length == prop_name_len &&
				    strncmp(obj->properties[i].name, prop_name, prop_name_len) == 0)
				{
					// Property exists — check if it's enumerable
					if (obj->properties[i].flags & PROPERTY_FLAG_ENUMERABLE)
					{
						ret.data.numeric_value = 1; // true
					}
					break;
				}
			}
		}
	}
	return ret;
}

// Built-in isPrototypeOf(obj) — checks if `this` appears in obj's prototype chain
static ActionVar builtin_object_isPrototypeOf(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.str_size = 0;
	ret.data.numeric_value = 0; // false by default

	if (this_obj != NULL && args != NULL && arg_count >= 1)
	{
		ASObject* self = (ASObject*) this_obj;

		// Get the object to check
		ASObject* check_obj = NULL;
		int is_function_arg = 0;
		if (args[0].type == ACTION_STACK_VALUE_OBJECT && args[0].data.numeric_value != 0)
		{
			check_obj = (ASObject*) args[0].data.numeric_value;
		}
		else if (args[0].type == ACTION_STACK_VALUE_FUNCTION && args[0].data.numeric_value != 0)
		{
			// Functions have own_props that acts as their object
			ASFunction* func = (ASFunction*) args[0].data.numeric_value;
			check_obj = func->own_props;
			is_function_arg = 1;
		}

		if (check_obj != NULL)
		{
			// Walk check_obj's __proto__ chain looking for self
			ASObject* current = check_obj;
			int max_depth = 64; // prevent infinite loops
			while (current != NULL && max_depth-- > 0)
			{
				ActionVar* proto_var = getProperty(current, "__proto__", 9);
				if (proto_var == NULL || proto_var->type != ACTION_STACK_VALUE_OBJECT || proto_var->data.numeric_value == 0)
					break;
				ASObject* proto = (ASObject*) proto_var->data.numeric_value;
				if (proto == self)
				{
					ret.data.numeric_value = 1; // true
					break;
				}
				current = proto;
			}
		}

		// Functions implicitly inherit from Object.prototype (via Function.prototype)
		// If chain walk didn't find self, check if self is Object.prototype
		if (ret.data.numeric_value == 0 && is_function_arg)
		{
			if (g_object_prototype != NULL && self == g_object_prototype)
				ret.data.numeric_value = 1;
		}
	}
	return ret;
}

// Built-in valueOf returns `this` (the object it's called on)
static ActionVar builtin_object_valueOf(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.str_size = 0;
	// MovieClip receiver path: actionCallMethod passes this_obj=NULL and
	// communicates the MC via g_event_this_mc. Object.prototype.valueOf
	// must return `this` as MOVIECLIP so `typeof(mc.valueOf())` is 'movieclip'
	// and it string-coerces to the MC's path.
	if (this_obj == NULL && g_event_this_mc != NULL)
	{
		ret.type = ACTION_STACK_VALUE_MOVIECLIP;
		ret.data.numeric_value = (u64) g_event_this_mc;
		return ret;
	}
	if (this_obj == NULL)
	{
		ret.type = ACTION_STACK_VALUE_UNDEFINED;
		ret.data.numeric_value = 0;
		return ret;
	}
	// For OBJECT/ARRAY/FUNCTION receivers, the caller's CallMethod path pushes
	// this onto g_this_stack with the right type tag; read it back so we
	// preserve MOVIECLIP/FUNCTION/ARRAY identity instead of forcing OBJECT.
	if (g_this_depth > 0 &&
	    g_this_stack[g_this_depth - 1].data.numeric_value == (u64) this_obj)
	{
		ret.type = g_this_stack[g_this_depth - 1].type;
	}
	else
	{
		ret.type = ACTION_STACK_VALUE_OBJECT;
	}
	ret.data.numeric_value = (u64) this_obj;
	return ret;
}

// Built-in Object.prototype.watch(prop, fn [, userData]) — register a watcher for property changes
static ActionVar builtin_object_watch(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret_false = {0};
	ret_false.type = ACTION_STACK_VALUE_BOOLEAN;
	ret_false.data.numeric_value = 0;
	if (arg_count < 2) return ret_false;
	if (args[1].type != ACTION_STACK_VALUE_FUNCTION) return ret_false;

	// When this_obj == NULL (called via actionCallFunction at timeline level),
	// treat it as a timeline/MovieClip variable watch on g_current_context.
	ASObject* obj = NULL;
	MovieClip* mc = NULL;
	if (this_obj != NULL) {
		obj = (ASObject*) this_obj;
	} else {
		mc = g_current_context ? g_current_context : &root_movieclip;
		if (mc == NULL) return ret_false;
	}

	char prop_name[64] = {0};
	u32 prop_name_len = 0;
	if (args[0].type == ACTION_STACK_VALUE_STRING) {
		const uint16_t* u16 = varGetU16Ptr(&args[0]);
		if (u16 != NULL)
			prop_name_len = (u32)u16_to_utf8(u16, args[0].str_size, prop_name, (int)(sizeof(prop_name) - 1));
	}
	ASFunction* wf = (ASFunction*) args[1].data.numeric_value;

	// Store userData (3rd arg, or undefined if not provided)
	ActionVar user_data = {0};
	user_data.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count >= 3) user_data = args[2];

	// Update existing entry if already watching this prop on this object/mc
	for (int i = 0; i < g_watch_count; i++) {
		if (g_watch_table[i].obj == obj &&
		    g_watch_table[i].mc == mc &&
		    g_watch_table[i].prop_name_len == prop_name_len &&
		    strncmp(g_watch_table[i].prop_name, prop_name, prop_name_len) == 0)
		{
			g_watch_table[i].watcher_func = wf;
			g_watch_table[i].user_data = user_data;
			ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_BOOLEAN; ret.data.numeric_value = 1;
			return ret;
		}
	}
	// Add new entry
	if (g_watch_count < MAX_WATCH_ENTRIES) {
		g_watch_table[g_watch_count].obj = obj;
		g_watch_table[g_watch_count].mc = mc;
		strncpy(g_watch_table[g_watch_count].prop_name, prop_name, sizeof(g_watch_table[0].prop_name) - 1);
		g_watch_table[g_watch_count].prop_name_len = prop_name_len;
		g_watch_table[g_watch_count].watcher_func = wf;
		g_watch_table[g_watch_count].user_data = user_data;
		g_watch_count++;
		ActionVar ret = {0}; ret.type = ACTION_STACK_VALUE_BOOLEAN; ret.data.numeric_value = 1;
		return ret;
	}
	return ret_false;
}

// Built-in Object.prototype.unwatch(prop) — remove a property watcher
static ActionVar builtin_object_unwatch(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0;
	if (arg_count < 1) return ret;

	// Determine target: ASObject (this_obj != NULL) or MovieClip timeline (this_obj == NULL)
	ASObject* obj = NULL;
	MovieClip* mc = NULL;
	if (this_obj != NULL) {
		obj = (ASObject*) this_obj;
	} else {
		mc = g_current_context ? g_current_context : &root_movieclip;
		if (mc == NULL) return ret;
	}

	char prop_name[64] = {0};
	u32 prop_name_len = 0;
	if (args[0].type == ACTION_STACK_VALUE_STRING) {
		const uint16_t* u16 = varGetU16Ptr(&args[0]);
		if (u16 != NULL)
			prop_name_len = (u32)u16_to_utf8(u16, args[0].str_size, prop_name, (int)(sizeof(prop_name) - 1));
	}
	for (int i = 0; i < g_watch_count; i++) {
		if (g_watch_table[i].obj == obj &&
		    g_watch_table[i].mc == mc &&
		    g_watch_table[i].prop_name_len == prop_name_len &&
		    strncmp(g_watch_table[i].prop_name, prop_name, prop_name_len) == 0)
		{
			for (int j = i; j < g_watch_count - 1; j++)
				g_watch_table[j] = g_watch_table[j + 1];
			g_watch_count--;
			ret.data.numeric_value = 1;
			return ret;
		}
	}
	return ret;
}

// Built-in Object.prototype.addProperty(name, getter, setter)
// Callable via Function.call: Object.addProperty.call(target, name, getter, setter)
static ActionVar builtin_object_addProperty(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0; // false by default

	if (this_obj == NULL || arg_count < 3) return ret;
	if (args[0].type != ACTION_STACK_VALUE_STRING) return ret;

	ASObject* obj = (ASObject*) this_obj;

	char _addprop_buf[512];
	const uint16_t* _u16 = varGetU16Ptr(&args[0]);
	u16_to_utf8(_u16, args[0].str_size, _addprop_buf, sizeof(_addprop_buf));
	const char* prop_name = _addprop_buf;
	u32 prop_name_len = (u32)strlen(prop_name);

	ASFunction* getter = NULL;
	if (args[1].type == ACTION_STACK_VALUE_FUNCTION)
		getter = (ASFunction*) args[1].data.numeric_value;
	ASFunction* setter = NULL;
	if (args[2].type == ACTION_STACK_VALUE_FUNCTION)
		setter = (ASFunction*) args[2].data.numeric_value;

	// Find or create property on the target object
	ASProperty* prop = NULL;
	for (u32 i = 0; i < obj->num_used; i++) {
		if (obj->properties[i].name_length == prop_name_len &&
		    strncmp(obj->properties[i].name, prop_name, prop_name_len) == 0) {
			prop = &obj->properties[i];
			break;
		}
	}
	if (prop == NULL) {
		ActionVar marker = {0};
		marker.type = ACTION_STACK_VALUE_UNDEFINED;
		setProperty(app_context, obj, prop_name, prop_name_len, &marker);
		for (u32 i = 0; i < obj->num_used; i++) {
			if (obj->properties[i].name_length == prop_name_len &&
			    strncmp(obj->properties[i].name, prop_name, prop_name_len) == 0) {
				prop = &obj->properties[i];
				break;
			}
		}
	}
	if (prop != NULL) {
		prop->getter = (void*) getter;
		prop->setter = (void*) setter;
		ret.data.numeric_value = 1; // true
	}
	return ret;
}

// Built-in Error.prototype.toString — returns the message property
static ActionVar builtin_error_toString(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 5;
	ret.data.numeric_value = (u64) u16_Error;

	if (this_obj != NULL)
	{
		ASObject* obj = (ASObject*) this_obj;
		ActionVar* msg = getPropertyWithPrototype(obj, "message", 7);
		if (msg != NULL && msg->type != ACTION_STACK_VALUE_UNDEFINED)
		{
			return *msg;
		}
	}
	return ret;
}

static ASFunction g_error_toString_func;

// Built-in String.fromCharCode(code1, code2, ...) — static method on String constructor
// Each argument is coerced to uint16, producing one UTF-16 code unit per argument.
static ASFunction g_string_fromCharCode_func;
static ActionVar builtin_string_fromCharCode(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 0;
	ret.data.numeric_value = 0;

	if (arg_count == 0)
		return ret;

	// Each arg produces one UTF-16 code unit
	uint16_t* buf = (uint16_t*) malloc( (arg_count + 1) * sizeof(uint16_t));
	u32 pos = 0;

	for (u32 i = 0; i < arg_count; i++)
	{
		double d = 0.0;
		switch (args[i].type)
		{
			case ACTION_STACK_VALUE_F32: d = (double) VAL(float, &args[i].data.numeric_value); break;
			case ACTION_STACK_VALUE_F64: d = VAL(double, &args[i].data.numeric_value); break;
			case ACTION_STACK_VALUE_BOOLEAN: d = args[i].data.numeric_value ? 1.0 : 0.0; break;
			default: d = 0.0; break;
		}

		// ToUint16: mod 65536
		int code;
		if (isnan(d) || isinf(d)) code = 0;
		else
		{
			double n = fmod(d, 65536.0);
			if (n < 0) n += 65536.0;
			code = (int)n;
		}

		// NUL code unit terminates C-string semantics, stop here
		if (code == 0) break;

		buf[pos++] = (uint16_t)code;
	}
	buf[pos] = 0;

	ret.str_size = pos;
	ret.data.string_data.heap_ptr = buf;
	ret.data.string_data.owns_memory = true;
	return ret;
}

