// ============================================================================
// flash.display.BitmapData globals
// ============================================================================
typedef struct {
    uint32_t* pixels;    // ARGB pixel data, row-major
    int32_t width;
    int32_t height;
    uint8_t transparent; // 0 = opaque (alpha always 0xFF), 1 = transparent
    uint8_t disposed;    // 1 = disposed (all operations return -1)
} BitmapDataNative;

static ASObject* g_bitmapdata_prototype = NULL;
// Methods: getPixel, getPixel32, setPixel, setPixel32, fillRect, clone, dispose,
//          copyChannel, floodFill, colorTransform, getColorBoundsRect, toString,
//          applyFilter, copyPixels, draw, generateFilterRect, hitTest, loadBitmap,
//          merge, noise, paletteMap, perlinNoise, pixelDissolve, scroll, setPixel,
//          compare, threshold
static ASFunction g_bitmapdata_methods[28];
static int g_bitmapdata_init_done = 0;

// Side table for BitmapData native data (avoids modifying ASObject struct).
// Entries are never reclaimed (no GC for ASObject), so this needs to be large
// enough to hold every BMD ever created in a single test run. The
// `bitmap_data_thorough/*` tests create ~50 fresh BMDs per iteration × 3
// iterations × 14 sub-tests, so 256 was hit in copyChannel and getter calls
// started returning -1.
#define MAX_BITMAP_NATIVES 8192
static struct { ASObject* obj; BitmapDataNative* native; } g_bitmap_natives[MAX_BITMAP_NATIVES];
static int g_bitmap_native_count = 0;

static void setBitmapNative(ASObject* obj, BitmapDataNative* native)
{
    // Check if already registered
    for (int i = 0; i < g_bitmap_native_count; i++) {
        if (g_bitmap_natives[i].obj == obj) {
            g_bitmap_natives[i].native = native;
            return;
        }
    }
    if (g_bitmap_native_count < MAX_BITMAP_NATIVES) {
        g_bitmap_natives[g_bitmap_native_count].obj = obj;
        g_bitmap_natives[g_bitmap_native_count].native = native;
        g_bitmap_native_count++;
    }
}

static inline BitmapDataNative* getBitmapNative(ASObject* obj)
{
    if (obj == NULL || obj->native_type != NATIVE_BITMAPDATA) return NULL;
    for (int i = 0; i < g_bitmap_native_count; i++) {
        if (g_bitmap_natives[i].obj == obj) return g_bitmap_natives[i].native;
    }
    return NULL;
}

// Convert double to uint32 for pixel color values (ECMA-262 ToUint32)
static inline uint32_t doubleToUint32(double d)
{
    if (isnan(d) || isinf(d) || d == 0.0) return 0;
    double posInt = (d > 0 ? 1.0 : -1.0) * floor(fabs(d));
    double mod = fmod(posInt, 4294967296.0);
    if (mod < 0) mod += 4294967296.0;
    return (uint32_t)mod;
}

// Premultiply ARGB color: RGB channels scaled by alpha/255
static inline uint32_t premultiplyAlpha(uint32_t color)
{
    uint32_t a = (color >> 24) & 0xFF;
    if (a == 255) return color;
    if (a == 0) return 0;
    uint32_t r = ((((color >> 16) & 0xFF) * a + 127) / 255);
    uint32_t g = ((((color >> 8) & 0xFF) * a + 127) / 255);
    uint32_t b = (((color & 0xFF) * a + 127) / 255);
    return (a << 24) | (r << 16) | (g << 8) | b;
}

// Un-multiply premultiplied ARGB: recover original RGB from premultiplied storage.
// Uses the same brute-force lookup table Ruffle uses, so the round-trip matches
// Flash exactly (generated by searching each alpha for the best recovery factor).
static const uint32_t FLASH_PREMUL_FACTOR[256] = {
    0, 16678912, 8339456, 5559638, 4169728, 3335783, 2779819, 2386603, 2086230, 1855488,
    1667892, 1518251, 1391151, 1285234, 1193302, 1111928, 1043895, 981113, 927744, 879275,
    834621, 795535, 759126, 726358, 695839, 668183, 642538, 618737, 596651, 576171, 555964,
    538706, 522104, 506319, 490557, 477321, 464038, 451353, 439544, 428244, 417582, 407500,
    397768, 388535, 379630, 371117, 363179, 355235, 348050, 340965, 334052, 327038, 321269,
    315077, 309159, 303586, 298189, 293092, 287981, 283080, 278251, 273892, 269268, 265179,
    261087, 256971, 253160, 249322, 245508, 242164, 238575, 235245, 231859, 228848, 225785,
    222712, 219616, 216827, 213985, 211432, 208835, 206075, 203750, 201196, 198895, 196223,
    194301, 191987, 189686, 187636, 185559, 183426, 181453, 179444, 177638, 175855, 174054,
    171948, 170489, 168695, 166889, 165365, 163519, 162045, 160508, 158970, 157429, 156150,
    154610, 153081, 151803, 150511, 148986, 147709, 146420, 145116, 143868, 142586, 141545,
    140277, 139194, 137957, 136954, 135676, 134652, 133621, 132604, 131577, 130552, 129527,
    128508, 127476, 126451, 125432, 124670, 123645, 122818, 121847, 121082, 120060, 119288,
    118263, 117502, 116720, 115967, 115195, 114424, 113655, 112893, 112125, 111356, 110563,
    109811, 109048, 108287, 107766, 107004, 106236, 105724, 104953, 104434, 103676, 102904,
    102375, 101879, 101119, 100604, 99834, 99321, 98813, 98112, 97533, 97019, 96509, 95994,
    95486, 94713, 94185, 93689, 93179, 92667, 92149, 91643, 91129, 90621, 90068, 89597,
    89342, 88829, 88318, 87804, 87294, 87034, 86523, 85994, 85499, 85245, 84732, 84222,
    83956, 83450, 82937, 82685, 82173, 81840, 81405, 80889, 80638, 80127, 79862, 79354,
    79103, 78590, 78332, 78077, 77565, 77308, 76795, 76541, 76284, 75766, 75518, 75262,
    74748, 74493, 74238, 73691, 73470, 73214, 72959, 72447, 72189, 71935, 71671, 71166,
    70911, 70651, 70399, 70140, 69886, 69615, 69116, 68861, 68603, 68350, 68093, 67839,
    67576, 67326, 67070, 66813, 66556, 66302, 66046, 65791, 65408,
};

static inline uint32_t unpremultiplyAlpha(uint32_t color)
{
    uint32_t a = (color >> 24) & 0xFF;
    if (a == 255) return color;
    if (a == 0) return 0;
    uint32_t factor = FLASH_PREMUL_FACTOR[a];
    uint32_t r = (color >> 16) & 0xFF;
    uint32_t g = (color >> 8) & 0xFF;
    uint32_t b = color & 0xFF;
    uint32_t ur = (r * factor + 0x8000) >> 16; if (ur > 255) ur = 255;
    uint32_t ug = (g * factor + 0x8000) >> 16; if (ug > 255) ug = 255;
    uint32_t ub = (b * factor + 0x8000) >> 16; if (ub > 255) ub = 255;
    return (a << 24) | (ur << 16) | (ug << 8) | ub;
}

// Coerce Math arguments to f64 via the stack (calls valueOf on objects).
// Flash coerces min(arg_count, max_args) arguments, left to right.
void coerceMathArgs(SWFAppContext* app_context, ActionVar* args, u32 arg_count, u32 max_args)
{
	u32 n = arg_count < max_args ? arg_count : max_args;
	for (u32 i = 0; i < n; i++)
	{
		pushVar(app_context, &args[i]);
		convertFloat(app_context);
		popVar(app_context, &args[i]);
	}
}

// Helper: extract f64 from a coerced ActionVar
double mathArgToDouble(ActionVar* v)
{
	if (v->type == ACTION_STACK_VALUE_F64)
		return VAL(double, &v->data.numeric_value);
	if (v->type == ACTION_STACK_VALUE_F32)
		return (double) VAL(float, &v->data.numeric_value);
	return NAN;
}

// Helper: return f64 ActionVar
ActionVar mathReturnDouble(double val)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_F64;
	ret.str_size = 0;
	VAL(double, &ret.data.numeric_value) = val;
	return ret;
}

