// --- ExternalInterface Phase 4: Bridge methods (available, addCallback, call) ---

// EI Callback registry — stores AS callbacks registered via addCallback
typedef struct {
	char name[128];
	ActionVar this_obj;    // The thisObj passed to addCallback
	ASFunction* func;      // The registered AS function
	int in_use;
} EICallback;

#define MAX_EI_CALLBACKS 32
static EICallback g_ei_callbacks[MAX_EI_CALLBACKS];
static int g_ei_callback_count = 0;

// Pluggable external call handler (set by test harness or host environment)
ExternalCallHandler g_external_call_handler = NULL;

// After-tick handler (set by test harness for post-frame callbacks)
AfterTickHandler g_after_tick_handler = NULL;

// ExternalInterface.available — returns true if external interface is available
static ActionVar actionEI_available(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_BOOLEAN;
	result.data.numeric_value = (g_external_call_handler != NULL) ? 1 : 0;
	return result;
}

// ExternalInterface.addCallback(name, thisObj, fn) — register AS callback
static ActionVar actionEI_addCallback(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};

	if (arg_count < 3 || g_external_call_handler == NULL)
	{
		result.type = ACTION_STACK_VALUE_BOOLEAN;
		result.data.numeric_value = 0;
		return result;
	}

	// Coerce name to string
	char name_buf[128];
	int name_len = varToStringBuf(app_context, &args[0], name_buf, sizeof(name_buf) - 1);
	name_buf[name_len] = '\0';

	// args[1] = thisObj, args[2] = function
	if (args[2].type != ACTION_STACK_VALUE_FUNCTION)
	{
		result.type = ACTION_STACK_VALUE_BOOLEAN;
		result.data.numeric_value = 0;
		return result;
	}

	// Store callback (overwrite existing with same name)
	int slot = -1;
	for (int i = 0; i < g_ei_callback_count; i++)
	{
		if (g_ei_callbacks[i].in_use && strcmp(g_ei_callbacks[i].name, name_buf) == 0)
		{
			slot = i;
			break;
		}
	}
	if (slot < 0)
	{
		// Find empty slot or append
		for (int i = 0; i < g_ei_callback_count; i++)
		{
			if (!g_ei_callbacks[i].in_use) { slot = i; break; }
		}
		if (slot < 0 && g_ei_callback_count < MAX_EI_CALLBACKS)
			slot = g_ei_callback_count++;
	}
	if (slot >= 0)
	{
		strncpy(g_ei_callbacks[slot].name, name_buf, 127);
		g_ei_callbacks[slot].name[127] = '\0';
		g_ei_callbacks[slot].this_obj = args[1];
		g_ei_callbacks[slot].func = (ASFunction*)(uintptr_t)args[2].data.numeric_value;
		g_ei_callbacks[slot].in_use = 1;
	}

	result.type = ACTION_STACK_VALUE_BOOLEAN;
	result.data.numeric_value = 1;
	return result;
}

// ExternalInterface.call(funcName, ...args) — call external function
static ActionVar actionEI_call(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};

	if (g_external_call_handler == NULL || arg_count < 1)
	{
		result.type = ACTION_STACK_VALUE_NULL;
		return result;
	}

	// Coerce funcName to string
	char name_buf[256];
	int name_len = varToStringBuf(app_context, &args[0], name_buf, sizeof(name_buf) - 1);
	name_buf[name_len] = '\0';

	// Pass remaining args to external handler
	ActionVar* call_args = (arg_count > 1) ? &args[1] : NULL;
	int call_arg_count = (arg_count > 1) ? (int)(arg_count - 1) : 0;

	return g_external_call_handler(app_context, name_buf, call_args, call_arg_count);
}

static ASFunction g_ei_available_func;
static ASFunction g_ei_addCallback_func;
static ASFunction g_ei_call_func;

// Public: Call a registered EI callback by name (for test harness / host)
// Invokes the AS function registered via addCallback with the given args.
// Returns the function's return value, or undefined if callback not found.
ActionVar actionEI_callInternalInterface(SWFAppContext* app_context, const char* name, ActionVar* args, int arg_count)
{
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;

	// Find callback
	EICallback* cb = NULL;
	for (int i = 0; i < g_ei_callback_count; i++)
	{
		if (g_ei_callbacks[i].in_use && strcmp(g_ei_callbacks[i].name, name) == 0)
		{
			cb = &g_ei_callbacks[i];
			break;
		}
	}
	if (cb == NULL || cb->func == NULL) return undef;

	g_call_depth++;
	if (g_call_depth > g_max_call_depth)
	{
		g_execution_halted = 1;
		g_call_depth--;
		return undef;
	}

	ASFunction* func = cb->func;
	void* this_obj = NULL;

	// Determine this_obj from the stored thisObj ActionVar
	if (cb->this_obj.type == ACTION_STACK_VALUE_OBJECT)
		this_obj = (void*)(uintptr_t)cb->this_obj.data.numeric_value;
	else if (cb->this_obj.type == ACTION_STACK_VALUE_MOVIECLIP)
		this_obj = (void*)(uintptr_t)cb->this_obj.data.numeric_value;

	ActionVar result;

	if (func->function_type == 2 && func->advanced_func != NULL)
	{
		ActionVar* registers = NULL;
		if (func->register_count > 0)
			registers = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		// Push local scope
		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		// Restore captured WITH scopes
		u32 captured_count = func->captured_scope_count;
		for (u32 i = 0; i < captured_count && scope_depth < MAX_SCOPE_DEPTH; i++)
		{
			scope_is_with[scope_depth] = 1;
			scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[i];
			scope_chain[scope_depth++] = (ASObject*)func->captured_scope[i];
		}

		// Switch base_clip context if SWF6+
		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		result = func->advanced_func(app_context, args, (u32)arg_count, registers, this_obj);

		g_current_context = saved_context;
		for (u32 i = 0; i < captured_count && scope_depth > 0; i++)
			scope_depth--;
		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (registers != NULL) FREE(registers);
	}
	else if (func->function_type == 1 && func->simple_func != NULL)
	{
		// Type 1: push args onto stack in reverse, set "this"
		for (int i = arg_count - 1; i >= 0; i--)
			pushVar(app_context, &args[i]);

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		u32 captured_count = func->captured_scope_count;
		for (u32 i = 0; i < captured_count && scope_depth < MAX_SCOPE_DEPTH; i++)
		{
			scope_is_with[scope_depth] = 1;
			scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[i];
			scope_chain[scope_depth++] = (ASObject*)func->captured_scope[i];
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		// Set "this"
		ActionVar this_var = {0};
		if (this_obj != NULL)
		{
			this_var.type = ACTION_STACK_VALUE_OBJECT;
			this_var.data.numeric_value = (u64)(uintptr_t)this_obj;
		}
		else
		{
			this_var.type = ACTION_STACK_VALUE_UNDEFINED;
		}
		setVariableByName("this", &this_var);

		result = ((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);

		g_current_context = saved_context;
		for (u32 i = 0; i < captured_count && scope_depth > 0; i++)
			scope_depth--;
		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}
	else
	{
		result = undef;
	}

	g_call_depth--;
	return result;
}

// Public: Convert an ActionVar STRING to a UTF-8 C string.
// Returns the number of bytes written (not including null terminator).
int ei_actionvar_to_utf8(ActionVar* var, char* buf, int buf_size)
{
	if (var == NULL || var->type != ACTION_STACK_VALUE_STRING)
	{
		buf[0] = '\0';
		return 0;
	}
	const uint16_t* u16 = (const uint16_t*)(uintptr_t)var->data.numeric_value;
	u32 u16_len = var->str_size;
	if (u16 == NULL || u16_len == 0) { buf[0] = '\0'; return 0; }
	int len = u16_to_utf8(u16, u16_len, buf, buf_size - 1);
	buf[len] = '\0';
	return len;
}

// Public: Set __proto__ on an object to Object.prototype (for test harness use)
void ei_set_object_proto(SWFAppContext* app_context, void* obj)
{
	setObjectProto(app_context, (ASObject*)obj);
}

// --- ASnative class 100: Global functions (escape, unescape, parseInt, parseFloat, trace) ---

static ActionVar asnative_100_escape(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count < 1) return result;
	// Coerce arg to string via stack
	pushVar(app_context, &args[0]);
	char sbuf[17];
	convertString(app_context, sbuf);
	const uint16_t* u16 = (const uint16_t*)STACK_TOP_VALUE;
	u32 u16_len = STACK_TOP_N;
	char utf8_buf[4096];
	int utf8_len = u16_to_utf8(u16, u16_len, utf8_buf, sizeof(utf8_buf));
	char* buf = (char*) HALLOC(utf8_len * 3 + 1);
	u32 out = 0;
	for (int i = 0; i < utf8_len; i++)
	{
		unsigned char c = (unsigned char) utf8_buf[i];
		if (c == 0) break;
		if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
			buf[out++] = c;
		else {
			buf[out++] = '%';
			buf[out++] = "0123456789ABCDEF"[c >> 4];
			buf[out++] = "0123456789ABCDEF"[c & 0x0F];
		}
	}
	buf[out] = '\0';
	POP();
	u32 res_u16_len;
	uint16_t* u16_result = ascii_to_u16(app_context, buf, out, &res_u16_len);
	result.type = ACTION_STACK_VALUE_STRING;
	result.str_size = res_u16_len;
	result.data.string_data.heap_ptr = u16_result;
	result.data.string_data.owns_memory = true;
	return result;
}

static ActionVar asnative_100_unescape(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count < 1) return result;
	pushVar(app_context, &args[0]);
	char sbuf[17];
	convertString(app_context, sbuf);
	const uint16_t* u16 = (const uint16_t*)STACK_TOP_VALUE;
	u32 u16_len = STACK_TOP_N;
	char utf8_buf[4096];
	int utf8_len = u16_to_utf8(u16, u16_len, utf8_buf, sizeof(utf8_buf));
	char* buf = (char*) HALLOC(utf8_len + 1);
	u32 out = 0;
	for (int i = 0; i < utf8_len; )
	{
		if (utf8_buf[i] == '%') {
			if (i + 5 < utf8_len && utf8_buf[i+1] == 'u' &&
			    isxdigit((unsigned char)utf8_buf[i+2]) && isxdigit((unsigned char)utf8_buf[i+3]) &&
			    isxdigit((unsigned char)utf8_buf[i+4]) && isxdigit((unsigned char)utf8_buf[i+5])) {
				buf[out++] = utf8_buf[i+2]; buf[out++] = utf8_buf[i+3];
				buf[out++] = utf8_buf[i+4]; buf[out++] = utf8_buf[i+5];
				i += 6; continue;
			}
			if (i + 2 < utf8_len &&
			    isxdigit((unsigned char)utf8_buf[i+1]) && isxdigit((unsigned char)utf8_buf[i+2])) {
				char hex[3] = { utf8_buf[i+1], utf8_buf[i+2], 0 };
				unsigned long val = strtoul(hex, NULL, 16);
				buf[out++] = (char) val;
				i += 3; continue;
			}
			i++;
			if (i < utf8_len) { int fh = isxdigit((unsigned char)utf8_buf[i]); i++; if (fh && i < utf8_len) i++; }
			continue;
		}
		if (utf8_buf[i] == '+') { buf[out++] = ' '; i++; }
		else { buf[out++] = utf8_buf[i++]; }
	}
	buf[out] = '\0';
	POP();
	u32 res_u16_len;
	uint16_t* u16_result = utf8_to_u16(app_context, buf, out, &res_u16_len);
	result.type = ACTION_STACK_VALUE_STRING;
	result.str_size = res_u16_len;
	result.data.string_data.heap_ptr = u16_result;
	result.data.string_data.owns_memory = true;
	return result;
}

static ActionVar asnative_100_trace(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count > 0) {
		pushVar(app_context, &args[0]);
		actionTrace(app_context);
	} else {
		printf("undefined\n");
	}
	return undef;
}

// ASnative(100, 2) = parseInt. Matches Flash/Ruffle semantics: leading
// whitespace skipped, optional sign, 0x prefix → hex (unless explicit
// radix), leading zeros → octal, stops at first non-digit.
static ActionVar asnative_100_parseInt(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count == 0) return undef;

	// Coerce arg[0] to UTF-8 string
	char sbuf[1024];
	const char* s = NULL;
	if (args[0].type == ACTION_STACK_VALUE_STRING) {
		const uint16_t* u16 = varGetU16Ptr(&args[0]);
		u16_to_utf8(u16, args[0].str_size, sbuf, sizeof(sbuf));
		s = sbuf;
	} else if (args[0].type == ACTION_STACK_VALUE_F32) {
		float f = VAL(float, &args[0].data.numeric_value);
		flash_format_double(sbuf, sizeof(sbuf), (double)f);
		s = sbuf;
	} else if (args[0].type == ACTION_STACK_VALUE_F64) {
		double d = VAL(double, &args[0].data.numeric_value);
		flash_format_double(sbuf, sizeof(sbuf), d);
		s = sbuf;
	} else if (args[0].type == ACTION_STACK_VALUE_BOOLEAN) {
		s = args[0].data.numeric_value ? "true" : "false";
	} else if (args[0].type == ACTION_STACK_VALUE_NULL) {
		s = "null";
	} else if (args[0].type == ACTION_STACK_VALUE_OBJECT ||
	           args[0].type == ACTION_STACK_VALUE_ARRAY ||
	           args[0].type == ACTION_STACK_VALUE_FUNCTION) {
		int slen = varToStringBuf(app_context, &args[0], sbuf, sizeof(sbuf) - 1);
		sbuf[slen] = '\0';
		s = sbuf;
	} else {
		s = "undefined";
	}

	int has_explicit_radix = (arg_count >= 2);
	int radix = 0;
	int radix_valid = 1;
	if (has_explicit_radix) {
		double rv = 0.0;
		if (args[1].type == ACTION_STACK_VALUE_F32)      rv = (double)VAL(float, &args[1].data.numeric_value);
		else if (args[1].type == ACTION_STACK_VALUE_F64) rv = VAL(double, &args[1].data.numeric_value);
		else if (args[1].type == ACTION_STACK_VALUE_BOOLEAN) rv = args[1].data.numeric_value ? 1.0 : 0.0;
		if (rv != rv || rv == 0.0) radix = 0;
		else radix = (int)rv;
		if (radix < 2 || radix > 36) radix_valid = 0;
	}

	double result = NAN;
	if (radix_valid) {
		int slen = (int)strlen(s);
		int has_sign = (slen > 0 && (s[0] == '+' || s[0] == '-'));
		int sign_off = has_sign ? 1 : 0;

		int is_hex = 0;
		if (sign_off < slen && s[sign_off] == '0' && sign_off + 1 < slen &&
		    (s[sign_off + 1] == 'x' || s[sign_off + 1] == 'X')) {
			is_hex = 1;
		}

		int ignore_sign = 0;
		const char* p = s;
		int parse_radix = radix ? radix : 10;

		if (is_hex) {
			if (has_sign) {
				if (!has_explicit_radix || parse_radix <= 33) goto pi_done;
				ignore_sign = 1;
			} else {
				p = s + 2;
				if (!has_explicit_radix) parse_radix = 16;
			}
		} else if (!has_explicit_radix && sign_off < slen && s[sign_off] == '0') {
			int all_octal = 1;
			for (int i = sign_off; i < slen; i++) {
				if (s[i] < '0' || s[i] > '7') { all_octal = 0; break; }
			}
			if (all_octal) parse_radix = 8;
		}

		while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;

		double sign = 1.0;
		if (*p == '+' || *p == '-') {
			if (!ignore_sign) sign = (*p == '-') ? -1.0 : 1.0;
			p++;
		}

		int found = 0;
		result = 0.0;
		while (*p) {
			int digit = -1;
			char c = *p;
			if (c >= '0' && c <= '9') digit = c - '0';
			else if (c >= 'a' && c <= 'z') digit = 10 + (c - 'a');
			else if (c >= 'A' && c <= 'Z') digit = 10 + (c - 'A');
			if (digit < 0 || digit >= parse_radix) break;
			result = result * (double)parse_radix + (double)digit;
			found = 1;
			p++;
		}

		if (!found) result = NAN;
		else if (sign < 0) result = -result;
	}

pi_done: {
		ActionVar r = {0};
		if (result != result) {
			float nan_val = 0.0f / 0.0f;
			r.type = ACTION_STACK_VALUE_F32;
			VAL(u32, &r.data.numeric_value) = VAL(u32, &nan_val);
		} else if (result == (double)(float)result && result < 1e18) {
			float fres = (float)result;
			r.type = ACTION_STACK_VALUE_F32;
			VAL(u32, &r.data.numeric_value) = VAL(u32, &fres);
		} else {
			r.type = ACTION_STACK_VALUE_F64;
			VAL(u64, &r.data.numeric_value) = VAL(u64, &result);
		}
		return r;
	}
}

// ASnative(100, 3) = parseFloat. Matches Flash semantics: skip ws, optional
// sign, digits with optional decimal, optional exponent with wrapping i32
// arithmetic, multiple dots OK, stops at first non-digit.
static ActionVar asnative_100_parseFloat(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count == 0) return undef;

	char cs_buf[17];
	pushVar(app_context, &args[0]);
	convertString(app_context, cs_buf);
	ActionVar str_var;
	popVar(app_context, &str_var);
	char buf[512];
	const uint16_t* u16 = varGetU16Ptr(&str_var);
	u16_to_utf8(u16, str_var.str_size, buf, sizeof(buf));
	const char* s = buf;

	while (*s == ' ' || *s == '\t' || *s == '\r' || *s == '\n' || *s == '\f') s++;

	int is_neg = 0;
	if (*s == '-') { is_neg = 1; s++; }
	else if (*s == '+') s++;

	const char* after_sign = s;
	while (*s >= '0' && *s <= '9') s++;
	int digits_before = (int)(s - after_sign);

	if (*s == '.') s++;
	const char* after_dot = s;
	while (*s >= '0' && *s <= '9') s++;
	int digits_after = (int)(s - after_dot);

	if (digits_before == 0 && digits_after == 0) {
		ActionVar r = {0};
		double nan_val = NAN;
		r.type = ACTION_STACK_VALUE_F64;
		VAL(u64, &r.data.numeric_value) = VAL(u64, &nan_val);
		return r;
	}

	int total_int_digits = digits_before;
	int32_t exp = (int32_t)(total_int_digits - 1);

	if (*s == 'e' || *s == 'E') {
		s++;
		int exp_neg = 0;
		if (*s == '-') { exp_neg = 1; s++; }
		else if (*s == '+') s++;
		int32_t exponent = 0;
		const char* exp_start = s;
		while (*s >= '0' && *s <= '9') {
			exponent = (int32_t)((uint32_t)exponent * 10u);
			exponent = (int32_t)((uint32_t)exponent + (uint32_t)(*s - '0'));
			s++;
		}
		if (s > exp_start) {
			if (exp_neg) exponent = (int32_t)(-(uint32_t)exponent);
			exp = (int32_t)((uint32_t)exp + (uint32_t)exponent);
		}
	}

	double result = 0.0;
	const char* p = after_sign;
	int32_t cur_exp = exp;
	while (*p) {
		if (*p >= '0' && *p <= '9') {
			int digit = *p - '0';
			if (digit != 0) result += (double)digit * pow(10.0, (double)cur_exp);
			cur_exp = (int32_t)((uint32_t)cur_exp - 1u);
		} else if (*p == '.') {
			// multiple dots skipped
		} else {
			break;
		}
		p++;
	}

	if (is_neg) result = -result;

	ActionVar r = {0};
	r.type = ACTION_STACK_VALUE_F64;
	VAL(u64, &r.data.numeric_value) = VAL(u64, &result);
	return r;
}

// Class 100 function table: (0=escape, 1=unescape, 2=parseInt, 3=parseFloat, 4=trace)
#define ASNATIVE_100_COUNT 5
static ASFunction g_asnative_100_funcs[ASNATIVE_100_COUNT];
static int g_asnative_100_init = 0;

static void init_asnative_100(void)
{
	if (g_asnative_100_init) return;
	struct { const char* name; Function2Ptr func; } table[] = {
		{"escape",     (Function2Ptr)asnative_100_escape},
		{"unescape",   (Function2Ptr)asnative_100_unescape},
		{"parseInt",   (Function2Ptr)asnative_100_parseInt},
		{"parseFloat", (Function2Ptr)asnative_100_parseFloat},
		{"trace",      (Function2Ptr)asnative_100_trace},
	};
	for (int i = 0; i < ASNATIVE_100_COUNT; i++) {
		memset(&g_asnative_100_funcs[i], 0, sizeof(ASFunction));
		strncpy(g_asnative_100_funcs[i].name, table[i].name, 255);
		g_asnative_100_funcs[i].function_type = 2;
		g_asnative_100_funcs[i].advanced_func = table[i].func;
		if (table[i].func && function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_asnative_100_funcs[i];
	}
	g_asnative_100_init = 1;
}

// --- ASnative class 2: ASNew (constructor context detection) ---

// Constructor call context tracking stack
#define MAX_CTOR_CONTEXT_DEPTH 64
static u8 g_ctor_context_stack[MAX_CTOR_CONTEXT_DEPTH];
static int g_ctor_context_sp = 0;

void pushCtorContext(u8 is_constructor) {
	if (g_ctor_context_sp < MAX_CTOR_CONTEXT_DEPTH)
		g_ctor_context_stack[g_ctor_context_sp++] = is_constructor;
}
void popCtorContext(void) {
	if (g_ctor_context_sp > 0)
		g_ctor_context_sp--;
}
static u8 isInCtorContext(void) {
	return (g_ctor_context_sp > 0) ? g_ctor_context_stack[g_ctor_context_sp - 1] : 0;
}

static ActionVar asnative_2_asnew(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_BOOLEAN;
	result.data.numeric_value = isInCtorContext() ? 1 : 0;
	return result;
}

static ASFunction g_asnative_2_asnew;
static int g_asnative_2_init = 0;

static void init_asnative_2(void)
{
	if (g_asnative_2_init) return;
	memset(&g_asnative_2_asnew, 0, sizeof(ASFunction));
	strncpy(g_asnative_2_asnew.name, "ASnew", 255);
	g_asnative_2_asnew.function_type = 2;
	g_asnative_2_asnew.advanced_func = (Function2Ptr)asnative_2_asnew;
	if (function_count < MAX_FUNCTIONS)
		function_registry[function_count++] = &g_asnative_2_asnew;
	g_asnative_2_init = 1;
}

static ASObject* getObjectPrototype(SWFAppContext* app_context); // forward decl for ASnative class 101

// --- ASnative class 252: Array constructor + prototype methods ---

static void initArrayProto(SWFAppContext* app_context, ASArray* arr); // forward decl

// Callable Array constructor — creates array when called as f(args) (not just new Array())
static ActionVar builtin_asnative_array_ctor(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ASArray* arr;
	if (arg_count == 1 && (args[0].type == ACTION_STACK_VALUE_F64 || args[0].type == ACTION_STACK_VALUE_F32)) {
		// Array(n) — creates empty array with length n
		double d = (args[0].type == ACTION_STACK_VALUE_F64)
			? VAL(double, &args[0].data.numeric_value)
			: (double)VAL(float, &args[0].data.numeric_value);
		u32 len = (u32)d;
		arr = allocArray(app_context, len > 0 ? len : 4);
		arr->length = len;
	} else {
		// Array(a, b, c) — creates [a, b, c]
		arr = allocArray(app_context, arg_count > 0 ? arg_count : 4);
		arr->length = arg_count;
		for (u32 i = 0; i < arg_count; i++) {
			arr->elements[i] = args[i];
		}
	}
	// Set up prototype chain so arr.pop/push/etc. resolve via Array.prototype
	initArrayProto(app_context, arr);
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_ARRAY;
	VAL(u64, &result.data.numeric_value) = (u64)arr;
	return result;
}

static ASFunction g_asnative_252_ctor;
static int g_asnative_252_init = 0;

// ASnative(class_id, method_index) — returns a native method by numeric address.
// Handles class 2 (ASNew), class 101 (Object.prototype), class 100 (global functions), class 200 (Math), class 252 (Array).
static ActionVar builtin_asnative(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (arg_count != 2) return undef;

	// Coerce both args via valueOf (handles objects with valueOf, strings, etc.)
	coerceMathArgs(app_context, args, 2, 2);
	double class_d = mathArgToDouble(&args[0]);
	double method_d = mathArgToDouble(&args[1]);

	// ECMAScript ToUint32 wrapping for both arguments
	u32 class_id = ecmaToUint32(class_d);
	u32 method_u32 = ecmaToUint32(method_d);
	// Saturate method index to u16 (values >= 65536 → 65535, which maps to nothing)
	u16 method_index = (method_u32 <= 0xFFFF) ? (u16)method_u32 : 0xFFFF;

	if (class_id == 2) {
		init_asnative_2();
		if (method_index == 0) {
			ActionVar result = {0};
			result.type = ACTION_STACK_VALUE_FUNCTION;
			VAL(u64, &result.data.numeric_value) = (u64)&g_asnative_2_asnew;
			return result;
		}
		return undef;
	}

	// Class 101: Object.prototype methods
	// Flash ASnative(101, N): 0=watch, 1=unwatch, 2=addProperty, 3=valueOf,
	// 4=toString, 5=hasOwnProperty, 6=isPropertyEnumerable, 7=isPrototypeOf
	if (class_id == 101) {
		// Ensure Object.prototype is initialized (which initializes the functions)
		getObjectPrototype(app_context);
		ASFunction* obj_methods[] = {
			&g_object_watch_func,                // 0
			&g_object_unwatch_func,              // 1
			&g_object_addProperty_func,          // 2
			&g_object_valueOf_func,              // 3
			&g_object_toString_func,             // 4
			&g_object_hasOwnProperty_func,       // 5
			&g_object_isPropertyEnumerable_func, // 6
			&g_object_isPrototypeOf_func,        // 7
		};
		if (method_index <= 7) {
			ASFunction* fn = obj_methods[method_index];
			if (fn->advanced_func != NULL || fn->simple_func != NULL) {
				ActionVar result = {0};
				result.type = ACTION_STACK_VALUE_FUNCTION;
				VAL(u64, &result.data.numeric_value) = (u64)fn;
				return result;
			}
		}
		return undef;
	}

	if (class_id == 100) {
		init_asnative_100();
		if (method_index < ASNATIVE_100_COUNT && g_asnative_100_funcs[method_index].advanced_func != NULL) {
			ActionVar result = {0};
			result.type = ACTION_STACK_VALUE_FUNCTION;
			VAL(u64, &result.data.numeric_value) = (u64)&g_asnative_100_funcs[method_index];
			return result;
		}
		return undef;
	}

	// Class 103: Date — getters/setters, constructor, and UTC. Index mapping in date.c.
	if (class_id == 103) {
		// method_u32 is the already-saturated u16 index, so use it directly for the
		// date table (which supports indices up to 257).
		u16 idx = (method_u32 <= 0xFFFF) ? (u16)method_u32 : 0xFFFF;
		ASFunction* fn = actionDateGetASnativeMethod(app_context, idx);
		if (fn != NULL) {
			ActionVar result = {0};
			result.type = ACTION_STACK_VALUE_FUNCTION;
			VAL(u64, &result.data.numeric_value) = (u64)fn;
			return result;
		}
		return undef;
	}

	if (class_id == 200) {
		// Math class: ensure the Math object and its function table are ready
		initMathObject(app_context);
		// Flash ASnative(200, N) index order (matches Ruffle and Flash docs):
		//  0=abs  1=min    2=max   3=sin  4=cos   5=atan2 6=tan  7=exp  8=log
		//  9=sqrt 10=round 11=random 12=floor 13=ceil 14=atan 15=asin 16=acos
		// 17=pow. Our internal g_math_funcs[] order differs (abs, sin, cos, ...),
		// so remap through a small table.
		static const int asnative_200_to_math[] = {
			 0,  // 0 = abs
			15,  // 1 = min
			16,  // 2 = max
			 1,  // 3 = sin
			 2,  // 4 = cos
			13,  // 5 = atan2
			 3,  // 6 = tan
			 4,  // 7 = exp
			 5,  // 8 = log
			 6,  // 9 = sqrt
			 7,  // 10 = round
			17,  // 11 = random
			 8,  // 12 = floor
			 9,  // 13 = ceil
			10,  // 14 = atan
			11,  // 15 = asin
			12,  // 16 = acos
			14,  // 17 = pow
		};
		int internal_idx = -1;
		if (method_index < (sizeof(asnative_200_to_math) / sizeof(asnative_200_to_math[0]))) {
			internal_idx = asnative_200_to_math[method_index];
		}
		ASFunction* fn = (internal_idx >= 0) ? actionMathGetFunc(internal_idx) : NULL;
		if (fn == NULL) {
			// Out-of-range index → NaN stub (still coerces its args via valueOf)
			fn = actionMathGetNaNStub();
			// Register the NaN stub exactly once so it appears in function_registry
			static int g_nan_stub_registered = 0;
			if (!g_nan_stub_registered) {
				if (function_count < MAX_FUNCTIONS)
					function_registry[function_count++] = fn;
				g_nan_stub_registered = 1;
			}
		}
		ActionVar result = {0};
		result.type = ACTION_STACK_VALUE_FUNCTION;
		VAL(u64, &result.data.numeric_value) = (u64)fn;
		return result;
	}

	// Class 252: Array — constructor (0) and prototype methods (1-12)
	// Flash ASnative(252, N): 0=constructor, 1=push, 2=pop, 3=concat,
	// 4=shift, 5=unshift, 6=slice, 7=join, 8=splice, 9=sort, 10=reverse,
	// 11=toString, 12=sortOn
	if (class_id == 252) {
		// Ensure Array.prototype methods are initialized
		initArrayPrototypeMethods(app_context);

		if (method_index == 0) {
			// Array constructor
			if (!g_asnative_252_init) {
				memset(&g_asnative_252_ctor, 0, sizeof(ASFunction));
				strncpy(g_asnative_252_ctor.name, "Array", 255);
				g_asnative_252_ctor.function_type = 2;
				g_asnative_252_ctor.advanced_func = (Function2Ptr)builtin_asnative_array_ctor;
				if (function_count < MAX_FUNCTIONS)
					function_registry[function_count++] = &g_asnative_252_ctor;
				g_asnative_252_init = 1;
			}
			ActionVar result = {0};
			result.type = ACTION_STACK_VALUE_FUNCTION;
			VAL(u64, &result.data.numeric_value) = (u64)&g_asnative_252_ctor;
			return result;
		}

		// Map ASnative index (1-12) to g_array_proto_funcs[] index
		// ASnative: 1=push(0), 2=pop(1), 3=concat(7), 4=shift(2), 5=unshift(3),
		//           6=slice(8), 7=join(5), 8=splice(9), 9=sort(10), 10=reverse(4),
		//           11=toString(6), 12=sortOn(11)
		static const int asnative_to_proto[] = {
			-1,  // 0 = constructor (handled above)
			 0,  // 1 = push
			 1,  // 2 = pop
			 7,  // 3 = concat
			 2,  // 4 = shift
			 3,  // 5 = unshift
			 8,  // 6 = slice
			 5,  // 7 = join
			 9,  // 8 = splice
			10,  // 9 = sort
			 4,  // 10 = reverse
			 6,  // 11 = toString
			11,  // 12 = sortOn
		};
		if (method_index >= 1 && method_index <= 12) {
			int proto_idx = asnative_to_proto[method_index];
			ASFunction* fn = &g_array_proto_funcs[proto_idx];
			if (fn->advanced_func != NULL) {
				ActionVar result = {0};
				result.type = ACTION_STACK_VALUE_FUNCTION;
				VAL(u64, &result.data.numeric_value) = (u64)fn;
				return result;
			}
		}
		return undef;
	}

	return undef;
}

// (initMathObject is in math.c, declared in actionmodern/actionmath.h)

// ============================================================================
// Date class — carved out to date.c (see actionmodern/actiondate.h)
// ============================================================================


// ============================================================================

// Built-in valueOf for primitive wrapper objects (new Object(5))
static ActionVar builtin_wrapper_valueOf(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ret.str_size = 0;
	ret.data.numeric_value = 0;

	if (this_obj != NULL)
	{
		ASObject* obj = (ASObject*) this_obj;
		ActionVar* prim = getProperty(obj, "valueOf_value", 13);
		if (prim != NULL)
			ret = *prim;
	}
	return ret;
}

// Built-in toString for Object(primitive) wrappers — returns primitive value as string
// For Number wrappers, supports optional radix argument (2-36)
static ActionVar builtin_prim_wrapper_toString(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 0;
	ret.data.numeric_value = 0;

	if (this_obj != NULL)
	{
		ASObject* obj = (ASObject*) this_obj;
		ActionVar* prim = getProperty(obj, "valueOf_value", 13);
		if (prim != NULL)
		{
			if (prim->type == ACTION_STACK_VALUE_STRING)
			{
				return *prim;
			}
			// Number wrapper with radix support
			if (obj->native_type == NATIVE_NUMBER &&
			    (prim->type == ACTION_STACK_VALUE_F32 || prim->type == ACTION_STACK_VALUE_F64))
			{
				int radix = 10;
				if (arg_count >= 1 && args != NULL)
				{
					double rv = 0;
					if (args[0].type == ACTION_STACK_VALUE_F64)
						rv = VAL(double, &args[0].data.numeric_value);
					else if (args[0].type == ACTION_STACK_VALUE_F32)
						rv = (double)VAL(float, &args[0].data.numeric_value);
					if (!isnan(rv) && rv >= 2.0 && rv <= 36.0)
						radix = (int)rv;
				}
				double dval = (prim->type == ACTION_STACK_VALUE_F64)
					? VAL(double, &prim->data.numeric_value)
					: (double)VAL(float, &prim->data.numeric_value);
				static char _nwt_buf[256];
				int _nwt_len = 0;
				if (isnan(dval)) {
					if (radix == 10) { _nwt_len = 3; memcpy(_nwt_buf, "NaN", 3); }
					else {
						uint32_t _nwt_uval = 2147483648U;
						char _nwt_tmp[128]; int _nwt_pos = 0;
						uint32_t _nwt_n = _nwt_uval;
						while (_nwt_n > 0 && _nwt_pos < 127) {
							int d = (int)(_nwt_n % (uint32_t)radix);
							char c = (char)(48 - d);
							if (c == '\r') c = '\n';
							_nwt_tmp[_nwt_pos++] = c;
							_nwt_n /= (uint32_t)radix;
						}
						_nwt_buf[0] = '-'; _nwt_len = 1;
						for (int j = _nwt_pos - 1; j >= 0 && _nwt_len < 255; j--)
							_nwt_buf[_nwt_len++] = _nwt_tmp[j];
					}
				} else if (isinf(dval)) {
					_nwt_len = (dval > 0) ? 8 : 9;
					memcpy(_nwt_buf, (dval > 0) ? "Infinity" : "-Infinity", _nwt_len);
				} else if (radix == 10) {
					_nwt_len = flash_format_double(_nwt_buf, sizeof(_nwt_buf), dval);
					if (_nwt_len < 0) _nwt_len = 0;
				} else {
					int negative = (dval < 0.0);
					double absval = negative ? -dval : dval;
					unsigned long long ival = (unsigned long long)absval;
					if (ival == 0) { _nwt_buf[0] = '0'; _nwt_len = 1; }
					else {
						const char* digits = "0123456789abcdefghijklmnopqrstuvwxyz";
						char tmp[128]; int pos = 0;
						unsigned long long n = ival;
						while (n > 0 && pos < 127) { tmp[pos++] = digits[n % radix]; n /= radix; }
						if (negative) _nwt_buf[_nwt_len++] = '-';
						for (int j = pos - 1; j >= 0 && _nwt_len < 255; j--)
							_nwt_buf[_nwt_len++] = tmp[j];
					}
				}
				_nwt_buf[_nwt_len] = '\0';
				u32 u16_len;
				uint16_t* u16_ptr = ascii_to_u16(app_context, _nwt_buf, _nwt_len, &u16_len);
				ret.data.numeric_value = (u64) u16_ptr;
				ret.str_size = u16_len;
				return ret;
			}
			// Non-Number wrapper: convert primitive to string
			{
				static char buf[64];
				int len = varToStringBuf(app_context, prim, buf, sizeof(buf));
				u32 u16_len;
				uint16_t* u16_ptr = ascii_to_u16(app_context, buf, len, &u16_len);
				ret.data.numeric_value = (u64) u16_ptr;
				ret.str_size = u16_len;
				return ret;
			}
		}
	}
	ret.data.numeric_value = (u64) u16_object_Object;
	ret.str_size = 15;
	return ret;
}

static ASFunction g_wrapper_valueOf_func;
static ASFunction g_prim_wrapper_toString_func;
static int g_wrapper_funcs_init = 0;

// Get or create the global Object.prototype
static ASObject* getObjectPrototype(SWFAppContext* app_context)
{
	if (g_object_prototype == NULL)
	{
		g_object_prototype = allocObject(app_context, 12);
		retainObject(g_object_prototype);

		// Object.prototype methods — insertion order determines LIFO enumeration.
		// Expected LIFO enum: toLocaleString, isPropertyEnumerable, isPrototypeOf, hasOwnProperty,
		//   toString, valueOf, addProperty, unwatch, watch, constructor
		// So insert in reverse: constructor(placeholder), watch, unwatch, addProperty, valueOf,
		//   toString, hasOwnProperty, isPrototypeOf, isPropertyEnumerable, toLocaleString

		// Object.prototype methods are DONTDELETE in Flash/Ruffle (ECMAScript default
		// for built-in prototypes). We keep ENUMERABLE since enumerate tests rely on
		// the current behavior, but clear CONFIGURABLE so delete returns false until
		// ASSetPropFlags re-enables deletion. Flags = ENUMERABLE|WRITABLE.
		#define _OBJPROTO_DONTDELETE (PROPERTY_FLAG_ENUMERABLE | PROPERTY_FLAG_WRITABLE)

		// constructor placeholder — filled in by ensureGlobalInit with Object constructor.
		// Inserted first so it enumerates last in LIFO.
		{
			ActionVar _u = {0}; _u.type = ACTION_STACK_VALUE_UNDEFINED;
			setPropertyWithFlags(app_context, g_object_prototype, "constructor", 11, &_u, PROPERTY_FLAG_WRITABLE);
		}

		// watch
		memset(&g_object_watch_func, 0, sizeof(ASFunction));
		strncpy(g_object_watch_func.name, "watch", 255);
		g_object_watch_func.function_type = 2;
		g_object_watch_func.param_count = 2;
		g_object_watch_func.advanced_func = (Function2Ptr) builtin_object_watch;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_watch_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_watch_func;
			setPropertyWithFlags(app_context, g_object_prototype, "watch", 5, &fv, _OBJPROTO_DONTDELETE);
		}

		// unwatch
		memset(&g_object_unwatch_func, 0, sizeof(ASFunction));
		strncpy(g_object_unwatch_func.name, "unwatch", 255);
		g_object_unwatch_func.function_type = 2;
		g_object_unwatch_func.param_count = 1;
		g_object_unwatch_func.advanced_func = (Function2Ptr) builtin_object_unwatch;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_unwatch_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_unwatch_func;
			setPropertyWithFlags(app_context, g_object_prototype, "unwatch", 7, &fv, _OBJPROTO_DONTDELETE);
		}

		// addProperty
		memset(&g_object_addProperty_func, 0, sizeof(ASFunction));
		strncpy(g_object_addProperty_func.name, "addProperty", 255);
		g_object_addProperty_func.function_type = 2;
		g_object_addProperty_func.param_count = 3;
		g_object_addProperty_func.advanced_func = (Function2Ptr) builtin_object_addProperty;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_addProperty_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_addProperty_func;
			setPropertyWithFlags(app_context, g_object_prototype, "addProperty", 11, &fv, _OBJPROTO_DONTDELETE);
		}

		// valueOf
		memset(&g_object_valueOf_func, 0, sizeof(ASFunction));
		strncpy(g_object_valueOf_func.name, "valueOf", 255);
		g_object_valueOf_func.function_type = 2;
		g_object_valueOf_func.param_count = 0;
		g_object_valueOf_func.advanced_func = (Function2Ptr) builtin_object_valueOf;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_valueOf_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_valueOf_func;
			setPropertyWithFlags(app_context, g_object_prototype, "valueOf", 7, &fv, _OBJPROTO_DONTDELETE);
		}

		// toString
		memset(&g_object_toString_func, 0, sizeof(ASFunction));
		strncpy(g_object_toString_func.name, "toString", 255);
		g_object_toString_func.function_type = 1;
		g_object_toString_func.param_count = 0;
		g_object_toString_func.simple_func = (SimpleFunctionPtr) builtin_object_toString;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_toString_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_toString_func;
			setPropertyWithFlags(app_context, g_object_prototype, "toString", 8, &fv, _OBJPROTO_DONTDELETE);
		}

		// hasOwnProperty
		memset(&g_object_hasOwnProperty_func, 0, sizeof(ASFunction));
		strncpy(g_object_hasOwnProperty_func.name, "hasOwnProperty", 255);
		g_object_hasOwnProperty_func.function_type = 2;
		g_object_hasOwnProperty_func.param_count = 1;
		g_object_hasOwnProperty_func.advanced_func = (Function2Ptr) builtin_object_hasOwnProperty;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_hasOwnProperty_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_hasOwnProperty_func;
			setPropertyWithFlags(app_context, g_object_prototype, "hasOwnProperty", 14, &fv, _OBJPROTO_DONTDELETE);
		}

		// isPrototypeOf
		memset(&g_object_isPrototypeOf_func, 0, sizeof(ASFunction));
		strncpy(g_object_isPrototypeOf_func.name, "isPrototypeOf", 255);
		g_object_isPrototypeOf_func.function_type = 2;
		g_object_isPrototypeOf_func.param_count = 1;
		g_object_isPrototypeOf_func.advanced_func = (Function2Ptr) builtin_object_isPrototypeOf;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_isPrototypeOf_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_isPrototypeOf_func;
			setPropertyWithFlags(app_context, g_object_prototype, "isPrototypeOf", 13, &fv, _OBJPROTO_DONTDELETE);
		}

		// isPropertyEnumerable
		memset(&g_object_isPropertyEnumerable_func, 0, sizeof(ASFunction));
		strncpy(g_object_isPropertyEnumerable_func.name, "isPropertyEnumerable", 255);
		g_object_isPropertyEnumerable_func.function_type = 2;
		g_object_isPropertyEnumerable_func.param_count = 1;
		g_object_isPropertyEnumerable_func.advanced_func = (Function2Ptr) builtin_object_isPropertyEnumerable;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_object_isPropertyEnumerable_func;
		{
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_isPropertyEnumerable_func;
			setPropertyWithFlags(app_context, g_object_prototype, "isPropertyEnumerable", 20, &fv, _OBJPROTO_DONTDELETE);
		}

		// toLocaleString (delegates to toString)
		{
			static ASFunction g_object_toLocaleString_func;
			memset(&g_object_toLocaleString_func, 0, sizeof(ASFunction));
			strncpy(g_object_toLocaleString_func.name, "toLocaleString", 255);
			g_object_toLocaleString_func.function_type = 1;
			g_object_toLocaleString_func.param_count = 0;
			g_object_toLocaleString_func.simple_func = (SimpleFunctionPtr) builtin_object_toString;
			if (function_count < MAX_FUNCTIONS)
				function_registry[function_count++] = &g_object_toLocaleString_func;
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION;
			fv.data.numeric_value = (u64) &g_object_toLocaleString_func;
			setPropertyWithFlags(app_context, g_object_prototype, "toLocaleString", 14, &fv, _OBJPROTO_DONTDELETE);

			// Set up own_props (constructor + __proto__) and no_lazy_prototype on all
			// Object.prototype method functions. This prevents lazy prototype creation
			// (so `func.prototype` returns undefined) and gives each function its own
			// __proto__ + constructor for proper enumeration in global_proto_decls.
			setupNativeFuncOwnProps(app_context, &g_object_watch_func);
			setupNativeFuncOwnProps(app_context, &g_object_unwatch_func);
			setupNativeFuncOwnProps(app_context, &g_object_addProperty_func);
			setupNativeFuncOwnProps(app_context, &g_object_valueOf_func);
			setupNativeFuncOwnProps(app_context, &g_object_toString_func);
			setupNativeFuncOwnProps(app_context, &g_object_hasOwnProperty_func);
			setupNativeFuncOwnProps(app_context, &g_object_isPrototypeOf_func);
			setupNativeFuncOwnProps(app_context, &g_object_isPropertyEnumerable_func);
			setupNativeFuncOwnProps(app_context, &g_object_toLocaleString_func);
		}

		// Mark all built-in Object.prototype properties as non-enumerable (DontEnum)
		for (u32 i = 0; i < g_object_prototype->num_used; i++)
			g_object_prototype->properties[i].flags &= ~PROPERTY_FLAG_ENUMERABLE;

		// Mark SWF6+ methods with flash_flags for version-based hiding.
		// flash_flags 0x0080: hidden in SWF5 (mask 0x7480), visible in SWF6+ (mask 0x7500).
		// This ensures the methods exist (preventing singleton poison) but are invisible in SWF5.
		static const char* swf6_methods[] = {
			"hasOwnProperty", "isPropertyEnumerable", "isPrototypeOf",
			"watch", "unwatch", "addProperty"
		};
		for (int m = 0; m < 6; m++) {
			u32 mlen = (u32)strlen(swf6_methods[m]);
			for (u32 i = 0; i < g_object_prototype->num_used; i++) {
				if (g_object_prototype->properties[i].name_length == mlen &&
				    memcmp(g_object_prototype->properties[i].name, swf6_methods[m], mlen) == 0) {
					g_object_prototype->properties[i].flash_flags = 0x0080;
					break;
				}
			}
		}
	}
	return g_object_prototype;
}

// Set __proto__ to Object.prototype on a user-created object
void setObjectProto(SWFAppContext* app_context, ASObject* obj)
{
	ASObject* proto = getObjectPrototype(app_context);
	ActionVar proto_var;
	proto_var.type = ACTION_STACK_VALUE_OBJECT;
	proto_var.str_size = 0;
	proto_var.data.numeric_value = (u64) proto;
	setPropertyWithFlags(app_context, obj, "__proto__", 9, &proto_var, PROPERTY_FLAG_WRITABLE);
}

// Make __proto__ READ_ONLY on an object (after setObjectProto established it).
// Used for singleton globals (Accessibility, Key, Math, Mouse, Selection, etc.)
void makeProtoReadOnly(ASObject* obj)
{
	for (u32 i = 0; i < obj->num_used; i++) {
		if (obj->properties[i].name_length == 9 && strncmp(obj->properties[i].name, "__proto__", 9) == 0) {
			obj->properties[i].flags = 0; // no ENUMERABLE, no WRITABLE, no CONFIGURABLE
			break;
		}
	}
}

// Like setObjectProto but sets __proto__ as ENUMERABLE.
// Used for built-in prototype objects where Flash exposes __proto__ in for-in.
static void setObjectProtoEnum(SWFAppContext* app_context, ASObject* obj)
{
	ASObject* proto = getObjectPrototype(app_context);
	ActionVar proto_var;
	proto_var.type = ACTION_STACK_VALUE_OBJECT;
	proto_var.str_size = 0;
	proto_var.data.numeric_value = (u64) proto;
	setPropertyWithFlags(app_context, obj, "__proto__", 9, &proto_var, PROPERTY_FLAGS_DEFAULT);
}

// Fix __proto__ and constructor flags on a built-in prototype object.
// Makes both DONT_ENUM + DONT_DELETE (= WRITABLE only).
// Called after prototype initialization to ensure these properties survive deletion.
static void fixBuiltinPrototypeFlags(ASObject* proto)
{
	if (proto == NULL) return;
	for (u32 i = 0; i < proto->num_used; i++)
	{
		if ((proto->properties[i].name_length == 9 &&
		     strncmp(proto->properties[i].name, "__proto__", 9) == 0) ||
		    (proto->properties[i].name_length == 11 &&
		     strncmp(proto->properties[i].name, "constructor", 11) == 0))
		{
			proto->properties[i].flags = PROPERTY_FLAG_WRITABLE;
		}
	}
}

// Ensure a built-in prototype has constructor property and both constructor/__proto__ are DONT_DELETE.
// If constructor is missing, adds it with DONT_ENUM + DONT_DELETE flags.
// Ensures __proto__ comes AFTER constructor in insertion order (so __proto__ enumerates first in LIFO).
static void ensureBuiltinPrototypeProps(SWFAppContext* app_context, ASObject* proto, void* ctor_ptr)
{
	if (proto == NULL) return;
	// Check if constructor exists as a real value (not just an UNDEFINED placeholder)
	ActionVar* existing_ctor = getProperty(proto, "constructor", 11);
	int ctor_missing = (existing_ctor == NULL);
	int ctor_placeholder = (existing_ctor != NULL && existing_ctor->type == ACTION_STACK_VALUE_UNDEFINED);

	if (ctor_ptr != NULL && (ctor_missing || ctor_placeholder))
	{
		ActionVar ctor_val = {0};
		ctor_val.type = ACTION_STACK_VALUE_FUNCTION;
		ctor_val.data.numeric_value = (u64) ctor_ptr;

		if (ctor_placeholder) {
			// Placeholder exists at correct position — just fill in the value
			setPropertyWithFlags(app_context, proto, "constructor", 11, &ctor_val, PROPERTY_FLAG_WRITABLE);
		} else {
			// Constructor missing — insert before __proto__ for correct LIFO order
			int proto_idx = -1;
			ActionVar saved_proto = {0};
			u8 saved_flags = 0;
			for (u32 i = 0; i < proto->num_used; i++) {
				if (proto->properties[i].name_length == 9 &&
				    strncmp(proto->properties[i].name, "__proto__", 9) == 0) {
					proto_idx = (int)i;
					saved_proto = proto->properties[i].value;
					saved_flags = proto->properties[i].flags;
					for (u32 j = i; j + 1 < proto->num_used; j++)
						proto->properties[j] = proto->properties[j + 1];
					proto->num_used--;
					break;
				}
			}
			setPropertyWithFlags(app_context, proto, "constructor", 11, &ctor_val, PROPERTY_FLAG_WRITABLE);
			if (proto_idx >= 0)
				setPropertyWithFlags(app_context, proto, "__proto__", 9, &saved_proto, saved_flags);
		}
	}
	fixBuiltinPrototypeFlags(proto);
}

// Set up arguments object properties: __proto__ = Array.prototype, callee, caller.
// Called after creating the arguments ASArray for any user-defined function call.
static void setupArgumentsProps(SWFAppContext* app_context, ASArray* arr,
                                 ASFunction* callee_func, ASFunction* caller_func)
{
	// Lazily create Array.prototype (shared singleton)
	if (g_array_prototype == NULL)
	{
		g_array_prototype = allocObject(app_context, 16);
		retainObject(g_array_prototype);
		setObjectProto(app_context, g_array_prototype);
	}
	initArrayPrototypeMethods(app_context);

	// Allocate props object on the array for non-index properties
	if (arr->props == NULL)
	{
		arr->props = allocObject(app_context, 4);
		retainObject(arr->props);
	}

	// __proto__ = Array.prototype (non-enumerable)
	{
		ActionVar pv = {0};
		pv.type = ACTION_STACK_VALUE_OBJECT;
		pv.data.numeric_value = (u64)g_array_prototype;
		setPropertyWithFlags(app_context, arr->props, "__proto__", 9, &pv, PROPERTY_FLAGS_DONTENUM);
	}

	// callee = the function being called (non-enumerable)
	{
		ActionVar cv = {0};
		cv.type = ACTION_STACK_VALUE_FUNCTION;
		cv.data.numeric_value = (u64)callee_func;
		setPropertyWithFlags(app_context, arr->props, "callee", 6, &cv, PROPERTY_FLAGS_DONTENUM);
	}

	// caller = the function that initiated this call, or null (non-enumerable)
	{
		ActionVar cr = {0};
		if (caller_func != NULL)
		{
			cr.type = ACTION_STACK_VALUE_FUNCTION;
			cr.data.numeric_value = (u64)caller_func;
		}
		else
		{
			cr.type = ACTION_STACK_VALUE_NULL;
		}
		setPropertyWithFlags(app_context, arr->props, "caller", 6, &cr, PROPERTY_FLAGS_DONTENUM);
	}
}

// Public wrapper for setupArgumentsProps — called from recompiler-generated code
// when DefineFunction2 has the preload_arguments flag. Uses the global function
// context (g_current_executing_func = callee, g_prev_executing_func = caller).
void swf_setup_arguments_props(SWFAppContext* app_context, ASArray* arr)
{
	setupArgumentsProps(app_context, arr, g_current_executing_func, g_prev_executing_func);
}

// Helper to look up function by name
static ASFunction* lookupFunctionByName(const char* name, u32 name_len) {
	// Search in reverse order (most recently defined first) so that function
	// redefinitions at the same scope level shadow earlier definitions.
	// In ActionScript, defining "f" twice means the second definition wins.
	for (int i = (int)function_count - 1; i >= 0; i--) {
		if (strlen(function_registry[i]->name) == name_len &&
		    strncmp(function_registry[i]->name, name, name_len) == 0) {
			return function_registry[i];
		}
	}
	return NULL;
}

// Helper to look up function from ActionVar
static ASFunction* lookupFunctionFromVar(ActionVar* var) {
	if (var->type != ACTION_STACK_VALUE_FUNCTION) {
		return NULL;
	}
	return (ASFunction*) var->data.numeric_value;
}

// Invoke a getter/setter function as a "special" invocation.
// Uses g_special_depth (not g_call_depth). Returns the function's return value.
// If special depth limit is reached, returns undefined without invoking.
static ActionVar invokeSpecialFunction(SWFAppContext* app_context, ASFunction* func, ActionVar* arg)
{
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;

	if (func == NULL || g_execution_halted) return undef;

	// Check special recursion limit (non-fatal)
	// Increment before check — Ruffle increments first, then checks >= 66
	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH)
	{
		g_special_depth--;
		return undef;
	}

	ActionVar result;
	if (func->function_type == 2)
	{
		// DefineFunction2
		ActionVar* registers = NULL;
		if (func->register_count > 0)
		{
			registers = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		if (arg != NULL)
		{
			// Setter: pass one argument
			result = func->advanced_func(app_context, arg, 1, registers, NULL);
		}
		else
		{
			// Getter: no arguments
			result = func->advanced_func(app_context, NULL, 0, registers, NULL);
		}

		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (registers != NULL) FREE(registers);
	}
	else
	{
		// Simple DefineFunction (type 1)
		// If setter, push the value arg onto the stack for the function to pop
		if (arg != NULL)
		{
			pushVar(app_context, arg);
		}
		result = ((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
	}

	g_special_depth--;
	return result;
}

// Invoke an addProperty getter with a specific this_obj
static ActionVar invokePropertyGetter(SWFAppContext* app_context, ASFunction* func, void* this_obj)
{
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (func == NULL || g_execution_halted) return undef;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH)
	{
		g_special_depth--;
		return undef;
	}

	ActionVar result;
	if (func->function_type == 2)
	{
		ActionVar* registers = NULL;
		if (func->register_count > 0)
			registers = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		// Restore captured scopes (closure context)
		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH)
			{
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		// Switch base_clip context for SWF6+
		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		result = func->advanced_func(app_context, NULL, 0, registers, this_obj);

		g_current_context = saved_context;
		// Pop local scope + captured scopes
		for (u32 ci = 0; ci < captured_count + 1; ci++)
		{
			if (scope_depth > 0) scope_depth--;
		}
		releaseObject(app_context, local_scope);
		if (registers != NULL) FREE(registers);
	}
	else
	{
		// Restore captured scopes for type-1 functions too
		u32 captured_count = func->captured_scope_count;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth < MAX_SCOPE_DEPTH)
			{
				scope_is_with[scope_depth] = func->captured_scope_is_with[ci];
				scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[ci];
				scope_chain[scope_depth++] = (ASObject*)func->captured_scope[ci];
			}
		}

		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		result = ((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);

		g_current_context = saved_context;
		for (u32 ci = 0; ci < captured_count; ci++)
		{
			if (scope_depth > 0) scope_depth--;
		}
	}

	g_special_depth--;
	return result;
}

// Find __resolve method by walking prototype chain (raw lookup, no addProperty getters).
// Auto-box a primitive value to a wrapper object using the current global constructor.
// When a monkey-patched constructor (user function) is found on _global for
// Boolean/Number/String, creates a wrapper ASObject, sets __proto__ and __constructor__,
// calls the constructor, and mutates obj_var from primitive to OBJECT type.
// Returns 1 if boxing occurred, 0 if not (constructor not found or is built-in stub).
// Returns: 1 = auto-boxed, 0 = no constructor found (use _global for Function.call/apply),
//          -1 = built-in stub constructor found (use primitive passthrough for Function.call/apply)
static int tryAutoBoxPrimitive(SWFAppContext* app_context, ActionVar* obj_var, ASObject* active_global)
{
	if (obj_var->type != ACTION_STACK_VALUE_BOOLEAN &&
	    obj_var->type != ACTION_STACK_VALUE_F32 &&
	    obj_var->type != ACTION_STACK_VALUE_F64 &&
	    obj_var->type != ACTION_STACK_VALUE_STRING)
		return 0;

	const char* ctor_name = NULL;
	u32 ctor_name_len = 0;
	if (obj_var->type == ACTION_STACK_VALUE_BOOLEAN) { ctor_name = "Boolean"; ctor_name_len = 7; }
	else if (obj_var->type == ACTION_STACK_VALUE_F32 || obj_var->type == ACTION_STACK_VALUE_F64) { ctor_name = "Number"; ctor_name_len = 6; }
	else { ctor_name = "String"; ctor_name_len = 6; }

	ASFunction* box_ctor = NULL;
	int found_builtin_stub = 0;
	if (active_global != NULL) {
		ASProperty* gp = findPropertyStructWithPrototype(active_global, ctor_name, ctor_name_len);
		if (gp != NULL) {
			ActionVar ctor_val;
			if (gp->getter != NULL) {
				ctor_val = invokePropertyGetter(app_context, (ASFunction*)gp->getter, (void*)active_global);
			} else {
				ctor_val = gp->value;
			}
			if (ctor_val.type == ACTION_STACK_VALUE_FUNCTION) {
				ASFunction* cf = (ASFunction*) ctor_val.data.numeric_value;
				// Only auto-box if constructor is a user-defined function (callable code)
				// Built-in stubs have advanced_func=NULL and simple_func=NULL
				if (cf != NULL && (cf->advanced_func != NULL || cf->simple_func != NULL))
					box_ctor = cf;
				else if (cf != NULL && strncmp(cf->name, ctor_name, ctor_name_len) == 0 && cf->name[ctor_name_len] == '\0')
					found_builtin_stub = 1; // Original built-in constructor for this type
			}
		}
	}

	if (box_ctor == NULL) return found_builtin_stub ? -1 : 0;

	// Create wrapper object: new Constructor(primitive_value)
	ASObject* wrapper = allocObject(app_context, 4);
	retainObject(wrapper);
	if (box_ctor->prototype_obj != NULL) {
		ActionVar proto_val = {0};
		proto_val.type = ACTION_STACK_VALUE_OBJECT;
		proto_val.data.numeric_value = (u64) box_ctor->prototype_obj;
		setProperty(app_context, wrapper, "__proto__", 9, &proto_val);
	} else if (box_ctor->own_props != NULL) {
		// Check for non-object prototype stored in own_props (e.g., func.prototype = true)
		ActionVar* stored_proto = getProperty(box_ctor->own_props, "prototype", 9);
		if (stored_proto != NULL && stored_proto->type != ACTION_STACK_VALUE_UNDEFINED)
			setProperty(app_context, wrapper, "__proto__", 9, stored_proto);
	}
	ActionVar ctor_ref = {0};
	ctor_ref.type = ACTION_STACK_VALUE_FUNCTION;
	ctor_ref.data.numeric_value = (u64) box_ctor;
	setProperty(app_context, wrapper, "__constructor__", 15, &ctor_ref);

	// Call the constructor with wrapper as 'this' and primitive value as argument
	ActionVar box_args[1];
	box_args[0] = *obj_var;
	if (box_ctor->function_type == 2 && box_ctor->advanced_func != NULL) {
		pushSuperContext((void*)wrapper, 1);
		// Set up local scope with `this` bound to the wrapper so the user
		// constructor body's `this.prop = value` resolves correctly. Needed
		// for SWF7+ DefineFunction2 constructors — without this, GetVariable
		// ("this") inside the function body falls back to parent context
		// (often undefined), and `this.id = "wonder1"` writes to the wrong
		// object. Mirrors the OBJECT/type-2 dispatch in actionCallMethod.
		ASObject* _box_local_scope = allocObject(app_context, 4);
		retainObject(_box_local_scope);
		int _box_pushed_scope = 0;
		if (scope_depth < MAX_SCOPE_DEPTH) {
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = _box_local_scope;
			_box_pushed_scope = 1;
		}
		u32 _box_saved_this_depth = g_this_depth;
		u16 _box_flags = box_ctor->flags;
		if (!(_box_flags & 0x0001) && !(_box_flags & 0x0002)) {
			ActionVar _box_tv = {0};
			_box_tv.type = ACTION_STACK_VALUE_OBJECT;
			_box_tv.data.numeric_value = (u64) wrapper;
			setProperty(app_context, _box_local_scope, "this", 4, &_box_tv);
			if (g_this_depth < MAX_THIS_DEPTH) {
				g_this_stack[g_this_depth] = _box_tv;
				g_this_depth++;
			}
		}
		ActionVar registers[256] = {0};
		g_call_depth++;
		box_ctor->advanced_func(app_context, box_args, 1, registers, (void*)wrapper);
		g_call_depth--;
		g_this_depth = _box_saved_this_depth;
		if (_box_pushed_scope && scope_depth > 0) scope_depth--;
		releaseObject(app_context, _box_local_scope);
		popSuperContext();
	} else if (box_ctor->function_type == 1 && box_ctor->simple_func != NULL) {
		ActionVar this_var = {0};
		this_var.type = ACTION_STACK_VALUE_OBJECT;
		this_var.data.numeric_value = (u64) wrapper;
		setVariableByName("this", &this_var);
		pushVar(app_context, &box_args[0]);
		g_call_depth++;
		((ActionVar(*)(SWFAppContext*))box_ctor->simple_func)(app_context);
		g_call_depth--;
	}

	// Replace obj_var with the wrapper object
	obj_var->type = ACTION_STACK_VALUE_OBJECT;
	obj_var->data.numeric_value = (u64) wrapper;
	return 1;
}

// Returns ASFunction* if a callable __resolve is found, NULL otherwise.
// Semantics: FUNCTION type → return it; OBJECT type → block (return NULL, sets *blocked=1);
// all other types (number, string, movieclip, etc.) → skip, continue up chain.
static ASFunction* findResolveMethod(SWFAppContext* app_context, ASObject* obj)
{
	ASObject* current = obj;
	int max_depth = 256;

	for (int depth = 0; depth < max_depth && current != NULL; depth++)
	{
		ASProperty* resolve_prop = findPropertyRaw(current, "__resolve", 9);
		if (resolve_prop != NULL && resolve_prop->getter == NULL)  // Skip addProperty-based __resolve
		{
			ActionVar* rv = &resolve_prop->value;
			if (rv->type == ACTION_STACK_VALUE_FUNCTION)
			{
				return (ASFunction*)(uintptr_t)rv->data.numeric_value;
			}
			else if (rv->type == ACTION_STACK_VALUE_OBJECT)
			{
				// Non-function object blocks — stop searching
				return NULL;
			}
			// Primitives (number, string, bool, movieclip, etc.) — skip, continue up chain
		}

		// Walk to __proto__
		ActionVar* proto_var = getProperty(current, "__proto__", 9);
		if (proto_var == NULL || proto_var->type != ACTION_STACK_VALUE_OBJECT || proto_var->data.numeric_value == 0)
			break;
		ASObject* next = (ASObject*)(uintptr_t)proto_var->data.numeric_value;
		if (next == obj) break;  // Cycle detection
		current = next;
	}

	return NULL;
}

// Invoke a __resolve function with one string argument (the property name).
// Returns the resolve function's return value, or undefined if invocation fails.
static ActionVar invokeResolveFunction(SWFAppContext* app_context, ASFunction* func, void* this_obj,
                                        const char* prop_name, u32 prop_name_len)
{
	ActionVar undef = {0};
	undef.type = ACTION_STACK_VALUE_UNDEFINED;
	if (func == NULL || g_execution_halted) return undef;

	g_call_depth++;
	if (g_call_depth > g_max_call_depth)
	{
		g_execution_halted = 1;
		g_call_depth--;
		return undef;
	}

	ActionVar result;
	if (func->function_type == 2 && func->advanced_func != NULL)
	{
		// Type 2 (DefineFunction2): pass args array directly
		ActionVar name_arg = {0};
		u32 u16_len = 0;
		uint16_t* u16_str = utf8_to_u16(app_context, prop_name, prop_name_len, &u16_len);
		name_arg.type = ACTION_STACK_VALUE_STRING;
		name_arg.str_size = u16_len;
		name_arg.data.numeric_value = (u64)(uintptr_t)u16_str;

		ActionVar* registers = NULL;
		if (func->register_count > 0)
			registers = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		// Push local scope
		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		// Restore captured WITH scopes if any
		u32 captured_count = func->captured_scope_count;
		for (u32 i = 0; i < captured_count && scope_depth < MAX_SCOPE_DEPTH; i++)
		{
			scope_is_with[scope_depth] = 1;
			scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[i];
			scope_chain[scope_depth++] = (ASObject*)func->captured_scope[i];
		}

		// Switch base_clip context if SWF6+
		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		result = func->advanced_func(app_context, &name_arg, 1, registers, this_obj);

		g_current_context = saved_context;
		// Pop captured scopes + local scope
		for (u32 i = 0; i < captured_count && scope_depth > 0; i++)
			scope_depth--;
		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (registers != NULL) FREE(registers);
	}
	else if (func->function_type == 1 && func->simple_func != NULL)
	{
		// Type 1 (DefineFunction): push args onto stack, set "this"
		PUSH_STR(prop_name, prop_name_len);  // Push property name as string arg

		// Push local scope
		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		// Restore captured WITH scopes
		u32 captured_count = func->captured_scope_count;
		for (u32 i = 0; i < captured_count && scope_depth < MAX_SCOPE_DEPTH; i++)
		{
			scope_is_with[scope_depth] = 1;
			scope_mc[scope_depth] = (MovieClip*)func->captured_scope_mc[i];
			scope_chain[scope_depth++] = (ASObject*)func->captured_scope[i];
		}

		// Switch base_clip context if SWF6+
		MovieClip* saved_context = g_current_context;
		if (g_swf_version >= 6 && func->base_clip != NULL)
			g_current_context = (MovieClip*)func->base_clip;

		// Set "this"
		ActionVar this_var = {0};
		this_var.type = ACTION_STACK_VALUE_OBJECT;
		this_var.data.numeric_value = (u64)(uintptr_t)this_obj;
		setVariableByName("this", &this_var);

		result = ((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);

		g_current_context = saved_context;
		for (u32 i = 0; i < captured_count && scope_depth > 0; i++)
			scope_depth--;
		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
	}
	else
	{
		result = undef;
	}

	g_call_depth--;
	return result;
}

// Invoke an addProperty setter with a specific this_obj and value argument
static void invokePropertySetter(SWFAppContext* app_context, ASFunction* func, void* this_obj, ActionVar* value)
{
	if (func == NULL || g_execution_halted) return;

	g_special_depth++;
	if (g_special_depth >= MAX_SPECIAL_DEPTH)
	{
		g_special_depth--;
		return;
	}

	if (func->function_type == 2)
	{
		ActionVar* registers = NULL;
		if (func->register_count > 0)
			registers = (ActionVar*) HCALLOC(func->register_count, sizeof(ActionVar));

		ASObject* local_scope = allocObject(app_context, 8);
		if (scope_depth < MAX_SCOPE_DEPTH)
		{
			scope_is_with[scope_depth] = 0;
			scope_mc[scope_depth] = NULL;
			scope_chain[scope_depth++] = local_scope;
		}

		func->advanced_func(app_context, value, 1, registers, this_obj);

		if (scope_depth > 0) scope_depth--;
		releaseObject(app_context, local_scope);
		if (registers != NULL) FREE(registers);
	}
	else if (func->function_type == 1 && func->simple_func != NULL)
	{
		// Type 1 (DefineFunction): push value onto stack, call function
		if (value != NULL) pushVar(app_context, value);
		((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
	}

	g_special_depth--;
}

