// (avmplus-compatible RNG and Math.random moved to math.c; access via
//  actionRNGGenerateRange in actionmodern/actionmath.h.)

// ==================================================================
// MovieClip Property Support (for SET_PROPERTY / GET_PROPERTY)
// ==================================================================

// MovieClip structure is defined in action.h

// Global object for ActionScript _global
// This is initialized on first use and persists for the lifetime of the runtime
ASObject* global_object = NULL;

// Per-version-group globals: SWF 1-6 share one, SWF 7+ share another
static ASObject* g_global_legacy = NULL;  // SWF 1-6
static ASObject* g_global_modern = NULL;  // SWF 7+
static int g_primary_version_group = -1;  // 0=legacy, 1=modern (first initialized)

// Per-version-group Object.prototype and Array.prototype for user-created objects
static ASObject* g_object_proto_legacy = NULL;
static ASObject* g_object_proto_modern = NULL;
static ASObject* g_array_proto_legacy = NULL;
static ASObject* g_array_proto_modern = NULL;
// Per-version-group Function.prototype for function __proto__ identity
static ASObject* g_function_proto_legacy = NULL;  // SWF 1-6
static ASObject* g_function_proto_modern = NULL;  // SWF 7+
static ASFunction* g_function_constructor = NULL; // Pointer to Function constructor (g_ctors[5])
// Per-version-group MovieClip constructor and prototype
static ASFunction* g_mc_ctor_legacy = NULL;  // SWF 1-6
static ASFunction* g_mc_ctor_modern = NULL;  // SWF 7+
static int g_secondary_global_init = 0;

static inline int versionGroup(int version) { return (version <= 6) ? 0 : 1; }

// Get the version-appropriate Function.prototype (for function __proto__ identity)
static inline ASObject* getFunctionProto(int version) {
	return (version <= 6) ? g_function_proto_legacy : g_function_proto_modern;
}

// Forward declaration (defined at ~line 8134)
extern ASFunction g_movieclip_constructor;

// Get the version-appropriate MovieClip constructor
static inline ASFunction* getMovieClipCtor(int version) {
	ASFunction* ctor = (version <= 6) ? g_mc_ctor_legacy : g_mc_ctor_modern;
	return ctor ? ctor : &g_movieclip_constructor;
}

// Get the version-appropriate MovieClip.prototype
static inline ASObject* getMovieClipPrototype(int version) {
	ASFunction* ctor = getMovieClipCtor(version);
	return ctor->prototype_obj;
}

// Get the version-appropriate _global object
static inline ASObject* getActiveGlobal(void) {
	ASObject* ag = global_object;
	if (g_swf_version <= 6 && g_global_legacy != NULL) ag = g_global_legacy;
	else if (g_swf_version > 6 && g_global_modern != NULL) ag = g_global_modern;
	return ag;
}

// Forward declaration
static void ensureSecondaryGlobalInit(SWFAppContext* app_context, int target_version);

// Phase 3: Per-function version context switching helpers.
// Built-in functions have swf_version=0 (zero-initialized statics) → no switch.
// User-defined functions have swf_version set at definition time → switch to their version.
static inline void switchToFunctionVersion(ASFunction* func, int* saved_ver, ASObject** saved_global, int* saved_movie_idx)
{
	*saved_ver = g_swf_version;
	*saved_global = global_object;
	*saved_movie_idx = 0; // reserved for future use
	if (func->swf_version != 0) {
		g_swf_version = func->swf_version;
		int vg = versionGroup(g_swf_version);
		if (vg == 0 && g_global_legacy) global_object = g_global_legacy;
		else if (vg == 1 && g_global_modern) global_object = g_global_modern;
	}
}
static inline void restoreFunctionVersion(int saved_ver, ASObject* saved_global, int saved_movie_idx)
{
	g_swf_version = saved_ver;
	global_object = saved_global;
	(void)saved_movie_idx; // reserved for future use
}

// MovieClip constructor function (for MovieClip.prototype access)
ASFunction g_movieclip_constructor;
int g_movieclip_constructor_init = 0;

// MovieClip prototype method stubs (static storage)
#define MC_METHOD_COUNT 29
static ASFunction g_mc_method_funcs[MC_METHOD_COUNT];

static void initMovieClipPrototype(SWFAppContext* app_context)
{
	if (g_movieclip_constructor_init) return;

	memset(&g_movieclip_constructor, 0, sizeof(ASFunction));
	strncpy(g_movieclip_constructor.name, "MovieClip", 255);
	g_movieclip_constructor.function_type = 1;
	g_movieclip_constructor.param_count = 0;

	// Create prototype
	ASObject* proto = allocObject(app_context, 32);
	retainObject(proto);
	g_movieclip_constructor.prototype_obj = proto;

	// Set __proto__ to Object.prototype
	setObjectProto(app_context, proto);

	// Method stub names (DontEnum functions on MovieClip.prototype)
	static const struct { const char* name; u32 len; } mc_methods[MC_METHOD_COUNT] = {
		{"attachMovie", 11},
		{"createEmptyMovieClip", 20},
		{"createTextField", 15},
		{"duplicateMovieClip", 18},
		{"getBounds", 9},
		{"getBytesLoaded", 14},
		{"getBytesTotal", 13},
		{"getDepth", 8},
		{"getInstanceAtDepth", 18},
		{"getNextHighestDepth", 19},
		{"getSWFVersion", 13},
		{"getURL", 6},
		{"globalToLocal", 13},
		{"localToGlobal", 13},
		{"removeMovieClip", 15},
		{"setMask", 7},
		{"startDrag", 9},
		{"stopDrag", 8},
		{"swapDepths", 10},
		{"getTextSnapshot", 15},
		{"gotoAndStop", 11},
		{"gotoAndPlay", 11},
		{"stop", 4},
		{"play", 4},
		{"prevFrame", 9},
		{"nextFrame", 9},
		{"loadMovie", 9},
		{"loadVariables", 13},
		{"unloadMovie", 11},
	};

	memset(g_mc_method_funcs, 0, sizeof(g_mc_method_funcs));
	// Names of MovieClip.prototype methods introduced in SWF6+. Match Ruffle's
	// `core/src/avm1/globals/movie_clip.rs` VERSION_6 tags. These get
	// flash_flags=0x0080 so SWF5 resolution hides them (gnash test:
	// `typeof(createEmptyMovieClip) == "undefined"` in SWF5).
	static const char* mc_swf6_methods[] = {
		"createEmptyMovieClip", "getDepth", "setMask", NULL
	};
	for (int i = 0; i < MC_METHOD_COUNT; i++)
	{
		strncpy(g_mc_method_funcs[i].name, mc_methods[i].name, 255);
		g_mc_method_funcs[i].function_type = 1;
		g_mc_method_funcs[i].param_count = 0;

		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_mc_method_funcs[i];

		ActionVar func_val = {0};
		func_val.type = ACTION_STACK_VALUE_FUNCTION;
		func_val.data.numeric_value = (u64) &g_mc_method_funcs[i];
		setProperty(app_context, proto, mc_methods[i].name, mc_methods[i].len, &func_val);

		// Mark SWF6+ methods as hidden under SWF5 via flash_flags=0x0080.
		for (int vi = 0; mc_swf6_methods[vi] != NULL; vi++) {
			if (strcmp(mc_methods[i].name, mc_swf6_methods[vi]) == 0) {
				if (proto->num_used > 0)
					proto->properties[proto->num_used - 1].flash_flags = 0x0080;
				break;
			}
		}
	}

	// Set MovieClip.prototype.enabled = true (used by button state machine)
	{
		ActionVar en_val = {0};
		en_val.type = ACTION_STACK_VALUE_BOOLEAN;
		en_val.data.numeric_value = 1;
		setProperty(app_context, proto, "enabled", 7, &en_val);
	}
	// Set MovieClip.prototype.transform = undefined (own property for hasOwnProperty checks)
	{
		ActionVar undef_val = {0};
		undef_val.type = ACTION_STACK_VALUE_UNDEFINED;
		setProperty(app_context, proto, "transform", 9, &undef_val);
	}
	// Additional drawing-API method stubs and undefined property slots that
	// Gnash MovieClip-v5..v8 tests expect on MovieClip.prototype via
	// hasOwnProperty. These are drawing API methods (SWF6+) and display
	// object properties (SWF8+). Flash Player installs them on the
	// prototype regardless of SWF version; hasPropertyRaw (used by
	// hasOwnProperty) ignores flash_flags visibility so they show up in
	// SWF5 for-in tests.
	{
		// Drawing API methods — install as stub functions
		static ASFunction mc_extra_fns[15];
		static const char* extra_names[15] = {
			"attachAudio", "beginFill", "beginGradientFill", "beginBitmapFill",
			"moveTo", "lineTo", "curveTo", "lineStyle", "lineGradientStyle",
			"endFill", "clear", "attachBitmap", "getRect",
			"getInstanceAtDepth", "swapDepths",
		};
		(void)extra_names; // silence if no-op
		// attachAudio, beginFill, beginGradientFill, beginBitmapFill, moveTo,
		// lineTo, curveTo, lineStyle, lineGradientStyle, endFill, clear,
		// attachBitmap, getRect — the 13 drawing-API / new method stubs.
		static const char* draw_names[13] = {
			"attachAudio", "beginFill", "beginGradientFill", "beginBitmapFill",
			"moveTo", "lineTo", "curveTo", "lineStyle", "lineGradientStyle",
			"endFill", "clear", "attachBitmap", "getRect",
		};
		for (int i = 0; i < 13; i++) {
			memset(&mc_extra_fns[i], 0, sizeof(ASFunction));
			strncpy(mc_extra_fns[i].name, draw_names[i], 255);
			mc_extra_fns[i].function_type = 2;
			mc_extra_fns[i].advanced_func = (Function2Ptr)builtin_noop_func;
			if (function_count < MAX_FUNCTIONS)
				function_registry[function_count++] = &mc_extra_fns[i];
			// Skip if already present (getRect shouldn't be, but defensive).
			if (!hasPropertyRaw(proto, draw_names[i], (u32)strlen(draw_names[i]))) {
				ActionVar fv = {0};
				fv.type = ACTION_STACK_VALUE_FUNCTION;
				fv.data.numeric_value = (u64)&mc_extra_fns[i];
				setPropertyWithFlags(app_context, proto, draw_names[i],
					(u32)strlen(draw_names[i]), &fv, PROPERTY_FLAG_WRITABLE);
			}
		}

		// Undefined property slots (display object extras exposed on the
		// prototype as enumerable-but-undefined own properties).
		ActionVar undef_val = {0};
		undef_val.type = ACTION_STACK_VALUE_UNDEFINED;
		static const char* extra_props[9] = {
			"blendMode", "cacheAsBitmap", "filters", "opaqueBackground",
			"scale9Grid", "scrollRect", "tabIndex", "useHandCursor",
			"_lockroot",
		};
		for (int i = 0; i < 9; i++) {
			if (!hasPropertyRaw(proto, extra_props[i], (u32)strlen(extra_props[i]))) {
				setProperty(app_context, proto, extra_props[i],
					(u32)strlen(extra_props[i]), &undef_val);
			}
		}
	}

	// Mark all methods and __proto__ as DontEnum (but NOT enabled — it's enumerable)
	for (u32 i = 0; i < proto->num_used; i++)
	{
		if (strcmp(proto->properties[i].name, "enabled") == 0) continue;
		proto->properties[i].flags &= ~PROPERTY_FLAG_ENUMERABLE;
	}

	g_movieclip_constructor_init = 1;

	// Register as the primary version group's MC constructor
	if (g_primary_version_group == 0)
		g_mc_ctor_legacy = &g_movieclip_constructor;
	else if (g_primary_version_group == 1)
		g_mc_ctor_modern = &g_movieclip_constructor;
}

// TextField constructor function and prototype
static ASFunction g_textfield_constructor;
static int g_textfield_constructor_init = 0;
static ASFunction g_tf_type_toString_func; // [type Object] toString for SWF < 7
// TextField prototype method stubs (static storage)
static ASFunction g_tf_getTextFormat_func;
static ASFunction g_tf_setTextFormat_func;
static ASFunction g_tf_getNewTextFormat_func;
static ASFunction g_tf_setNewTextFormat_func;
static ASFunction g_tf_getDepth_func;
static ASFunction g_tf_removeTextField_func;
static ASFunction g_tf_replaceSel_func;
static ASFunction g_tf_replaceText_func;

// Helper: check if an ASObject is a bare TextField instance (created via new TextField())
static int isTextFieldInstance(ASObject* obj) {
	if (!g_textfield_constructor_init || g_textfield_constructor.prototype_obj == NULL) return 0;
	// Safety: skip corrupt objects (NULL properties or unreasonable size)
	if (obj->properties == NULL || obj->num_used > 4096) return 0;
	ActionVar* proto_var = getProperty(obj, "__proto__", 9);
	if (proto_var == NULL || proto_var->type != ACTION_STACK_VALUE_OBJECT) return 0;
	return (ASObject*)proto_var->data.numeric_value == g_textfield_constructor.prototype_obj;
}

// Helper: check if a property name is a native TextField property
// These properties are "virtual" on TextField — setting them on a bare new TextField() has no effect
// SWF7-: 30 native props (filters/sharpness/thickness/antiAliasType/gridFitType are settable)
// SWF8+: all 35 data properties are native
static int isNativeTextFieldProperty(const char* name, u32 len) {
	static const struct { const char* n; u32 l; } props[] = {
		{"styleSheet",10}, {"mouseWheelEnabled",17}, {"condenseWhite",13}, {"restrict",8},
		{"textHeight",10}, {"textWidth",9}, {"bottomScroll",12}, {"length",6},
		{"selectable",10}, {"multiline",9}, {"password",8}, {"wordWrap",8},
		{"background",10}, {"border",6}, {"html",4}, {"embedFonts",10},
		{"maxChars",8}, {"maxhscroll",10}, {"hscroll",7}, {"variable",8},
		{"htmlText",8}, {"type",4}, {"text",4}, {"autoSize",8},
		{"tabIndex",8}, {"textColor",9}, {"backgroundColor",15}, {"borderColor",11},
		{"maxscroll",9}, {"scroll",6},
		// SWF8+ only: these 5 also become native
		{"filters",7}, {"sharpness",9}, {"thickness",9}, {"antiAliasType",13}, {"gridFitType",11}
	};
	int count = (g_swf_version >= 8) ? 35 : 30;
	for (int i = 0; i < count; i++) {
		if (props[i].l == len && strncmp(name, props[i].n, len) == 0) return 1;
	}
	return 0;
}

static void initStyleSheetPrototype(SWFAppContext* app_context); // forward decl
static ASFunction g_stylesheet_constructor_global; // forward decl

static void initTextFieldPrototype(SWFAppContext* app_context)
{
	// Two-stage init: SWF5 run (e.g. via Dejagnu.swf child-SWF init) allocates the
	// prototype so `new TextField() instanceof TextField` works, but skips SWF6+
	// virtual-properties/methods/__proto__ wiring. When re-entered under SWF6+
	// (usually after Dejagnu's SWF5 init), we upgrade and install the full set.
	if (g_textfield_constructor_init && (g_textfield_constructor_init >= 2 || g_swf_version < 6))
		return;

	if (!g_textfield_constructor_init) {
		memset(&g_textfield_constructor, 0, sizeof(ASFunction));
		strncpy(g_textfield_constructor.name, "TextField", 255);
		g_textfield_constructor.function_type = 1;
		g_textfield_constructor.param_count = 0;

		// Create prototype with capacity for 35 properties + 8 methods + __proto__ + __constructor__
		ASObject* proto = allocObject(app_context, 48);
		retainObject(proto);
		g_textfield_constructor.prototype_obj = proto;
	}

	// In SWF5 Flash exposes TextField.prototype as an Object whose __proto__
	// chain reaches Object.prototype (so `TextField.prototype.toString ==
	// Object.prototype.toString` via inherited lookup). Wire __proto__ even
	// under SWF5; skip only the SWF6+ virtual properties / methods below.
	if (g_swf_version < 6) {
		ASObject* _tf_proto = g_textfield_constructor.prototype_obj;
		if (_tf_proto != NULL) {
			ActionVar* _tf_pp = getProperty(_tf_proto, "__proto__", 9);
			if (_tf_pp == NULL || _tf_pp->type == ACTION_STACK_VALUE_UNDEFINED) {
				setObjectProto(app_context, _tf_proto);
			}
		}
		g_textfield_constructor_init = 1; // stage 1 only — allow later SWF6+ upgrade
		return;
	}

	ASObject* proto = g_textfield_constructor.prototype_obj;

	// Set __proto__ to Object.prototype
	setObjectProto(app_context, proto);

	// Add 35 enumerable properties in the exact order Flash enumerates them.
	// All start as undefined on the prototype; instances shadow them with real values.
	ActionVar undef_val = {0};
	undef_val.type = ACTION_STACK_VALUE_UNDEFINED;

	static const char* tf_prop_names[] = {
		"styleSheet", "mouseWheelEnabled", "condenseWhite", "restrict",
		"textHeight", "textWidth", "bottomScroll", "length",
		"selectable", "multiline", "password", "wordWrap",
		"background", "border", "html", "embedFonts",
		"maxChars", "maxhscroll", "hscroll", "variable",
		"htmlText", "type", "text", "autoSize",
		"tabIndex", "textColor", "backgroundColor", "borderColor",
		"maxscroll", "scroll", "filters", "sharpness",
		"thickness", "antiAliasType", "gridFitType"
	};
	static const u32 tf_prop_lens[] = {
		10, 17, 13, 8,
		10, 9, 12, 6,
		10, 9, 8, 8,
		10, 6, 4, 10,
		8, 10, 7, 8,
		8, 4, 4, 8,
		8, 9, 15, 11,
		9, 6, 7, 9,
		9, 13, 11
	};

	// Register in REVERSE order so that for-in enumeration (LIFO stack) yields forward order.
	// Flash enumerates TextField props as: styleSheet first, gridFitType last.
	for (int i = 34; i >= 0; i--)
	{
		setProperty(app_context, proto, tf_prop_names[i], tf_prop_lens[i], &undef_val);
	}

	// Add 8 method functions (DontEnum — they don't show up in for..in)
	struct {
		const char* name;
		u32 name_len;
		ASFunction* func;
	} tf_methods[] = {
		{"getTextFormat", 13, &g_tf_getTextFormat_func},
		{"setTextFormat", 13, &g_tf_setTextFormat_func},
		{"getNewTextFormat", 16, &g_tf_getNewTextFormat_func},
		{"setNewTextFormat", 16, &g_tf_setNewTextFormat_func},
		{"getDepth", 8, &g_tf_getDepth_func},
		{"removeTextField", 15, &g_tf_removeTextField_func},
		{"replaceSel", 10, &g_tf_replaceSel_func},
		{"replaceText", 11, &g_tf_replaceText_func},
	};

	// replaceText (last entry) only exists in SWF7+
	int tf_method_count = (g_swf_version < 7) ? 7 : 8;
	for (int i = 0; i < tf_method_count; i++)
	{
		memset(tf_methods[i].func, 0, sizeof(ASFunction));
		strncpy(tf_methods[i].func->name, tf_methods[i].name, 255);
		tf_methods[i].func->function_type = 1;
		tf_methods[i].func->param_count = 0;

		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = tf_methods[i].func;

		ActionVar func_val = {0};
		func_val.type = ACTION_STACK_VALUE_FUNCTION;
		func_val.data.numeric_value = (u64) tf_methods[i].func;
		setProperty(app_context, proto, tf_methods[i].name, tf_methods[i].name_len, &func_val);
	}

	// Mark method properties and __proto__ as DontEnum
	for (u32 i = 0; i < proto->num_used; i++)
	{
		const char* pname = proto->properties[i].name;
		if (strcmp(pname, "__proto__") == 0 ||
		    strcmp(pname, "getTextFormat") == 0 ||
		    strcmp(pname, "setTextFormat") == 0 ||
		    strcmp(pname, "getNewTextFormat") == 0 ||
		    strcmp(pname, "setNewTextFormat") == 0 ||
		    strcmp(pname, "getDepth") == 0 ||
		    strcmp(pname, "removeTextField") == 0 ||
		    strcmp(pname, "replaceSel") == 0 ||
		    strcmp(pname, "replaceText") == 0)
		{
			proto->properties[i].flags &= ~PROPERTY_FLAG_ENUMERABLE;
		}
	}

	// Register TextField.StyleSheet as a property on the constructor (SWF7+)
	if (g_swf_version >= 7)
	{
		initStyleSheetPrototype(app_context);
		if (g_textfield_constructor.own_props == NULL)
		{
			g_textfield_constructor.own_props = allocObject(app_context, 4);
			retainObject(g_textfield_constructor.own_props);
		}
		ActionVar ss_val = {0};
		ss_val.type = ACTION_STACK_VALUE_FUNCTION;
		VAL(u64, &ss_val.data.numeric_value) = (u64)&g_stylesheet_constructor_global;
		setProperty(app_context, g_textfield_constructor.own_props, "StyleSheet", 10, &ss_val);
	}

	g_textfield_constructor_init = 2; // full SWF6+ init complete
}

// ============================================================
// StyleSheet Implementation
// ============================================================
static ASFunction g_stylesheet_constructor_global;
static int g_stylesheet_constructor_init = 0;
static ASObject* g_stylesheet_prototype = NULL;
static ASFunction g_ss_methods[8]; // transform, setStyle, getStyle, getStyleNames, clear, parseCSS, load, parse

static void initTextFormatPrototype(SWFAppContext* app_context); // forward decl
static ASFunction g_textformat_constructor; // forward decl

// Helper: create a fresh TextFormat object with all null props + display="block", kerning=false
static ASObject* createBlankTextFormat(SWFAppContext* app_context) {
	initTextFormatPrototype(app_context);
	ASObject* tf = allocObject(app_context, 24);
	tf->native_type = NATIVE_TEXTFORMAT;
	if (g_textformat_constructor.prototype_obj != NULL) {
		ActionVar pv = {0};
		pv.type = ACTION_STACK_VALUE_OBJECT;
		pv.data.numeric_value = (u64)g_textformat_constructor.prototype_obj;
		setProperty(app_context, tf, "__proto__", 9, &pv);
		for (u32 i = 0; i < tf->num_used; i++) {
			if (strcmp(tf->properties[i].name, "__proto__") == 0) {
				tf->properties[i].flags &= ~PROPERTY_FLAG_ENUMERABLE;
				break;
			}
		}
	}
	// Initialize all properties to null
	ActionVar null_val = {0};
	null_val.type = ACTION_STACK_VALUE_NULL;
	static const char* ss_tf_props[] = {
		"font", "size", "color", "bold", "italic", "underline",
		"align", "leftMargin", "rightMargin", "indent", "leading",
		"blockIndent", "bullet", "kerning", "letterSpacing", "tabStops",
		"url", "target", "display"
	};
	static const u32 ss_tf_lens[] = {
		4, 4, 5, 4, 6, 9, 5, 10, 11, 6, 7, 11, 6, 7, 13, 8, 3, 6, 7
	};
	for (int i = 0; i < 19; i++) {
		setProperty(app_context, tf, ss_tf_props[i], ss_tf_lens[i], &null_val);
	}
	// display = "block"
	static const uint16_t blk[] = {'b','l','o','c','k',0};
	ActionVar dv = {0};
	dv.type = ACTION_STACK_VALUE_STRING;
	dv.data.numeric_value = (u64)blk;
	dv.str_size = 5;
	setProperty(app_context, tf, "display", 7, &dv);
	// kerning = false
	ActionVar kv = {0};
	kv.type = ACTION_STACK_VALUE_BOOLEAN;
	kv.data.numeric_value = 0;
	setProperty(app_context, tf, "kerning", 7, &kv);
	return tf;
}

// Helper: parse suffixed number from ActionVar as i32 (like Flash parseInt, stops at non-digit)
// NaN results → 0
static int32_t css_parse_i32(ActionVar* val) {
	if (val->type == ACTION_STACK_VALUE_F64) {
		double d = VAL(double, &val->data.numeric_value);
		if (isnan(d) || isinf(d)) return 0;
		return (int32_t)d;
	}
	if (val->type == ACTION_STACK_VALUE_F32) {
		float f = VAL(float, &val->data.numeric_value);
		if (isnanf(f) || isinff(f)) return 0;
		return (int32_t)f;
	}
	if (val->type != ACTION_STACK_VALUE_STRING) return 0;
	const uint16_t* u16 = varGetU16Ptr(val);
	u32 len = val->str_size;
	if (u16 == NULL || len == 0) return 0;
	u32 pos = 0;
	while (pos < len && (u16[pos] == ' ' || u16[pos] == '\t' || u16[pos] == '\n' || u16[pos] == '\r')) pos++;
	if (pos >= len) return 0;
	int neg = 0;
	if (u16[pos] == '-') { neg = 1; pos++; }
	else if (u16[pos] == '+') { pos++; }
	if (pos >= len || u16[pos] < '0' || u16[pos] > '9') return 0;
	int64_t result = 0;
	while (pos < len && u16[pos] >= '0' && u16[pos] <= '9') {
		result = result * 10 + (u16[pos] - '0');
		pos++;
	}
	if (neg) result = -result;
	return (int32_t)result;
}

// Helper: parse suffixed number from ActionVar as f64 (NaN stays NaN)
static double css_parse_f64(ActionVar* val) {
	if (val->type == ACTION_STACK_VALUE_F64) {
		double d = VAL(double, &val->data.numeric_value);
		if (isnan(d) || isinf(d)) return NAN;
		return (double)(int32_t)d;
	}
	if (val->type == ACTION_STACK_VALUE_F32) {
		float f = VAL(float, &val->data.numeric_value);
		if (isnanf(f) || isinff(f)) return (double)NAN;
		return (double)(int32_t)f;
	}
	if (val->type != ACTION_STACK_VALUE_STRING) return NAN;
	const uint16_t* u16 = varGetU16Ptr(val);
	u32 len = val->str_size;
	if (u16 == NULL || len == 0) return NAN;
	u32 pos = 0;
	while (pos < len && (u16[pos] == ' ' || u16[pos] == '\t' || u16[pos] == '\n' || u16[pos] == '\r')) pos++;
	if (pos >= len) return NAN;
	int neg = 0;
	if (u16[pos] == '-') { neg = 1; pos++; }
	else if (u16[pos] == '+') { pos++; }
	if (pos >= len || u16[pos] < '0' || u16[pos] > '9') return NAN;
	int64_t result = 0;
	while (pos < len && u16[pos] >= '0' && u16[pos] <= '9') {
		result = result * 10 + (u16[pos] - '0');
		pos++;
	}
	if (neg) result = -result;
	return (double)result;
}

// Helper: ActionScript truthiness check for CSS transform
static int css_is_truthy(ActionVar* val) {
	switch (val->type) {
		case ACTION_STACK_VALUE_NULL:
		case ACTION_STACK_VALUE_UNDEFINED:
			return 0;
		case ACTION_STACK_VALUE_BOOLEAN:
			return val->data.numeric_value != 0;
		case ACTION_STACK_VALUE_F64: {
			double d = VAL(double, &val->data.numeric_value);
			return !isnan(d) && d != 0.0;
		}
		case ACTION_STACK_VALUE_F32: {
			float f = VAL(float, &val->data.numeric_value);
			return !isnanf(f) && f != 0.0f;
		}
		case ACTION_STACK_VALUE_STRING:
			return val->str_size > 0;
		default:
			return 1;
	}
}

// Helper: check if UTF-16 string matches ASCII keyword (case-sensitive)
static int css_str_eq(ActionVar* val, const char* kw, u32 kw_len) {
	if (val->type != ACTION_STACK_VALUE_STRING || val->str_size != kw_len) return 0;
	const uint16_t* u16 = varGetU16Ptr(val);
	if (!u16) return 0;
	for (u32 i = 0; i < kw_len; i++) {
		if (u16[i] != (uint16_t)(unsigned char)kw[i]) return 0;
	}
	return 1;
}

// StyleSheet.transform(style) — converts CSS object properties to TextFormat
static ActionVar stylesheetTransform(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_UNDEFINED;

	// If no args, null, or undefined → return null
	if (arg_count == 0) { result.type = ACTION_STACK_VALUE_NULL; return result; }
	ActionVar* style = &args[0];
	if (style->type == ACTION_STACK_VALUE_NULL || style->type == ACTION_STACK_VALUE_UNDEFINED) {
		result.type = ACTION_STACK_VALUE_NULL;
		return result;
	}

	// Create a TextFormat object with defaults
	ASObject* tf = createBlankTextFormat(app_context);
	// Set display="block" default
	{
		u32 u16l;
		uint16_t* u16s = utf8_to_u16(app_context, "block", 5, &u16l);
		ActionVar dv = {0}; dv.type = ACTION_STACK_VALUE_STRING; dv.str_size = u16l; dv.data.numeric_value = (u64)u16s;
		setProperty(app_context, tf, "display", 7, &dv);
	}
	// Set kerning=false default
	{
		ActionVar kv = {0}; kv.type = ACTION_STACK_VALUE_BOOLEAN; kv.data.numeric_value = 0;
		setProperty(app_context, tf, "kerning", 7, &kv);
	}

	// If style is not an object, return the default TextFormat
	ASObject* style_obj = NULL;
	if (style->type == ACTION_STACK_VALUE_OBJECT && style->data.numeric_value != 0) {
		style_obj = (ASObject*)style->data.numeric_value;
	} else {
		result.type = ACTION_STACK_VALUE_OBJECT;
		result.data.numeric_value = (u64)tf;
		return result;
	}

	// --- color: "#RRGGBB" → integer ---
	ActionVar* cv = getProperty(style_obj, "color", 5);
	if (cv != NULL && cv->type == ACTION_STACK_VALUE_STRING && cv->str_size > 0) {
		const uint16_t* u16 = varGetU16Ptr(cv);
		if (u16 && u16[0] == '#' && cv->str_size == 7) {
			u32 color = 0;
			for (int i = 1; i <= 6; i++) {
				color <<= 4;
				uint16_t c = u16[i];
				if (c >= '0' && c <= '9') color |= (c - '0');
				else if (c >= 'a' && c <= 'f') color |= (c - 'a' + 10);
				else if (c >= 'A' && c <= 'F') color |= (c - 'A' + 10);
			}
			ActionVar cval = {0}; cval.type = ACTION_STACK_VALUE_F64;
			VAL(double, &cval.data.numeric_value) = (double)color;
			setProperty(app_context, tf, "color", 5, &cval);
		}
	}

	// --- fontSize → size: parse as i32, must be > 0 ---
	ActionVar* fsv = getProperty(style_obj, "fontSize", 8);
	if (fsv != NULL) {
		int32_t size = css_parse_i32(fsv);
		if (size > 0) {
			ActionVar sv = {0}; sv.type = ACTION_STACK_VALUE_F64;
			VAL(double, &sv.data.numeric_value) = (double)size;
			setProperty(app_context, tf, "size", 4, &sv);
		}
	}

	// --- fontFamily → font: truthiness gate, STRING → font list parse ---
	ActionVar* ffv = getProperty(style_obj, "fontFamily", 10);
	if (ffv != NULL && css_is_truthy(ffv)) {
		if (ffv->type == ACTION_STACK_VALUE_STRING) {
			const uint16_t* u16 = varGetU16Ptr(ffv);
			u32 len = ffv->str_size;
			if (u16 && len > 0) {
				// Parse font list: split by comma, trim leading spaces per item, remove empty items
				uint16_t* res = (uint16_t*)malloc((len + 1) * sizeof(uint16_t));
				u32 rlen = 0;
				u32 pos = 0;
				int first = 1;
				while (pos <= len) {
					u32 item_start = pos;
					while (pos < len && u16[pos] != ',') pos++;
					u32 item_end = pos;
					while (item_start < item_end && u16[item_start] == ' ') item_start++;
					if (item_start < item_end) {
						if (!first) res[rlen++] = ',';
						first = 0;
						memcpy(res + rlen, u16 + item_start, (item_end - item_start) * sizeof(uint16_t));
						rlen += item_end - item_start;
					}
					pos++;
				}
				// Create string ActionVar from processed font list
				char utf8_buf[1024];
				u32 utf8_len = (u32)u16_to_utf8(res, rlen, utf8_buf, sizeof(utf8_buf));
				char* utf8_heap = (char*)malloc(utf8_len + 1);
				memcpy(utf8_heap, utf8_buf, utf8_len);
				utf8_heap[utf8_len] = '\0';
				uint16_t* u16_heap = (uint16_t*)malloc((rlen + 1) * sizeof(uint16_t));
				memcpy(u16_heap, res, rlen * sizeof(uint16_t));
				u16_heap[rlen] = 0;
				ActionVar fval = {0}; fval.type = ACTION_STACK_VALUE_STRING; fval.str_size = rlen;
				fval.data.numeric_value = (u64)u16_heap;
				setProperty(app_context, tf, "font", 4, &fval);
				free(res);
				free(utf8_heap);
			}
		} else {
			// Non-string truthy value: set directly (trace coercion handles toString)
			setProperty(app_context, tf, "font", 4, ffv);
		}
	}

	// --- fontStyle → italic: "normal"→false, "italic"→true ---
	ActionVar* fsiv = getProperty(style_obj, "fontStyle", 9);
	if (fsiv != NULL && fsiv->type == ACTION_STACK_VALUE_STRING) {
		ActionVar bv = {0}; bv.type = ACTION_STACK_VALUE_BOOLEAN;
		if (css_str_eq(fsiv, "italic", 6)) {
			bv.data.numeric_value = 1;
			setProperty(app_context, tf, "italic", 6, &bv);
		} else if (css_str_eq(fsiv, "normal", 6)) {
			bv.data.numeric_value = 0;
			setProperty(app_context, tf, "italic", 6, &bv);
		}
	}

	// --- fontWeight → bold: "bold"→true, "normal"→false ---
	ActionVar* fwv = getProperty(style_obj, "fontWeight", 10);
	if (fwv != NULL && fwv->type == ACTION_STACK_VALUE_STRING) {
		ActionVar bv = {0}; bv.type = ACTION_STACK_VALUE_BOOLEAN;
		if (css_str_eq(fwv, "bold", 4)) {
			bv.data.numeric_value = 1;
			setProperty(app_context, tf, "bold", 4, &bv);
		} else if (css_str_eq(fwv, "normal", 6)) {
			bv.data.numeric_value = 0;
			setProperty(app_context, tf, "bold", 4, &bv);
		}
	}

	// --- textDecoration → underline: "underline"→true, "none"→false ---
	ActionVar* tdv = getProperty(style_obj, "textDecoration", 14);
	if (tdv != NULL && tdv->type == ACTION_STACK_VALUE_STRING) {
		ActionVar bv = {0}; bv.type = ACTION_STACK_VALUE_BOOLEAN;
		if (css_str_eq(tdv, "underline", 9)) {
			bv.data.numeric_value = 1;
			setProperty(app_context, tf, "underline", 9, &bv);
		} else if (css_str_eq(tdv, "none", 4)) {
			bv.data.numeric_value = 0;
			setProperty(app_context, tf, "underline", 9, &bv);
		}
	}

	// --- kerning: string "true"→true, else parse as i32 != 0 ---
	ActionVar* krv = getProperty(style_obj, "kerning", 7);
	if (krv != NULL) {
		ActionVar kbv = {0}; kbv.type = ACTION_STACK_VALUE_BOOLEAN;
		if (css_str_eq(krv, "true", 4)) {
			kbv.data.numeric_value = 1;
		} else {
			kbv.data.numeric_value = (css_parse_i32(krv) != 0) ? 1 : 0;
		}
		setProperty(app_context, tf, "kerning", 7, &kbv);
	}

	// --- leading: truthiness gate + parse as i32 ---
	ActionVar* ldv = getProperty(style_obj, "leading", 7);
	if (ldv != NULL && css_is_truthy(ldv)) {
		int32_t v = css_parse_i32(ldv);
		ActionVar nv = {0}; nv.type = ACTION_STACK_VALUE_F64;
		VAL(double, &nv.data.numeric_value) = (double)v;
		setProperty(app_context, tf, "leading", 7, &nv);
	}

	// --- letterSpacing: truthiness gate + parse as f64 (NaN stays NaN) ---
	ActionVar* lsv = getProperty(style_obj, "letterSpacing", 13);
	if (lsv != NULL && css_is_truthy(lsv)) {
		double v = css_parse_f64(lsv);
		ActionVar nv = {0}; nv.type = ACTION_STACK_VALUE_F64;
		VAL(double, &nv.data.numeric_value) = v;
		setProperty(app_context, tf, "letterSpacing", 13, &nv);
	}

	// --- marginLeft → leftMargin: truthiness gate + parse as i32 + max(0) ---
	ActionVar* mlv = getProperty(style_obj, "marginLeft", 10);
	if (mlv != NULL && css_is_truthy(mlv)) {
		int32_t v = css_parse_i32(mlv);
		if (v < 0) v = 0;
		ActionVar nv = {0}; nv.type = ACTION_STACK_VALUE_F64;
		VAL(double, &nv.data.numeric_value) = (double)v;
		setProperty(app_context, tf, "leftMargin", 10, &nv);
	}

	// --- marginRight → rightMargin: truthiness gate + parse as i32 + max(0) ---
	ActionVar* mrv = getProperty(style_obj, "marginRight", 11);
	if (mrv != NULL && css_is_truthy(mrv)) {
		int32_t v = css_parse_i32(mrv);
		if (v < 0) v = 0;
		ActionVar nv = {0}; nv.type = ACTION_STACK_VALUE_F64;
		VAL(double, &nv.data.numeric_value) = (double)v;
		setProperty(app_context, tf, "rightMargin", 11, &nv);
	}

	// --- textIndent → indent: truthiness gate + parse as i32 ---
	ActionVar* indv = getProperty(style_obj, "textIndent", 10);
	if (indv != NULL && css_is_truthy(indv)) {
		int32_t v = css_parse_i32(indv);
		ActionVar nv = {0}; nv.type = ACTION_STACK_VALUE_F64;
		VAL(double, &nv.data.numeric_value) = (double)v;
		setProperty(app_context, tf, "indent", 6, &nv);
	}

	// --- textAlign → align: case-insensitive match, lowercase output ---
	ActionVar* tav = getProperty(style_obj, "textAlign", 9);
	if (tav != NULL && tav->type == ACTION_STACK_VALUE_STRING && tav->str_size > 0 && tav->str_size <= 16) {
		const uint16_t* u16 = varGetU16Ptr(tav);
		if (u16) {
			uint16_t lower[16];
			u32 len = tav->str_size;
			for (u32 i = 0; i < len; i++)
				lower[i] = (u16[i] >= 'A' && u16[i] <= 'Z') ? u16[i] + 32 : u16[i];
			const char* align_str = NULL; u32 align_len = 0;
			if (len == 4 && lower[0]=='l' && lower[1]=='e' && lower[2]=='f' && lower[3]=='t') { align_str = "left"; align_len = 4; }
			else if (len == 6 && lower[0]=='c' && lower[1]=='e' && lower[2]=='n' && lower[3]=='t' && lower[4]=='e' && lower[5]=='r') { align_str = "center"; align_len = 6; }
			else if (len == 5 && lower[0]=='r' && lower[1]=='i' && lower[2]=='g' && lower[3]=='h' && lower[4]=='t') { align_str = "right"; align_len = 5; }
			else if (len == 7 && lower[0]=='j' && lower[1]=='u' && lower[2]=='s' && lower[3]=='t' && lower[4]=='i' && lower[5]=='f' && lower[6]=='y') { align_str = "justify"; align_len = 7; }
			if (align_str) {
				u32 u16al;
				uint16_t* u16a = utf8_to_u16(app_context, align_str, align_len, &u16al);
				ActionVar av = {0}; av.type = ACTION_STACK_VALUE_STRING; av.str_size = u16al; av.data.numeric_value = (u64)u16a;
				setProperty(app_context, tf, "align", 5, &av);
			}
		}
	}

	// --- display: case-sensitive match "inline"/"none", else keep "block" default ---
	ActionVar* dpv = getProperty(style_obj, "display", 7);
	if (dpv != NULL && dpv->type == ACTION_STACK_VALUE_STRING) {
		if (css_str_eq(dpv, "inline", 6) || css_str_eq(dpv, "none", 4)) {
			setProperty(app_context, tf, "display", 7, dpv);
		}
	}

	result.type = ACTION_STACK_VALUE_OBJECT;
	result.data.numeric_value = (u64)tf;
	return result;
}

// Helper: call this.transform(value) virtually (allows subclass override)
static ActionVar callStyleSheetTransform(SWFAppContext* app_context, ASObject* ss_obj, ActionVar* value) {
	// Look up "transform" on the object (may be overridden by user code)
	ActionVar* tfm = getPropertyWithPrototype(ss_obj, "transform", 9);
	if (tfm && tfm->type == ACTION_STACK_VALUE_FUNCTION && tfm->data.numeric_value) {
		ASFunction* func = (ASFunction*)tfm->data.numeric_value;
		ActionVar arg = value ? *value : (ActionVar){0};
		if (!value) arg.type = ACTION_STACK_VALUE_UNDEFINED;
		if (func->function_type == 2 && func->advanced_func) {
			// Set up scope chain + captured scopes for user overrides
			ASObject* local_scope = allocObject(app_context, 4);
			if (scope_depth < MAX_SCOPE_DEPTH) {
				scope_is_with[scope_depth] = 0;
				scope_mc[scope_depth] = NULL;
				scope_chain[scope_depth++] = local_scope;
			}
			// Restore captured scopes
			int _css_pushed = 0;
			for (int _cs = 0; _cs < func->captured_scope_count; _cs++) {
				if (func->captured_scope[_cs] != NULL && scope_depth < MAX_SCOPE_DEPTH) {
					scope_is_with[scope_depth] = 1;
					scope_mc[scope_depth] = func->captured_scope_mc[_cs];
					scope_chain[scope_depth++] = func->captured_scope[_cs];
					_css_pushed++;
				}
			}
			// Set this variable in scope
			ActionVar this_var = {0};
			this_var.type = ACTION_STACK_VALUE_OBJECT;
			this_var.data.numeric_value = (u64)ss_obj;
			setVariableByName("this", &this_var);

			g_call_depth++;
			ActionVar result = func->advanced_func(app_context, &arg, 1, NULL, ss_obj);
			g_call_depth--;

			// Pop captured scopes + local scope
			for (int _cs = 0; _cs < _css_pushed; _cs++) {
				if (scope_depth > 0) scope_depth--;
			}
			if (scope_depth > 0) scope_depth--;
			releaseObject(app_context, local_scope);
			return result;
		} else if (func->function_type == 1 && func->simple_func) {
			// Type 1 function — push arg onto stack
			if (value) {
				pushVar(app_context, value);
			} else {
				ActionVar udef = {0}; udef.type = ACTION_STACK_VALUE_UNDEFINED;
				pushVar(app_context, &udef);
			}
			g_call_depth++;
			ActionVar result = ((ActionVar(*)(SWFAppContext*))func->simple_func)(app_context);
			g_call_depth--;
			return result;
		}
	}
	// Fallback: call native transform
	ActionVar arg = value ? *value : (ActionVar){0};
	if (!value) arg.type = ACTION_STACK_VALUE_UNDEFINED;
	return stylesheetTransform(app_context, &arg, 1, NULL, ss_obj);
}

// Ensure _css and _styles exist on the object
static void ensureStyleSheetInternals(SWFAppContext* app_context, ASObject* ss_obj) {
	ActionVar* css_var = getProperty(ss_obj, "_css", 4);
	if (css_var == NULL || css_var->type != ACTION_STACK_VALUE_OBJECT) {
		ASObject* css_obj = allocObject(app_context, 8);
		// Set __proto__ so valueOf/toString are accessible (matches Ruffle's
		// ArrayBuilder::empty which creates an Array with full proto chain).
		setObjectProto(app_context, css_obj);
		ActionVar cv = {0}; cv.type = ACTION_STACK_VALUE_OBJECT; cv.data.numeric_value = (u64)css_obj;
		setProperty(app_context, ss_obj, "_css", 4, &cv);
	}
	ActionVar* styles_var = getProperty(ss_obj, "_styles", 7);
	if (styles_var == NULL || styles_var->type != ACTION_STACK_VALUE_OBJECT) {
		ASObject* styles_obj = allocObject(app_context, 8);
		setObjectProto(app_context, styles_obj);
		ActionVar sv = {0}; sv.type = ACTION_STACK_VALUE_OBJECT; sv.data.numeric_value = (u64)styles_obj;
		setProperty(app_context, ss_obj, "_styles", 7, &sv);
	}
}

// StyleSheet.setStyle(selector, styleObj)
static ActionVar stylesheetSetStyle(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)registers;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* ss_obj = (ASObject*)this_obj;
	if (ss_obj == NULL || arg_count < 2) return result;

	// Get selector name
	ActionVar* sel_arg = &args[0];
	if (sel_arg->type != ACTION_STACK_VALUE_STRING) return result;
	char sel_buf[256];
	u32 sel_len = (u32)u16_to_utf8(varGetU16Ptr(sel_arg), sel_arg->str_size, sel_buf, sizeof(sel_buf));

	ActionVar* value = &args[1];

	// Call this.transform(value) — virtual dispatch for ALL value types
	// Non-object values are passed as null to transform (Flash behavior)
	ActionVar null_tf_arg = {0}; null_tf_arg.type = ACTION_STACK_VALUE_NULL;
	ActionVar* tf_arg = (value->type == ACTION_STACK_VALUE_OBJECT) ? value : &null_tf_arg;
	ActionVar tf_result = callStyleSheetTransform(app_context, ss_obj, tf_arg);

	ensureStyleSheetInternals(app_context, ss_obj);
	ActionVar* css_var = getProperty(ss_obj, "_css", 4);
	ActionVar* styles_var = getProperty(ss_obj, "_styles", 7);

	if (value->type == ACTION_STACK_VALUE_OBJECT && value->data.numeric_value != 0) {
		// Shallow clone the CSS object for _css storage
		ASObject* orig = (ASObject*)value->data.numeric_value;
		ASObject* clone = allocObject(app_context, orig->num_used + 4);
		for (u32 ci = 0; ci < orig->num_used; ci++) {
			ASProperty* sp = &orig->properties[ci];
			setPropertyWithFlags(app_context, clone, sp->name, sp->name_length, &sp->value, sp->flags);
		}
		ActionVar clone_var = {0}; clone_var.type = ACTION_STACK_VALUE_OBJECT;
		clone_var.data.numeric_value = (u64)clone;

		if (css_var && css_var->type == ACTION_STACK_VALUE_OBJECT) {
			ASObject* css_obj = (ASObject*)css_var->data.numeric_value;
			setProperty(app_context, css_obj, sel_buf, sel_len, &clone_var);
		}
		if (styles_var && styles_var->type == ACTION_STACK_VALUE_OBJECT) {
			ASObject* styles_obj = (ASObject*)styles_var->data.numeric_value;
			setProperty(app_context, styles_obj, sel_buf, sel_len, &tf_result);
		}
	} else {
		// Non-object values: store null in _css, don't store in _styles
		ActionVar null_var = {0}; null_var.type = ACTION_STACK_VALUE_NULL;
		if (css_var && css_var->type == ACTION_STACK_VALUE_OBJECT) {
			ASObject* css_obj = (ASObject*)css_var->data.numeric_value;
			setProperty(app_context, css_obj, sel_buf, sel_len, &null_var);
		}
	}

	return result;
}

// StyleSheet.getStyle(selector) — returns raw CSS object or null
static ActionVar stylesheetGetStyle(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)registers; (void)app_context;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_NULL;
	ASObject* ss_obj = (ASObject*)this_obj;
	if (ss_obj == NULL || arg_count < 1) return result;

	ActionVar* sel_arg = &args[0];
	if (sel_arg->type != ACTION_STACK_VALUE_STRING) return result;
	char sel_buf[256];
	u32 sel_len = (u32)u16_to_utf8(varGetU16Ptr(sel_arg), sel_arg->str_size, sel_buf, sizeof(sel_buf));

	ActionVar* css_var = getProperty(ss_obj, "_css", 4);
	if (css_var == NULL || css_var->type != ACTION_STACK_VALUE_OBJECT) return result;
	ASObject* css_obj = (ASObject*)css_var->data.numeric_value;
	ActionVar* val = getProperty(css_obj, sel_buf, sel_len);
	if (val != NULL && val->type == ACTION_STACK_VALUE_OBJECT) return *val;
	return result; // null
}

// StyleSheet.getStyleNames() — returns Array of selector names
static ActionVar stylesheetGetStyleNames(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)args; (void)arg_count; (void)registers;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* ss_obj = (ASObject*)this_obj;
	if (ss_obj == NULL) return result;

	ActionVar* css_var = getProperty(ss_obj, "_css", 4);
	if (css_var == NULL || css_var->type != ACTION_STACK_VALUE_OBJECT) {
		// Return empty array when no _css exists
		ASObject* empty_arr = allocObject(app_context, 4);
		empty_arr->native_type = NATIVE_ARRAY;
		setObjectProto(app_context, empty_arr);
		ActionVar len_val = {0}; len_val.type = ACTION_STACK_VALUE_F64;
		VAL(double, &len_val.data.numeric_value) = 0.0;
		setProperty(app_context, empty_arr, "length", 6, &len_val);
		result.type = ACTION_STACK_VALUE_OBJECT;
		result.data.numeric_value = (u64)empty_arr;
		return result;
	}
	ASObject* css_obj = (ASObject*)css_var->data.numeric_value;

	// Create an array with all selector names
	ASObject* arr = allocObject(app_context, css_obj->num_used + 4);
	arr->native_type = NATIVE_ARRAY;
	setObjectProto(app_context, arr);
	u32 idx = 0;
	for (u32 i = 0; i < css_obj->num_used; i++) {
		if (css_obj->properties[i].name[0] == '\0') continue;
		if (strcmp(css_obj->properties[i].name, "__proto__") == 0) continue;
		char idx_str[12];
		int idx_len = snprintf(idx_str, sizeof(idx_str), "%u", idx);
		// Convert property name to u16 string
		const char* pname = css_obj->properties[i].name;
		u32 pname_len = (u32)strlen(pname);
		u32 u16_name_len;
		uint16_t* u16_name = utf8_to_u16(app_context, pname, pname_len, &u16_name_len);
		ActionVar sv = {0}; sv.type = ACTION_STACK_VALUE_STRING;
		sv.data.numeric_value = (u64)u16_name;
		sv.str_size = u16_name_len;
		setProperty(app_context, arr, idx_str, (u32)idx_len, &sv);
		idx++;
	}
	// Set length
	ActionVar len_val = {0}; len_val.type = ACTION_STACK_VALUE_F64;
	VAL(double, &len_val.data.numeric_value) = (double)idx;
	setProperty(app_context, arr, "length", 6, &len_val);

	result.type = ACTION_STACK_VALUE_OBJECT;
	result.data.numeric_value = (u64)arr;
	return result;
}

// StyleSheet.clear()
static ActionVar stylesheetClear(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)args; (void)arg_count; (void)registers;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* ss_obj = (ASObject*)this_obj;
	if (ss_obj == NULL) return result;

	// Replace _css and _styles with new empty objects (with proto chain so
	// Object.prototype.valueOf is reachable, matching Ruffle's ArrayBuilder).
	ASObject* new_css = allocObject(app_context, 4);
	setObjectProto(app_context, new_css);
	ASObject* new_styles = allocObject(app_context, 4);
	setObjectProto(app_context, new_styles);
	ActionVar cv = {0}; cv.type = ACTION_STACK_VALUE_OBJECT; cv.data.numeric_value = (u64)new_css;
	ActionVar sv = {0}; sv.type = ACTION_STACK_VALUE_OBJECT; sv.data.numeric_value = (u64)new_styles;
	setProperty(app_context, ss_obj, "_css", 4, &cv);
	setProperty(app_context, ss_obj, "_styles", 7, &sv);
	return result;
}

// StyleSheet.parseCSS(cssText) — parse CSS text and add styles
// Flash CSS parser: property name scan does NOT stop at }, {, or ; — only at : and whitespace.
// Body delimited by first { and matching }; property names can span past } characters.
static ActionVar stylesheetParseCSS(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)registers;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_BOOLEAN; result.data.numeric_value = 0; // false
	ASObject* ss_obj = (ASObject*)this_obj;
	if (ss_obj == NULL || arg_count < 1) return result;

	ActionVar* css_arg = &args[0];
	if (css_arg->type != ACTION_STACK_VALUE_STRING) return result;

	const uint16_t* src = varGetU16Ptr(css_arg);
	u32 src_len = css_arg->str_size;
	if (src == NULL || src_len == 0) return result;

	// Convert u16 to utf8 for parsing
	char* css_text = (char*)malloc(src_len * 4 + 1);
	u32 text_len = (u32)u16_to_utf8(src, src_len, css_text, src_len * 4 + 1);

#define IS_CSS_WS(c) ((c) == ' ' || (c) == '\t' || (c) == '\n' || (c) == '\r')

	typedef struct { char name[256]; u32 name_len; ASObject* style; } ParsedRule;
	ParsedRule parsed_rules[64];
	u32 rule_count = 0;
	int parse_valid = 1;

	u32 pos = 0;
	while (pos < text_len && parse_valid) {
		// Skip whitespace
		while (pos < text_len && IS_CSS_WS(css_text[pos])) pos++;
		if (pos >= text_len) break;

		// Find selector: everything up to first '{'
		u32 sel_start = pos;
		while (pos < text_len && css_text[pos] != '{') pos++;
		if (pos >= text_len) { parse_valid = 0; break; }

		u32 sel_end = pos;
		while (sel_end > sel_start && IS_CSS_WS(css_text[sel_end - 1])) sel_end--;

		pos++; // skip '{'
		u32 bp = pos; // body parsing position

		// Parse properties: scan for ':' in remaining text (past }, {, ; chars)
		ASObject* style_obj = allocObject(app_context, 8);
		int has_error = 0;
		int block_closed = 0;
		int props_parsed = 0;

		while (!has_error && !block_closed) {
			// Skip whitespace
			while (bp < text_len && IS_CSS_WS(css_text[bp])) bp++;
			if (bp >= text_len) break; // EOF
			if (css_text[bp] == '}') { bp++; block_closed = 1; break; }

			// Scan for ':' (does NOT stop at }, {, ;, or anything else)
			u32 colon_pos = bp;
			while (colon_pos < text_len && css_text[colon_pos] != ':') colon_pos++;

			if (colon_pos >= text_len) {
				// No ':' found in remaining text
				// Find the next '}' if any
				u32 brace = bp;
				while (brace < text_len && css_text[brace] != '}') brace++;
				u32 check_end = (brace < text_len) ? brace : text_len;

				// Check if content between bp and check_end has non-whitespace → error
				int has_nonws = 0;
				for (u32 i = bp; i < check_end; i++) {
					if (!IS_CSS_WS(css_text[i])) { has_nonws = 1; break; }
				}
				if (has_nonws) { has_error = 1; }
				if (brace < text_len) { bp = brace + 1; block_closed = 1; }
				else bp = text_len;
				break;
			}

			// ':' found at colon_pos
			// Property name: from bp to colon_pos
			u32 name_start = bp;
			u32 name_end = colon_pos;

			// Check for internal spaces in property name
			// Rule: trailing spaces before ':' are OK, internal spaces (space then non-space before ':') are error
			{
				u32 fs = name_start;
				while (fs < name_end && css_text[fs] != ' ' && css_text[fs] != '\t') fs++;
				if (fs < name_end) {
					// Space found at fs — skip all whitespace
					u32 after_ws = fs;
					while (after_ws < name_end && (css_text[after_ws] == ' ' || css_text[after_ws] == '\t')) after_ws++;
					if (after_ws < name_end) {
						// Non-whitespace after space before colon → internal space → error
						has_error = 1; break;
					}
					// Trailing spaces only → OK (name includes them)
				}
			}

			u32 pn_len = name_end - name_start;

			// Convert CSS dash-names to camelCase
			char camel_name[256];
			u32 ci2 = 0, co2 = 0;
			while (ci2 < pn_len && co2 < sizeof(camel_name) - 1) {
				if (css_text[name_start + ci2] == '-') {
					if (ci2 + 1 < pn_len && css_text[name_start + ci2 + 1] == '-') {
						camel_name[co2++] = '-';
						ci2 += 2;
					} else if (ci2 > 0 && ci2 + 1 < pn_len) {
						ci2++;
						char c = css_text[name_start + ci2];
						if (c >= 'a' && c <= 'z') c -= 32;
						camel_name[co2++] = c;
						ci2++;
					} else {
						camel_name[co2++] = css_text[name_start + ci2];
						ci2++;
					}
				} else {
					camel_name[co2++] = css_text[name_start + ci2];
					ci2++;
				}
			}
			camel_name[co2] = '\0';
			u32 camel_len = co2;

			bp = colon_pos + 1; // skip ':'

			// Skip leading whitespace from value
			while (bp < text_len && IS_CSS_WS(css_text[bp])) bp++;

			// Scan value until ';' or '}'
			u32 val_start = bp;
			while (bp < text_len && css_text[bp] != ';' && css_text[bp] != '}') bp++;
			u32 val_end = bp;

			if (bp < text_len && css_text[bp] == ';') {
				bp++; // skip ';'
			} else if (bp < text_len && css_text[bp] == '}') {
				bp++; block_closed = 1;
			} else {
				// EOF without ';' or '}' → error (unclosed value)
				has_error = 1; break;
			}

			// Store property on style object
			u32 vlen = val_end - val_start;
			u32 u16_vlen;
			uint16_t* u16_val = utf8_to_u16(app_context, css_text + val_start, vlen, &u16_vlen);
			ActionVar pval = {0}; pval.type = ACTION_STACK_VALUE_STRING;
			pval.data.numeric_value = (u64)u16_val;
			pval.str_size = u16_vlen;
			if (camel_len > 0) {
				setProperty(app_context, style_obj, camel_name, camel_len, &pval);
			}
			props_parsed++;
		}

		if (has_error) { parse_valid = 0; releaseObject(app_context, style_obj); break; }

		// Advance pos past body
		pos = bp;

		// Selector validation and storage
		if (sel_end <= sel_start) continue;

		// Split selectors by comma
		u32 s = sel_start;
		while (s < sel_end) {
			u32 se = s;
			while (se < sel_end && css_text[se] != ',') se++;

			u32 ss = s;
			while (ss < se && IS_CSS_WS(css_text[ss])) ss++;
			u32 sse = se;
			while (sse > ss && IS_CSS_WS(css_text[sse - 1])) sse--;

			if (sse > ss) {
				char sel_name[256];
				u32 sel_name_len = sse - ss;
				if (sel_name_len >= sizeof(sel_name)) sel_name_len = sizeof(sel_name) - 1;
				memcpy(sel_name, css_text + ss, sel_name_len);
				sel_name[sel_name_len] = '\0';

				// Check for spaces in selector name
				int has_space = 0;
				for (u32 ci = 0; ci < sel_name_len; ci++) {
					if (sel_name[ci] == ' ' || sel_name[ci] == '\t') { has_space = 1; break; }
				}
				if (has_space) { parse_valid = 0; break; }

				if (rule_count < 64) {
					memcpy(parsed_rules[rule_count].name, sel_name, sel_name_len + 1);
					parsed_rules[rule_count].name_len = sel_name_len;
					parsed_rules[rule_count].style = style_obj;
					retainObject(style_obj); // shared across comma-separated selectors
					rule_count++;
				}
			}
			s = se + 1;
		}
		releaseObject(app_context, style_obj); // balance the initial alloc
	}

#undef IS_CSS_WS

	// Phase 2: Apply rules only if parse was fully valid
	if (parse_valid && rule_count > 0) {
		ensureStyleSheetInternals(app_context, ss_obj);
		for (u32 ri = 0; ri < rule_count; ri++) {
			ActionVar style_val = {0}; style_val.type = ACTION_STACK_VALUE_OBJECT;
			style_val.data.numeric_value = (u64)parsed_rules[ri].style;

			ActionVar tf_result = callStyleSheetTransform(app_context, ss_obj, &style_val);

			ActionVar* css_prop = getProperty(ss_obj, "_css", 4);
			ActionVar* styles_prop = getProperty(ss_obj, "_styles", 7);
			if (css_prop && css_prop->type == ACTION_STACK_VALUE_OBJECT) {
				ASObject* css_o = (ASObject*)css_prop->data.numeric_value;
				setProperty(app_context, css_o, parsed_rules[ri].name, parsed_rules[ri].name_len, &style_val);
			}
			if (styles_prop && styles_prop->type == ACTION_STACK_VALUE_OBJECT) {
				ASObject* styles_o = (ASObject*)styles_prop->data.numeric_value;
				setProperty(app_context, styles_o, parsed_rules[ri].name, parsed_rules[ri].name_len, &tf_result);
			}
		}
		result.data.numeric_value = 1; // true
	}

	free(css_text);
	return result;
}

// StyleSheet.load(url) — stub
static ActionVar stylesheetLoad(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj) {
	(void)app_context; (void)args; (void)arg_count; (void)registers; (void)this_obj;
	ActionVar result = {0}; result.type = ACTION_STACK_VALUE_UNDEFINED;
	return result;
}

static ActionVar builtin_stylesheet_constructor(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)app_context; (void)args; (void)arg_count; (void)registers;
	if (this_obj != NULL) {
		ASObject* obj = (ASObject*)this_obj;
		if (obj->native_type == NATIVE_NONE)
			obj->native_type = NATIVE_STYLESHEET;
	}
	ActionVar r = {0}; r.type = ACTION_STACK_VALUE_UNDEFINED; return r;
}

static void initStyleSheetPrototype(SWFAppContext* app_context) {
	if (g_stylesheet_constructor_init) return;

	memset(&g_stylesheet_constructor_global, 0, sizeof(ASFunction));
	strncpy(g_stylesheet_constructor_global.name, "StyleSheet", 255);
	g_stylesheet_constructor_global.function_type = 2;
	g_stylesheet_constructor_global.advanced_func = (Function2Ptr)builtin_stylesheet_constructor;

	// Create prototype
	g_stylesheet_prototype = allocObject(app_context, 16);

	// Set __proto__ to Object.prototype
	extern ASObject* g_object_prototype;
	if (g_object_prototype != NULL) {
		ActionVar pv = {0}; pv.type = ACTION_STACK_VALUE_OBJECT;
		pv.data.numeric_value = (u64)g_object_prototype;
		setProperty(app_context, g_stylesheet_prototype, "__proto__", 9, &pv);
	}

	// Register methods on prototype with DONT_ENUM | DONT_DELETE | READ_ONLY flags (=0x00)
	registerGeomMethod(&g_ss_methods[0], "transform",     (Function2Ptr)stylesheetTransform,     app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[1], "setStyle",      (Function2Ptr)stylesheetSetStyle,      app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[2], "getStyle",      (Function2Ptr)stylesheetGetStyle,      app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[3], "getStyleNames", (Function2Ptr)stylesheetGetStyleNames, app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[4], "clear",         (Function2Ptr)stylesheetClear,         app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[5], "parseCSS",      (Function2Ptr)stylesheetParseCSS,      app_context, g_stylesheet_prototype);
	registerGeomMethod(&g_ss_methods[6], "load",          (Function2Ptr)stylesheetLoad,          app_context, g_stylesheet_prototype);
	// "parse" is an alias for parseCSS
	registerGeomMethod(&g_ss_methods[7], "parse",         (Function2Ptr)stylesheetParseCSS,      app_context, g_stylesheet_prototype);

	// Set flags to DONT_ENUM | DONT_DELETE | READ_ONLY (= 0, no flags set)
	for (u32 i = 0; i < g_stylesheet_prototype->num_used; i++) {
		char* pname = g_stylesheet_prototype->properties[i].name;
		if (strcmp(pname, "__proto__") == 0) {
			g_stylesheet_prototype->properties[i].flags &= ~PROPERTY_FLAG_ENUMERABLE;
			continue;
		}
		// Clear all flags for methods
		g_stylesheet_prototype->properties[i].flags = 0;
	}

	g_stylesheet_constructor_global.prototype_obj = g_stylesheet_prototype;
	if (function_count < MAX_FUNCTIONS)
		function_registry[function_count++] = &g_stylesheet_constructor_global;

	g_stylesheet_constructor_init = 1;
}

// ============================================================
// TextFormat constructor and property coercion
// ============================================================
static ASFunction g_textformat_constructor;
static int g_textformat_constructor_init = 0;

// TextFormat property names (19 properties)
static const char* tf_prop_names[] = {
	"font", "size", "color", "bold", "italic", "underline",
	"align", "leftMargin", "rightMargin", "indent", "leading",
	"blockIndent", "bullet", "kerning", "letterSpacing", "tabStops",
	"url", "target", "display"
};
static const u32 tf_prop_lens[] = {
	4, 4, 5, 4, 6, 9,
	5, 10, 11, 6, 7,
	11, 6, 7, 13, 8,
	3, 6, 7
};
#define TF_PROP_COUNT 19
#define TF_FONT_MAX_LENGTH 64

// Coercion type enum
enum TFCoercionType {
	TF_COERCE_NONE = 0,
	TF_COERCE_STRING,     // font, url, target
	TF_COERCE_INTEGER,    // size, indent, leading, blockIndent
	TF_COERCE_NONNEG_INT, // leftMargin, rightMargin
	TF_COERCE_UNSIGNED,   // color
	TF_COERCE_FLOAT,      // letterSpacing
	TF_COERCE_BOOLEAN,    // bold, italic, underline, bullet, kerning
	TF_COERCE_ALIGN,      // align
	TF_COERCE_TABSTOPS,   // tabStops
	TF_COERCE_DISPLAY,    // display
};

static int getTextFormatCoercionType(const char* name, u32 len) {
	if (len == 4 && strncmp(name, "font", 4) == 0) return TF_COERCE_STRING;
	if (len == 3 && strncmp(name, "url", 3) == 0) return TF_COERCE_STRING;
	if (len == 6 && strncmp(name, "target", 6) == 0) return TF_COERCE_STRING;
	if (len == 4 && strncmp(name, "size", 4) == 0) return TF_COERCE_INTEGER;
	// SWF7 and below: indent/leading/blockIndent clamp negative to 0
	// SWF8+: allow negative values (plain integer coercion)
	if (len == 6 && strncmp(name, "indent", 6) == 0) return (g_swf_version < 8) ? TF_COERCE_NONNEG_INT : TF_COERCE_INTEGER;
	if (len == 7 && strncmp(name, "leading", 7) == 0) return (g_swf_version < 8) ? TF_COERCE_NONNEG_INT : TF_COERCE_INTEGER;
	if (len == 11 && strncmp(name, "blockIndent", 11) == 0) return (g_swf_version < 8) ? TF_COERCE_NONNEG_INT : TF_COERCE_INTEGER;
	if (len == 10 && strncmp(name, "leftMargin", 10) == 0) return TF_COERCE_NONNEG_INT;
	if (len == 11 && strncmp(name, "rightMargin", 11) == 0) return TF_COERCE_NONNEG_INT;
	if (len == 5 && strncmp(name, "color", 5) == 0) return TF_COERCE_UNSIGNED;
	if (len == 13 && strncmp(name, "letterSpacing", 13) == 0) return TF_COERCE_FLOAT;
	if (len == 4 && strncmp(name, "bold", 4) == 0) return TF_COERCE_BOOLEAN;
	if (len == 6 && strncmp(name, "italic", 6) == 0) return TF_COERCE_BOOLEAN;
	if (len == 9 && strncmp(name, "underline", 9) == 0) return TF_COERCE_BOOLEAN;
	if (len == 6 && strncmp(name, "bullet", 6) == 0) return TF_COERCE_BOOLEAN;
	if (len == 7 && strncmp(name, "kerning", 7) == 0) return TF_COERCE_BOOLEAN;
	if (len == 5 && strncmp(name, "align", 5) == 0) return TF_COERCE_ALIGN;
	if (len == 8 && strncmp(name, "tabStops", 8) == 0) return TF_COERCE_TABSTOPS;
	if (len == 7 && strncmp(name, "display", 7) == 0) return TF_COERCE_DISPLAY;
	return TF_COERCE_NONE;
}

// Helper: check if an ASObject is a TextFormat instance
static int isTextFormatInstance(ASObject* obj) {
	if (!g_textformat_constructor_init || g_textformat_constructor.prototype_obj == NULL) return 0;
	ActionVar* proto_var = getProperty(obj, "__proto__", 9);
	if (proto_var == NULL || proto_var->type != ACTION_STACK_VALUE_OBJECT) return 0;
	return (ASObject*)proto_var->data.numeric_value == g_textformat_constructor.prototype_obj;
}

// Banker's rounding (round half to even)
static double bankersRound(double x) {
	if (x != x) return x; // NaN
	double f = x - floor(x); // fractional part in [0, 1)
	if (fabs(f - 0.5) < 1e-10) {
		// Exactly 0.5 — round to even
		double down = floor(x);
		double up = down + 1.0;
		if (fmod(fabs(down), 2.0) < 0.5) return down; // down is even
		return up;
	}
	return round(x);
}

// Coerce value for TextFormat integer property (size, indent, leading, blockIndent)
static ActionVar tfCoerceInteger(SWFAppContext* app_context, ActionVar* value) {
	ActionVar result = {0};
	if (value->type == ACTION_STACK_VALUE_NULL || value->type == ACTION_STACK_VALUE_UNDEFINED) {
		result.type = ACTION_STACK_VALUE_NULL;
		return result;
	}
	double d = 0;
	if (value->type == ACTION_STACK_VALUE_F64)
		d = VAL(double, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_F32)
		d = (double) VAL(float, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_BOOLEAN)
		d = value->data.numeric_value ? 1.0 : 0.0;
	else if (value->type == ACTION_STACK_VALUE_STRING) {
		char _vtd_buf[512];
		const uint16_t* _vtd_u16 = varGetU16Ptr(value);
		u16_to_utf8(_vtd_u16, value->str_size, _vtd_buf, sizeof(_vtd_buf));
		d = atof(_vtd_buf);
	}
	else if (value->type == ACTION_STACK_VALUE_OBJECT) {
		int _vof_found = 0;
		ActionVar vof = objectCallValueOf(app_context, value, &_vof_found);
		if (vof.type == ACTION_STACK_VALUE_F64)
			d = VAL(double, &vof.data.numeric_value);
		else if (vof.type == ACTION_STACK_VALUE_F32)
			d = (double) VAL(float, &vof.data.numeric_value);
		else
			d = 0.0 / 0.0; // NaN
	} else {
		d = 0.0 / 0.0; // NaN
	}
	// NaN, ±Infinity → -2147483648
	if (d != d || d == (1.0/0.0) || d == -(1.0/0.0)) {
		result.type = ACTION_STACK_VALUE_F64;
		double v = -2147483648.0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	if (g_swf_version < 8)
		d = (d >= 0) ? floor(d) : -floor(-d); // SWF7 and below: truncate toward zero
	else
		d = bankersRound(d); // SWF8+: banker's rounding (round half to even)
	// Out of int32 range → -2147483648
	if (d > 2147483647.0 || d < -2147483648.0) {
		result.type = ACTION_STACK_VALUE_F64;
		double v = -2147483648.0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	result.type = ACTION_STACK_VALUE_F64;
	double v = (double)(s32)d;
	result.data.numeric_value = VAL(u64, &v);
	return result;
}

// Coerce for non-negative integer (leftMargin, rightMargin)
static ActionVar tfCoerceNonNegInt(SWFAppContext* app_context, ActionVar* value) {
	ActionVar result = {0};
	if (value->type == ACTION_STACK_VALUE_NULL || value->type == ACTION_STACK_VALUE_UNDEFINED) {
		result.type = ACTION_STACK_VALUE_NULL;
		return result;
	}
	double d = 0;
	if (value->type == ACTION_STACK_VALUE_F64)
		d = VAL(double, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_F32)
		d = (double) VAL(float, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_BOOLEAN)
		d = value->data.numeric_value ? 1.0 : 0.0;
	else if (value->type == ACTION_STACK_VALUE_STRING) {
		char _vtd_buf[512];
		const uint16_t* _vtd_u16 = varGetU16Ptr(value);
		u16_to_utf8(_vtd_u16, value->str_size, _vtd_buf, sizeof(_vtd_buf));
		d = atof(_vtd_buf);
	}
	else if (value->type == ACTION_STACK_VALUE_OBJECT) {
		int _vof_found = 0;
		ActionVar vof = objectCallValueOf(app_context, value, &_vof_found);
		if (vof.type == ACTION_STACK_VALUE_F64)
			d = VAL(double, &vof.data.numeric_value);
		else if (vof.type == ACTION_STACK_VALUE_F32)
			d = (double) VAL(float, &vof.data.numeric_value);
		else
			d = 0.0 / 0.0;
	} else {
		d = 0.0 / 0.0;
	}
	result.type = ACTION_STACK_VALUE_F64;
	// NaN → 0
	if (d != d) {
		double v = 0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	// +Infinity → -2147483648 (positive overflow, not clamped)
	if (d == (1.0/0.0)) {
		double v = -2147483648.0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	// -Infinity → 0 (negative, clamped)
	if (d == -(1.0/0.0)) {
		double v = 0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	if (g_swf_version < 8)
		d = (d >= 0) ? floor(d) : -floor(-d); // SWF7: truncate toward zero
	else
		d = bankersRound(d); // SWF8+: banker's rounding
	// Positive overflow → -2147483648
	if (d > 2147483647.0) {
		double v = -2147483648.0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	// Negative (including large negative overflow) → 0
	if (d < 0) {
		double v = 0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	double v = (double)(s32)d;
	result.data.numeric_value = VAL(u64, &v);
	return result;
}

// Coerce for unsigned integer (color)
static ActionVar tfCoerceUnsigned(SWFAppContext* app_context, ActionVar* value) {
	ActionVar result = {0};
	if (value->type == ACTION_STACK_VALUE_NULL || value->type == ACTION_STACK_VALUE_UNDEFINED) {
		result.type = ACTION_STACK_VALUE_NULL;
		return result;
	}
	double d = 0;
	if (value->type == ACTION_STACK_VALUE_F64)
		d = VAL(double, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_F32)
		d = (double) VAL(float, &value->data.numeric_value);
	else if (value->type == ACTION_STACK_VALUE_BOOLEAN)
		d = value->data.numeric_value ? 1.0 : 0.0;
	else if (value->type == ACTION_STACK_VALUE_STRING) {
		char _vtd_buf[512];
		const uint16_t* _vtd_u16 = varGetU16Ptr(value);
		u16_to_utf8(_vtd_u16, value->str_size, _vtd_buf, sizeof(_vtd_buf));
		d = atof(_vtd_buf);
	}
	else if (value->type == ACTION_STACK_VALUE_OBJECT) {
		int _vof_found = 0;
		ActionVar vof = objectCallValueOf(app_context, value, &_vof_found);
		if (vof.type == ACTION_STACK_VALUE_F64)
			d = VAL(double, &vof.data.numeric_value);
		else if (vof.type == ACTION_STACK_VALUE_F32)
			d = (double) VAL(float, &vof.data.numeric_value);
		else
			d = 0.0 / 0.0;
	} else {
		d = 0.0 / 0.0;
	}
	// NaN, ±Infinity → 0
	if (d != d || d == (1.0/0.0) || d == -(1.0/0.0)) {
		result.type = ACTION_STACK_VALUE_F64;
		double v = 0;
		result.data.numeric_value = VAL(u64, &v);
		return result;
	}
	// ECMAScript ToUint32: truncate toward zero, then mod 2^32
	double truncated = (d >= 0) ? floor(d) : -floor(-d);
	double mod = fmod(truncated, 4294967296.0);
	if (mod < 0) mod += 4294967296.0;
	result.type = ACTION_STACK_VALUE_F64;
	result.data.numeric_value = VAL(u64, &mod);
	return result;
}

