		obj->native_type = NATIVE_FILTER;
		ActionVar v;
		v = makeF64(bx); setProperty(app_context, obj, "blurX", 5, &v);
		v = makeF64(by); setProperty(app_context, obj, "blurY", 5, &v);
		v = makeF64(quality); setProperty(app_context, obj, "quality", 7, &v);
