				MovieClip* _rmc_parent = mc->parent ? mc->parent : &root_movieclip;
				if (_rmc_parent->dynamic_props != NULL && mc->name[0]) {
					deleteProperty(app_context, (ASObject*)_rmc_parent->dynamic_props,
					               mc->name, strlen(mc->name));
				}
